    private TouchControlsNowPlayingUiModel buildTouchControlsNowPlayingUiModel(ChannelItem channel) {
        if (channel == null) {
            return TouchControlsNowPlayingUiModel.EMPTY;
        }
        if (channel.isVod && !isU7dReplayItem(channel)) {
            long positionMs = playerController == null ? 0L : Math.max(0L, playerController.getCurrentPlaybackPosition());
            long durationMs = PlaybackFinishEstimate.duration(playerController == null ? 0L : playerController.getHudVodDurationMs(channel.id), channel.vodDurationSeconds);
            int progress = durationMs <= 0L ? 0 : (int) Math.min(100d, (positionMs * 100d) / durationMs);
            String remaining = durationMs > positionMs
                    ? getString(R.string.zap_banner_remaining, formatDurationShort(durationMs - positionMs))
                    : "";
            TouchControlsNowPlayingUiModel model = new TouchControlsNowPlayingUiModel(
                    true,
                    channel.logoUrl,
                    "",
                    getString(R.string.tools_section_vod),
                    displayName(channel),
                    buildVodInfoMeta(channel),
                    "",
                    false,
                    channel.logoUrl,
                    remaining,
                    progress,
                    durationMs > 0L,
                    "",
                    playerController == null ? "" : playerController.getPlaybackTrackInfo(channel.id)
            );
            model.estimatedFinishAtMs = playerController == null ? 0L : playerController.getVodFinishEstimate(channel.id, System.currentTimeMillis());
            return model;
        }
        if (isU7dReplayItem(channel)) {
            String programTitle = channel.nowProgram == null || channel.nowProgram.trim().isEmpty()
                    ? displayName(channel)
                    : channel.nowProgram.trim();
            TouchControlsNowPlayingUiModel model = new TouchControlsNowPlayingUiModel(
                    true,
                    channel.logoUrl,
                    "",
                    getString(R.string.u7d_replay_group),
                    programTitle,
                    buildVodInfoMeta(channel),
                    "",
                    false,
                    channel.logoUrl,
                    "",
                    0,
                    false,
                    ""
            );
            model.playbackTrackInfo = playerController == null ? "" : playerController.getPlaybackTrackInfo(channel.id);
            model.programmeMetadata=currentPlaybackU7dPreviewEntry==null?null:currentPlaybackU7dPreviewEntry.programmeMetadata;
            return model;
        }
        ensureTouchControlsEpgPair(channel);
        EpgRepository.EpgProgramPair pair = normalizedEpgPair(channel.id);
        EpgRepository.EpgProgram currentProgram = pair == null ? null : pair.current;
        EpgRepository.EpgProgram nextProgram = pair == null ? null : pair.next;
        String currentTitle = currentProgram != null && currentProgram.title != null && !currentProgram.title.trim().isEmpty()
                ? currentProgram.title.trim()
                : (channel.nowProgram == null ? "" : channel.nowProgram.trim());
        String nextTitle = nextProgram != null && nextProgram.title != null && !nextProgram.title.trim().isEmpty()
                ? nextProgram.title.trim()
                : (channel.nextProgram == null ? "" : channel.nextProgram.trim());
        int progress = currentProgram == null ? 0 : Math.max(0, Math.min(100, currentProgram.progress));
        boolean progressVisible = currentProgram != null && currentProgram.progress >= 0;
        long endMs = currentProgram == null ? 0L : parseIsoMillis(currentProgram.endTime);
        long nowMs = System.currentTimeMillis();
        String remainingText = progressVisible && endMs > nowMs
                ? getString(R.string.zap_banner_remaining, formatDurationShort(endMs - nowMs))
                : "";
        String endTimeText = currentProgram == null ? "" : shortTime(currentProgram.endTime);
        String nextLabel = nextTitle.isEmpty() ? "" : getString(R.string.zap_banner_next_prefix) + ": " + nextTitle;
        TouchControlsNowPlayingUiModel model = new TouchControlsNowPlayingUiModel(
                true,
                channel.logoUrl,
                buildZapChannelBadge(channel),
                displayName(channel),
                currentTitle.isEmpty() ? getString(R.string.zap_banner_epg_missing) : currentTitle,
                buildZapProgramMeta(channel, currentProgram),
                nextLabel,
                !nextLabel.isEmpty(),
                ProgramArtworkResolver.resolve(currentProgram, channel),
                remainingText,
                progress,
                progressVisible,
                endTimeText
        );
        model.playbackTrackInfo = playerController == null ? "" : playerController.getPlaybackTrackInfo(channel.id);
        model.programmeMetadata=programmeMetadata(channel,currentProgram);
        return model;
    }

    private void ensureTouchControlsEpgPair(ChannelItem channel) {
        if (channel == null || channel.isVod || isU7dReplayItem(channel) || epgRepository == null) {
            return;
        }
        String channelId = channel.id == null ? "" : channel.id.trim();
        EpgRepository.EpgProgramPair existingPair = normalizedEpgPair(channelId);
        boolean hasCurrent = hasProgramTitle(existingPair == null ? null : existingPair.current)
                || (channel.nowProgram != null && !channel.nowProgram.trim().isEmpty());
        boolean hasNext = hasProgramTitle(existingPair == null ? null : existingPair.next)
                || (channel.nextProgram != null && !channel.nextProgram.trim().isEmpty());
        boolean hasRichCurrent = hasRichProgramDetails(existingPair == null ? null : existingPair.current);
        if (channelId.isEmpty() || (hasCurrent && hasNext && hasRichCurrent)
                || !touchControlsEpgRefreshGate.begin(channelId, android.os.SystemClock.elapsedRealtime())) {
            return;
        }
        if (!submitEpgTask("touch-hud-epg", () -> {
            EpgRepository.EpgProgram current = null;
            EpgRepository.EpgProgram next = null;
            boolean failed = false;
            try {
                EpgRepository.EpgProgramPair pair = epgRepository
                        .fetchProgramPairsForChannels(Collections.singletonList(channel), true, true, false)
                        .get(channelId);
                if (pair != null) {
                    current = pair.current;
                    next = pair.next;
                }
            } catch (Exception e) {
                failed = true;
                Log.w(TAG, "Touch HUD EPG hydrate failed for " + channelId + " " + displayName(channel), e);
            }
            EpgRepository.EpgProgram finalCurrent = current;
            EpgRepository.EpgProgram finalNext = next;
            boolean finalFailed = failed;
            postUiIfAlive(() -> {
                touchControlsEpgRefreshGate.complete(channelId, android.os.SystemClock.elapsedRealtime(),
                        finalCurrent != null || finalNext != null, finalFailed);
                EpgRepository.EpgProgramPair previousPair = normalizedEpgPair(channelId);
                EpgRepository.EpgProgram mergedCurrent = finalCurrent != null ? finalCurrent : (previousPair == null ? null : previousPair.current);
                EpgRepository.EpgProgram mergedNext = finalNext != null ? finalNext : (previousPair == null ? null : previousPair.next);
                boolean changed = !EpgRepository.sameProgramContent(previousPair == null ? null : previousPair.current, mergedCurrent)
                        || !EpgRepository.sameProgramContent(previousPair == null ? null : previousPair.next, mergedNext);
                if (!changed) return;
                if (mergedCurrent != null || mergedNext != null) {
                    epgProgramPairByChannelId.put(channelId, new EpgRepository.EpgProgramPair(mergedCurrent, mergedNext));
                    applySingleProgramPairToChannelLists(channelId, mergedCurrent, mergedNext);
                    Log.w(TAG, "Touch HUD EPG hydrated channel=" + channelId
                            + " current=" + (mergedCurrent == null ? "" : mergedCurrent.title)
                            + " next=" + (mergedNext == null ? "" : mergedNext.title));
                }
                ChannelItem active = getCurrentPlaybackChannelItem();
                boolean stillActive = active != null && channelId.equals(active.id);
                boolean hudVisible = touchControlsBar != null && touchControlsBar.getVisibility() == View.VISIBLE;
                if (stillActive && hudVisible) {
                    refreshTouchControlsBar();
                }
                if (stillActive && isOverlayVisible()) {
                    refreshOverlayChannelList();
                    updateOverlayPanel();
                }
            });
        })) {
            touchControlsEpgRefreshGate.complete(channelId, android.os.SystemClock.elapsedRealtime(), false, true);
        }
    }

    private boolean hasProgramTitle(EpgRepository.EpgProgram program) {
        return program != null && program.title != null && !program.title.trim().isEmpty();
    }

    private boolean hasRichProgramDetails(EpgRepository.EpgProgram program) {
        if (!hasProgramTitle(program)) {
            return false;
        }
        boolean hasTiming = program.startTime != null && !program.startTime.trim().isEmpty()
                && program.endTime != null && !program.endTime.trim().isEmpty();
        boolean hasArtwork = program.icon != null && !program.icon.trim().isEmpty();
        return hasTiming || hasArtwork;
    }

    private String formatPlaybackPreviewLabel(PlayerController.PlaybackSeekState state, long targetMs) {
        if (state == null) {
            return getString(R.string.timeshift_status_unavailable);
        }
        ChannelItem current = getCurrentPlaybackChannelItem();
        if (current != null && current.isVod && !state.liveCapable) {
            return getString(R.string.vod_playback_seek_label, displayName(current), formatDurationLabel(targetMs), formatDurationLabel(state.endMs));
        }
        if (state.liveCapable && playerController != null && playerController.isTimeshiftSupportedForCurrentChannel()) {
            long timestamp = playerController.liveProgrammeTimeMs(targetMs);
            if (timestamp > 0) {
                String title = "";
                List<EpgRepository.EpgProgram> entries = current == null ? null : liveGuideCache.get(current.id);
                if (entries != null) for (EpgRepository.EpgProgram entry : entries) {
                    if (parseIsoMillis(entry.startTime) <= timestamp && parseIsoMillis(entry.endTime) > timestamp) {
                        title = entry.title == null ? "" : entry.title; break;
                    }
                }
                long behind=Math.max(0L,state.endMs-targetMs);
                return liveClock(timestamp) + (behind>=LIVE_BADGE_THRESHOLD_MS ? " · −"+formatDurationLabel(behind) : " · Directo") + (title.isEmpty() ? "" : " · " + title);
            }
        }
        if (state.liveCapable) {
            long offsetMs = Math.max(0L, state.endMs - targetMs);
            if (offsetMs < LIVE_BADGE_THRESHOLD_MS) {
                return getString(R.string.timeshift_status_live);
            }
            long totalSeconds = Math.max(0L, Math.round(offsetMs / 1000f));
            long mins = totalSeconds / 60L;
            long secs = totalSeconds % 60L;
            return getString(R.string.timeshift_status_delayed, mins, secs);
        }
        return formatDurationLabel(targetMs) + " / " + formatDurationLabel(state.endMs);
    }

    private String liveClock(long timestamp) {
        return new java.text.SimpleDateFormat("HH:mm", Locale.getDefault()).format(new java.util.Date(timestamp));
    }

    private void prefetchLiveGuide() {
        ChannelItem channel = getCurrentPlaybackChannelItem();
        if (channel == null || channel.isVod || isProtectedItem(channel) || liveGuideCache.containsKey(channel.id) || channel.id.equals(liveGuideLoadingId)) return;
        final String id = channel.id; liveGuideLoadingId = id;
        ioExecutor.execute(() -> {
            List<EpgRepository.EpgProgram> loaded;
            try { loaded = epgRepository.fetchChannelPrograms(id, 80); } catch (Exception e) { loaded = new ArrayList<>(); }
            final List<EpgRepository.EpgProgram> result = loaded;
            postUiIfAlive(() -> {
                liveGuideCache.put(id, result);
                if (liveGuideCache.size() > 32) liveGuideCache.remove(liveGuideCache.keySet().iterator().next());
                if (id.equals(liveGuideLoadingId)) liveGuideLoadingId = "";
            });
        });
    }

    private void showLiveJumpMenu() {
        PlayerController.PlaybackSeekState state = playerController.getPlaybackSeekState();
        if (state == null || !playerController.isTimeshiftSupportedForCurrentChannel()) return;
        final ChannelItem channel = getCurrentPlaybackChannelItem();
        List<String> labels = new ArrayList<>(); List<Runnable> actions = new ArrayList<>();
        for (int minutes : new int[]{15, 30, 60}) {
            if (state.endMs - state.startMs < minutes * 60000L) continue;
            labels.add("Hace " + minutes + " minutos");
            actions.add(() -> {
                if (getCurrentPlaybackChannelItem() != channel) return;
                PlayerController.PlaybackSeekState now = playerController.getPlaybackSeekState();
                if (now != null) playerController.seekTimeshiftTo(Math.max(now.startMs, now.endMs - minutes * 60000L));
            });
        }
        if (playerController.liveProgrammeTimeMs(state.endMs) > 0) {
            labels.add("Elegir hora…"); actions.add(this::showLiveJumpClock);
        }
        labels.add("Ir al directo"); actions.add(() -> playerController.resumeTimeshiftLive());
        showTvOptionsDialog("Volver a…", "Dentro de la ventana disponible del canal", labels, actions);
    }

    private void showLiveJumpClock() {
        final ChannelItem channel = getCurrentPlaybackChannelItem();
        showTvTextInputPanel(new TvTextInputPanelUiModel("Hora de la emisión", "Introduce la hora en formato HH:mm", "Ir", "Cancelar", "",
            java.util.Arrays.asList(new TvTextInputFieldUiModel("Hora HH:mm", "", false, false)), values -> {
                if (channel != getCurrentPlaybackChannelItem() || values.isEmpty()) return;
                PlayerController.PlaybackSeekState state = playerController.getPlaybackSeekState();
                if (state == null) return;
                long start = playerController.liveProgrammeTimeMs(state.startMs), end = playerController.liveProgrammeTimeMs(state.endMs);
                long target = LiveDvrClock.resolve(values.get(0), start, end, java.util.TimeZone.getDefault());
                if (target < 0) { showStatus("Hora no válida o fuera de la ventana disponible"); return; }
                playerController.seekTimeshiftTo(state.startMs + target - start);
            }, null, null));
    }

    private String formatDurationLabel(long valueMs) {
        long totalSeconds = Math.max(0L, Math.round(valueMs / 1000f));
        long hours = totalSeconds / 3600L;
        long minutes = (totalSeconds % 3600L) / 60L;
        long seconds = totalSeconds % 60L;
        if (hours > 0L) {
            return String.format(Locale.getDefault(), "%d:%02d:%02d", hours, minutes, seconds);
        }
        return String.format(Locale.getDefault(), "%02d:%02d", minutes, seconds);
    }

    private String formatDurationShort(long valueMs) {
        return formatDurationLabel(valueMs);
    }

