    private List<ChannelItem> archiveChannels() {
        List<ChannelItem> allowed = new ArrayList<>();
        if (currentOfflinePermissions == null || !currentOfflinePermissions.liveEnabled) return allowed;
        for (ChannelItem c : allChannels) if (supportsU7d(c) && LiveHomePolicy.visibleInHome(c,currentOfflinePermissions)
                && !shouldHideProtectedItem(c) && !PrivateChannelPolicy.privateItem(c,currentOfflinePermissions)) allowed.add(c);
        java.util.LinkedHashMap<String,ChannelItem> unique=new java.util.LinkedHashMap<>();
        ChannelItem active=currentPlaybackU7dChannel!=null?currentPlaybackU7dChannel:getCurrentPlaybackChannelItem();
        for(ChannelItem c:allowed) {
            String key=(isOrangeChannel(c)?"orange:":"movistar:")+normalizeU7dMatchText(displayName(c));
            if(!unique.containsKey(key) || (active!=null && active.id.equals(c.id)) || archiveState.getChannel().equals(c.id))unique.put(key,c);
        }
        return new ArrayList<>(unique.values());
    }

    private void ensureArchiveScope() {
        if (archiveStore == null) archiveStore = new U7dCatalogStore(getApplicationContext());
        if(archiveAvailability==null)archiveAvailability=new ArchiveAvailability(getSharedPreferences("archive_availability",MODE_PRIVATE));
        String scope = catalogSnapshotStore.getUserScope();
        if (!scope.equals(archiveScope)) {
            archiveScope=scope;archiveKnownSaved=null;
            archiveState.setGenres(java.util.Collections.emptyList());
            archiveState.setFormat(prefs.getString("u7d_transport_"+android.net.Uri.encode(scope),"Auto"));
            archiveGeneration++; panelGuideRefreshGate.clear(); pendingMovistarGuideChannels.clear(); archiveWindowKey="";archiveWindowLoading=false;archivePrograms.clear();archiveLoading.clear();archiveErrors.clear();
            archiveState.setEntries(java.util.Collections.emptyList()); archiveState.setQuery("");
            archiveState.setChannel("");archiveState.setGenre("");archiveState.setSelectedId("");
        }
    }

    private void refreshArchiveAssociations() {
        ensureArchiveScope();
        List<ChannelItem> changed=new ArrayList<>();
        for(ChannelItem c:allChannels)if(supportsU7d(c) && !isOrangeChannel(c)
                && archiveAvailability.invalidateMismatchedIdentity(archiveScope,c))changed.add(c);
        if(changed.isEmpty())return;
        // Cancel old metadata jobs, retaining all unaffected channel programmes and playback.
        archiveGeneration++;panelGuideRefreshGate.clear();archiveWindowRevision++;archiveWindowKey="";archiveWindowLoading=false;
        archiveLoading.clear();pendingMovistarGuideChannels.clear();archivePrefetchedChannel="";
        final String scope=archiveScope;
        archiveEligible=new ArrayList<>(archiveChannels());
        for(ChannelItem c:changed){archivePrograms.remove(c.id);archiveErrors.remove(c.id);}
        archiveStorageExecutor.execute(()->{
            for(ChannelItem c:changed)archiveStore.invalidate(scope,c.id);
        });
        Log.i(TAG,"catchup associations refreshed channels="+changed.size());
        refreshMovistarArchiveBatch(changed,scope,archiveGeneration);
        if(archiveDialog!=null)loadArchiveCatalog(false);
    }

    private void openArchiveCatalog(ChannelItem initial, boolean savedOnly) {
        cancelRemoteZap();
        ensureArchiveScope();
        if (archiveChannels().isEmpty()) { showStatus("No hay canales con U7D disponibles para esta cuenta");return; }
        if (archiveDialog != null) { archiveDialog.dismiss();archiveDialog=null; }
        archiveState.setSavedOnly(savedOnly);
        if(archiveState.getDay().isEmpty())archiveState.setDay(java.time.LocalDate.now().toString());
        if(initial!=null) archiveState.setChannel(initial.id);
        if(savedOnly) {archiveState.setChannel("");archiveState.setGenre("");archiveState.setQuery("");}
        ComposeView view=new ComposeView(this);attachDialogViewTreeOwners(view);prepareModalSurface();
        archiveState.setQueryPage(()->queryArchivePage());
        U7dCatalogComposeBinder.bind(view,archiveState,()->{if(archiveDialog!=null)archiveDialog.dismiss();},()->loadArchiveCatalog(false));
        archiveDialog=ComposeDialogHost.showFullscreen(this,view,()->{archiveDialog=null;handleModalDismissed();});
        handleModalShown();loadArchiveCatalog(false);
    }

    private void loadArchiveCatalog(boolean preload) {
        if(preload && archiveDialog!=null)return;
        ensureArchiveScope();
        if(archiveFanart==null) archiveFanart=new FanartRepository(getCacheDir());
        if(!archiveFanartLoading) {
            archiveFanartLoading=true;final int fanartGeneration=archiveGeneration;final String fanartBase=baseUrl;final String fanartScope=archiveScope;
            archiveFanartExecutor.execute(()->{
                boolean changed=false;try{changed=archiveFanart.refresh(fanartBase);}catch(Exception ignored){}
                final boolean publish=changed;final List<EpgRepository.EpgProgram> fanartSaved=archiveStore.savedPrograms(fanartScope);postUiIfAlive(()->{archiveFanartLoading=false;if(publish && fanartGeneration==archiveGeneration)publishArchiveEntries(fanartSaved);});
            });
        }
        List<ChannelItem> allowed=archiveChannels();
        archiveEligible=new ArrayList<>(allowed);
        if(allowed.isEmpty())return;
        ChannelItem active=currentPlaybackU7dChannel!=null?currentPlaybackU7dChannel:getCurrentPlaybackChannelItem();
        String priority=preload && active!=null?active.id:archiveState.getChannel();
        allowed.sort((a,b)->Boolean.compare(!a.id.equals(priority),!b.id.equals(priority)));
        if(preload)allowed=new ArrayList<>(allowed.subList(0,Math.min(1,allowed.size())));
        else if(priority!=null&&!priority.isEmpty()){
            List<ChannelItem> selected=new ArrayList<>();for(ChannelItem c:allowed)if(c.id.equals(priority))selected.add(c);
            if(!selected.isEmpty())allowed=selected;
        }
        final int generation=archiveGeneration;final String scope=archiveScope;
        final List<ChannelItem> snapshot=allowed;
        final java.util.Set<String> windowDays=archiveWindowDays();
        String windowKey=scope+"|"+new java.util.TreeSet<>(windowDays)+"|"+(preload?"preload:":"visible:")+priority;
        if(windowKey.equals(archiveWindowKey)) {
            if(archiveWindowLoading)return;
            List<ChannelItem> movistar=new ArrayList<>();for(ChannelItem c:snapshot)if(isOrangeChannel(c))refreshArchiveChannel(c,scope,generation);else movistar.add(c);
            if(!movistar.isEmpty())refreshMovistarArchiveBatch(movistar,scope,generation);return;
        }
        archiveWindowKey=windowKey;archiveWindowLoading=true;archiveState.setLoading(true);
        final int windowRevision=++archiveWindowRevision;
        List<ChannelItem> directChannels=new ArrayList<>();for(ChannelItem c:snapshot)if(!isOrangeChannel(c))directChannels.add(c);
        if(!directChannels.isEmpty())refreshMovistarArchiveBatch(directChannels,scope,generation);
        archiveStorageExecutor.execute(()->{
            android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);
            // Include alternate platform copies omitted by the visible-channel deduplication.

            List<EpgRepository.EpgProgram> saved=archiveStore.savedPrograms(scope);
            java.util.Map<String,List<EpgRepository.EpgProgram>> cached=new java.util.LinkedHashMap<>();
            for(ChannelItem c:snapshot) {
                if(generation!=archiveGeneration || windowRevision!=archiveWindowRevision || Thread.currentThread().isInterrupted())return;
                // Movistar has its own compact daily cache; avoid decoding the legacy full-week JSON.
                cached.put(c.id,archiveStore.readDays(scope,c.id,windowDays));
                if(cached.size()>=24) {
                    java.util.Map<String,List<EpgRepository.EpgProgram>> batch=new java.util.LinkedHashMap<>(cached);cached.clear();
                    postUiIfAlive(()->{if(generation==archiveGeneration && windowRevision==archiveWindowRevision){
                        for(String id:batch.keySet())archivePrograms.put(id,batch.get(id));
                        mergeArchiveSaved(saved);publishArchiveEntries(saved);
                    }});
                }
            }
            postUiIfAlive(()->{
                if(generation!=archiveGeneration || windowRevision!=archiveWindowRevision)return;
                archiveWindowLoading=false;archiveState.setLoading(false);
                for(String id:cached.keySet())archivePrograms.put(id,cached.get(id));
                mergeArchiveSaved(saved);publishArchiveEntries(saved);
                for(ChannelItem c:snapshot)if(isOrangeChannel(c))refreshArchiveChannel(c,scope,generation);
            });
        });
    }

    private void mergeArchiveSaved(List<EpgRepository.EpgProgram> saved) {
        for(EpgRepository.EpgProgram p:saved) {
            List<EpgRepository.EpgProgram> list=new ArrayList<>(archivePrograms.getOrDefault(p.channelId,java.util.Collections.emptyList()));
            boolean exists=false;for(EpgRepository.EpgProgram x:list)if(U7dCatalogStore.id(x).equals(U7dCatalogStore.id(p)))exists=true;
            if(!exists){list.add(p);archivePrograms.put(p.channelId,list);}
        }
    }

    private final java.util.Map<String,ChannelItem> pendingMovistarGuideChannels=new java.util.LinkedHashMap<>();
    private void drainPendingMovistarGuide(String scope,int generation){
        if(generation!=archiveGeneration||archiveLoading.contains("@movistar")||pendingMovistarGuideChannels.isEmpty())return;
        List<ChannelItem> next=new ArrayList<>(pendingMovistarGuideChannels.values());pendingMovistarGuideChannels.clear();
        refreshMovistarArchiveBatch(next,scope,generation);
    }
    private void refreshMovistarArchiveBatch(List<ChannelItem> channels,String scope,int generation) {
        final String batchKey="@movistar";
        if(!archiveLoading.add(batchKey)){for(ChannelItem c:channels)pendingMovistarGuideChannels.put(c.id,c);return;}
        archiveState.setStatus("Actualizando guía de Movistar…");
        final List<String> days=new ArrayList<>(archiveWindowDays());days.sort(java.util.Collections.reverseOrder());
        String selectedDay=archiveState.getDay();if(days.remove(selectedDay))days.add(0,selectedDay);
        final java.util.Map<String,List<EpgRepository.EpgProgram>> aggregate=new java.util.LinkedHashMap<>();
        for(ChannelItem c:channels)aggregate.put(c.id,new ArrayList<>(archivePrograms.getOrDefault(c.id,java.util.Collections.emptyList())));
        movistarGuideExecutor.execute(()->{
            boolean failed=false;int loaded=0;
            final List<EpgRepository.EpgProgram> saved=archiveStore.savedPrograms(scope);
            for(String day:days){
                if(generation!=archiveGeneration||Thread.currentThread().isInterrupted())return;
                try{
                    MovistarGuideRepository.Guide result=directMovistarGuide().day(day,channels,guide->{
                        if(generation!=archiveGeneration)return;
                        java.util.Map<String,List<EpgRepository.EpgProgram>> changed=new java.util.LinkedHashMap<>();
                        for(ChannelItem c:channels){
                            JSONObject identity=guide.identity(c);if(identity==null)continue;
                            archiveAvailability.registerOfficial(scope,c,identity);
                            List<EpgRepository.EpgProgram> merged=new ArrayList<>(aggregate.get(c.id));
                            merged.removeIf(p->ArchiveWindow.day(p.startTime).equals(day));
                            try{merged.addAll(guide.programmes(c,identity));}catch(Exception invalid){continue;}
                            aggregate.put(c.id,merged);changed.put(c.id,merged);
                        }
                        if(!changed.isEmpty())try{archiveStore.indexAll(scope,changed);}catch(Exception failure){Log.w(TAG,"Catchup index unavailable",failure);}
                        if(!changed.isEmpty())postUiIfAlive(()->{if(generation==archiveGeneration){
                            for(String id:changed.keySet())archivePrograms.put(id,windowArchive(changed.get(id)));
                            archiveState.setLoading(false);mergeArchiveSaved(saved);publishArchiveEntries(saved);
                        }});
                    });
                    if(!result.complete)failed=true;
                    loaded++;
                    final java.util.Map<String,List<EpgRepository.EpgProgram>> diskSnapshot=new java.util.LinkedHashMap<>(aggregate);
                    archiveStorageExecutor.execute(()->{try{if(generation==archiveGeneration)archiveStore.writeAll(scope,diskSnapshot);}catch(Exception ignored){}});
                }catch(Exception e){failed=true;android.util.Log.w("DirectGuide","Day failed: "+e.getClass().getSimpleName());}
            }
            final boolean error=failed;final boolean noGuide=loaded==0;
            postUiIfAlive(()->{
                if(generation!=archiveGeneration)return;
                archiveLoading.remove(batchKey);
                if(error)archiveErrors.add(batchKey);else archiveErrors.remove(batchKey);
                archiveState.setStatus(error?"Parte de la guía no se ha actualizado · se conserva la caché":"Guía de Movistar actualizada");
                if(noGuide)refreshMovistarArchiveBackend(channels,scope,generation);
                else if(!days.containsAll(archiveWindowDays()))loadArchiveCatalog(false);
                drainPendingMovistarGuide(scope,generation);
            });
        });
    }

    private void refreshMovistarArchiveBackend(List<ChannelItem> channels,String scope,int generation) {
        final String batchKey="@movistar";
        if(!archiveLoading.add(batchKey))return;
        archiveState.setStatus("Actualizando parrilla Movistar…");
        // Credentials are captured for this account; a later login cannot change the request scope.
        final String url=buildMovistarU7dProgramsUrl(baseUrl,catalogSnapshotStore.getAccessToken(),catalogSnapshotStore.getDeviceId(),null);
        final java.util.Map<String,String> headers=buildAuthenticatedJsonHeaders();
        movistarGuideExecutor.execute(()->{
            java.util.Map<String,List<EpgRepository.EpgProgram>> results=new java.util.LinkedHashMap<>();
            boolean failed=false;
            try {
                boolean stale=false;for(ChannelItem c:channels)if(!archiveStore.fresh(scope,c.id,System.currentTimeMillis()) || (archiveAvailability!=null && archiveAvailability.needsIdentity(scope,c))
                        || ("mplus".equals(U7dChannelIdentity.normalize(c.tvgId)) && archiveStore.read(scope,c.id).isEmpty()))stale=true;
                if(stale) {
                    HttpClient.Response response=httpClient.get(url,10000,25000,headers);
                    if(response==null||!response.isSuccessful())throw new IllegalStateException("Catálogo no disponible");
                    String body=response.body.trim();Object payload=body.startsWith("[")?new JSONArray(body):new JSONObject(body);
                    for(ChannelItem c:channels) {
                        if(Thread.currentThread().isInterrupted())return;
                        List<EpgRepository.EpgProgram> items=parseMovistarU7dProgramsObject(c,payload);
                        if(archiveAvailability!=null)archiveAvailability.identityAttempt(scope,c);
                        archiveStore.write(scope,c.id,items);results.put(c.id,items);
                    }
                }
            }catch(Exception e){failed=true;}
            boolean error=failed;List<EpgRepository.EpgProgram> saved=archiveStore.savedPrograms(scope);
            postUiIfAlive(()->{
                if(generation!=archiveGeneration)return;
                archiveLoading.remove(batchKey);for(String id:results.keySet())archivePrograms.put(id,windowArchive(results.get(id)));
                if(error)archiveErrors.add(batchKey);else archiveErrors.remove(batchKey);
                mergeArchiveSaved(saved);publishArchiveEntries(saved);
                archiveState.setStatus(!archiveErrors.isEmpty()?"Sin conexión con parte del catálogo · datos guardados":
                    archiveLoading.isEmpty()?"Programación actualizada":"Actualizando otros canales…");
                drainPendingMovistarGuide(scope,generation);
            });
        });
    }

    private void refreshArchiveChannel(ChannelItem c,String scope,int generation) {
        if(!archiveLoading.add(c.id))return;
        archiveState.setStatus("Actualizando programación · "+archiveLoading.size()+" canales pendientes");
        final String requestUrl=buildMovistarU7dProgramsUrl(baseUrl,catalogSnapshotStore.getAccessToken(),catalogSnapshotStore.getDeviceId(),c);
        final java.util.Map<String,String> requestHeaders=buildAuthenticatedJsonHeaders();
        archiveExecutor.execute(()->{
            List<EpgRepository.EpgProgram> result=null;boolean failed=false;
            try {
                if(!archiveStore.fresh(scope,c.id,System.currentTimeMillis())) {
                    HttpClient.Response response=httpClient.get(requestUrl,10000,25000,requestHeaders);
                    if(response==null||!response.isSuccessful())throw new IllegalStateException("Catálogo no disponible");
                    result=parseMovistarU7dProgramsPayload(c,response.body);archiveStore.write(scope,c.id,result);
                }
            }catch(Exception e){failed=true;}
            List<EpgRepository.EpgProgram> programs=result;boolean error=failed;
            List<EpgRepository.EpgProgram> saved=archiveStore.savedPrograms(scope);
            postUiIfAlive(()->{
                if(generation!=archiveGeneration)return;
                archiveLoading.remove(c.id);
                if(programs!=null)archivePrograms.put(c.id,windowArchive(programs));
                mergeArchiveSaved(saved);publishArchiveEntries(saved);
                if(error)archiveErrors.add(c.id);else archiveErrors.remove(c.id);
                archiveState.setStatus(!archiveErrors.isEmpty()?"Algunos datos no se han actualizado · se conserva la caché":
                    archiveLoading.isEmpty()?"Programación actualizada": "Actualizando · "+archiveLoading.size()+" canales pendientes");
            });
        });
    }

    private final DeferredArchiveRefresh archiveRefresh = new DeferredArchiveRefresh();
    private boolean archiveRefreshPosted;
    private final Runnable archivePresentationDelivery = () -> {
        archiveRefreshPosted = false;
        archiveRefresh.drain(isArchivePresentationVisible());
    };
    private boolean isArchivePresentationVisible() {
        return (archiveDialog != null && archiveDialog.isShowing())
                || (touchControlsBar != null && touchControlsBar.getVisibility() == View.VISIBLE);
    }
    private void scheduleArchivePresentation() {
        boolean visible = isArchivePresentationVisible();
        if (!visible || archiveRefreshPosted || !archiveRefresh.pending()) return;
        archiveRefreshPosted = true;
        uiHandler.postDelayed(archivePresentationDelivery, 250);
    }
    private void publishArchiveEntries(List<EpgRepository.EpgProgram> saved) {
        publishArchiveEntries(saved, false);
    }
    private void publishArchiveEntries(List<EpgRepository.EpgProgram> saved, boolean immediate) {
        final int generation = archiveGeneration;
        // A guide/availability callback may carry saved state read before a click.
        // Retain the newest accepted snapshot without another database round trip.
        if (!ArchiveSavedSnapshot.current(saved, archiveStore.savedRevision())) {
            if (!ArchiveSavedSnapshot.current(archiveKnownSaved, archiveStore.savedRevision())) return;
            saved = archiveKnownSaved;
        }
        final List<EpgRepository.EpgProgram> snapshot = saved;
        archiveKnownSaved=snapshot;
        archiveRefresh.request(() -> { if (generation == archiveGeneration) publishArchiveEntriesNow(snapshot); });
        // A requested page should not wait behind the background coalescing delay.
        // Replace pending work and cancel its timer so it cannot drain a later batch early.
        if (immediate) {
            uiHandler.removeCallbacks(archivePresentationDelivery);
            archiveRefreshPosted = false;
            archiveRefresh.drain(isArchivePresentationVisible());
        } else scheduleArchivePresentation();
    }
    private void publishArchiveEntriesNow(List<EpgRepository.EpgProgram> saved) {
        java.util.Set<String> ids=new java.util.HashSet<>();for(EpgRepository.EpgProgram p:saved)ids.add(U7dCatalogStore.id(p));
        List<ChannelItem> available=new ArrayList<>(archiveEligible);
        java.util.Set<String> availableIds=new java.util.HashSet<>();for(ChannelItem c:available)availableIds.add(c.id);
        for(EpgRepository.EpgProgram p:saved) {
            ChannelItem c=findAllowedHomeLiveChannel(p.channelId);
            if(c!=null && supportsU7d(c) && availableIds.add(c.id))available.add(c);
        }
        java.util.Map<String,List<EpgRepository.EpgProgram>> snapshot=new java.util.LinkedHashMap<>(archivePrograms);
        int generation=archiveGeneration;int revision=++archivePublishRevision;final int pageRequest=archivePageRequest;
        final String availabilityScope=archiveScope;
        final String queryDay=archiveState.getDay(),queryChannel=archiveState.getChannel(),queryGenre=archiveState.getGenre(),queryText=archiveState.getQuery();
        final int pageTrace=ArchivePageTrace.capture(queryDay);
        ArchivePageTrace.mark(pageTrace,revision,"scheduled");
        final boolean queryCatalog=archiveDialog!=null && archiveDialog.isShowing();
        if(queryCatalog)refreshArchiveGenres(availabilityScope,generation);
        final boolean querySaved=archiveState.getSavedOnly();final int queryOffset=archiveState.getOffset();
        ChannelItem playing=currentPlaybackU7dChannel!=null?currentPlaybackU7dChannel:getCurrentPlaybackChannelItem();
        final String stripChannel=playing==null?"":playing.id;
        final ArchiveAvailability availability = archiveAvailability;
        archivePresentationExecutor.execute(()->{
        if(generation!=archiveGeneration || revision!=archivePublishRevision)return;
        // Per-channel preference/identity checks must not hold up remote input.
        // Scheduling and subsequent availability reads stay ordered on this worker.
        if(availability!=null)for(ChannelItem c:available)if(!isOrangeChannel(c)) {
            try {
                availability.schedule(availabilityScope,c,()->postUiIfAlive(()->{if(generation==archiveGeneration)publishArchiveEntries(saved);}));
            } catch (java.util.concurrent.RejectedExecutionException closed) {
                // The activity can close its availability worker while this batch is running.
                return;
            }
        }
        if(generation!=archiveGeneration || revision!=archivePublishRevision)return;
        ArchivePageTrace.mark(pageTrace,revision,"queryStart");
        long queryStarted=android.os.SystemClock.elapsedRealtime();
        List<String> allowedIds=new ArrayList<>();java.util.Map<String,String> channelOptions=new java.util.LinkedHashMap<>();
        for(ChannelItem c:available)if(querySaved || archiveAvailability==null || !archiveAvailability.unavailable(availabilityScope,c)){
            allowedIds.add(c.id);channelOptions.put(c.id,displayName(c));
        }
        U7dCatalogStore.Page page=queryCatalog ? archiveStore.page(availabilityScope,allowedIds,queryDay,queryChannel,queryGenre,queryText,querySaved,queryOffset,60,System.currentTimeMillis()) : new U7dCatalogStore.Page();
        ArchivePageTrace.mark(pageTrace,revision,"pageReady");
        if(generation!=archiveGeneration || pageRequest!=archivePageRequest)return;
        java.util.Set<String> pageIds=new java.util.LinkedHashSet<>();
        java.util.Map<String,List<EpgRepository.EpgProgram>> presented=new java.util.LinkedHashMap<>();
        for(EpgRepository.EpgProgram p:page.programs){pageIds.add(U7dCatalogStore.id(p));presented.computeIfAbsent(p.channelId,k->new ArrayList<>()).add(p);}
        // The playback strip is independent of catalog filters and pages.
        if(availableIds.contains(stripChannel)){
            long now=System.currentTimeMillis();
            presented.computeIfAbsent(stripChannel,k->new ArrayList<>()).addAll(archiveStore.recent(availabilityScope,stripChannel,now-2L*86400000,now,40));
        }
        ArchivePageTrace.mark(pageTrace,revision,"stripReady");
        if(generation!=archiveGeneration || pageRequest!=archivePageRequest)return;
        // Genre refresh runs independently; never hold a ready page for its scan.
        ArchivePageTrace.mark(pageTrace,revision,"genresReady");
        if(generation!=archiveGeneration || pageRequest!=archivePageRequest)return;
        long nextChange=archiveStore.nextChange(availabilityScope,System.currentTimeMillis());
        final long dataReady=android.os.SystemClock.elapsedRealtime();
        ArchivePageTrace.mark(pageTrace,revision,"dataReady");
        List<U7dCatalogEntry> entries=new ArrayList<>();
        java.util.Set<String> emitted=new java.util.HashSet<>();
        SimpleDateFormat dayFormat=new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);
        SimpleDateFormat cardTimeFormat=new SimpleDateFormat("HH:mm",Locale.getDefault());
        final long modelNow=System.currentTimeMillis();
        for(ChannelItem c:available) {
        List<EpgRepository.EpgProgram> channelPrograms=presented.get(c.id);
        if(channelPrograms==null || channelPrograms.isEmpty())continue;
        final String channelDisplay=displayName(c);
        final String repairedDisplay=ArchiveText.repair(channelDisplay);
        final boolean unavailable=archiveAvailability!=null && archiveAvailability.unavailable(availabilityScope,c);
        final boolean officialChannel=U7dChannelPolicy.isMovistarChannel(c);
        final String provider=archiveAvailability==null?c.tvgId:archiveAvailability.provider(availabilityScope,c);
        final String officialChannelName=archiveAvailability==null?"":archiveAvailability.officialName(availabilityScope,c,"");
        for(EpgRepository.EpgProgram p:channelPrograms) {
            if(generation!=archiveGeneration || pageRequest!=archivePageRequest || Thread.currentThread().isInterrupted())return;
            long start=parseIsoMillis(p.startTime),end=parseIsoMillis(p.endTime);
            if(start<=0||end<=start)continue;
            String id=U7dCatalogStore.id(p);if(!emitted.add(id))continue;
            if(unavailable && !ids.contains(id))continue;
            if(start>modelNow || (end+7L*86400000<modelNow && !ids.contains(id)))continue;
            String day=dayFormat.format(new Date(start));
            String fanart=MovistarGuideRepository.officialImage(p.icon)?p.icon:archiveFanart==null?null:archiveFanart.find(repairedDisplay,p.tvgId,start,p.title);
            String[] presentation=ArchiveText.sports(p.title,p.category);
            U7dCatalogEntry entry=new U7dCatalogEntry(id,c.id,ArchiveText.channel(channelDisplay,officialChannelName.isEmpty()?p.channelName:officialChannelName),presentation[0],p.category,p.description,day,start,end,ids.contains(id),
                image->bindMovistarArchiveArtwork(image,c,p,fanart),
                ()->runArchiveAction(c,()->playMovistarIsmU7dProgram(c,p)),
                ()->runArchiveAction(c,()->tuneChannelById(c.id)),
                ()->setArchiveSaved(p,end+7L*86400000,!ids.contains(id)));
            entry.programmeMetadata=new ProgrammeMetadataUiModel(p,officialChannel,
                provider==null||provider.isEmpty()?(p.tvgId==null?"":p.tvgId):provider);
            entry.schedule=cardTimeFormat.format(new Date(start))+"–"+cardTimeFormat.format(new Date(end))+" · "+entry.channel;
            entry.hasProgramArtwork=fanart!=null || (!ProgramArtworkResolver.resolve(p.icon, "").isEmpty() && !p.icon.equals(c.logoUrl));
            String official=movistarArtwork==null||archiveAvailability==null?"":movistarArtwork.cached(provider,start,p.title);
            entry.artworkKey=!official.isEmpty()?official:fanart!=null?fanart:ProgramArtworkResolver.resolve(p,c);
            if(!official.isEmpty())entry.hasProgramArtwork=true;
            entry.subtitle=presentation[1];
            entries.add(entry);
        }
        }
        final long modelsReady=android.os.SystemClock.elapsedRealtime();
        ArchivePageTrace.mark(pageTrace,revision,"modelsReady");
        postUiIfAlive(()->{
            if(generation==archiveGeneration && ArchiveSavedSnapshot.current(saved,archiveStore.savedRevision()) && revision>archiveLastPublishedRevision
                    && queryDay.equals(archiveState.getDay()) && queryChannel.equals(archiveState.getChannel())
                    && queryGenre.equals(archiveState.getGenre()) && queryText.equals(archiveState.getQuery())
                    && querySaved==archiveState.getSavedOnly() && queryOffset==archiveState.getOffset()
                    && queryCatalog==(archiveDialog!=null && archiveDialog.isShowing())) {
                Log.i(TAG,"ArchiveCost queryMs="+(dataReady-queryStarted)+" modelsMs="+(modelsReady-dataReady)+" deliveryMs="+(android.os.SystemClock.elapsedRealtime()-modelsReady)+" cards="+entries.size());
                ArchivePageTrace.published(pageTrace,revision);
                archiveState.setPublishedDay(queryDay);
                archiveLastPublishedRevision=revision;
                archiveState.setPresentationKey(ArchivePageIdentity.key(queryDay,queryChannel,queryGenre,queryText,querySaved,page.offset));
                archiveState.setEntries(entries);
                archiveState.setQuerying(false);archiveState.setNextChange(nextChange);
                if(queryCatalog) {
                    archiveState.setPageIds(pageIds);archiveState.setTotal(page.total);archiveState.setOffset(page.offset);
                    archiveState.setChannels(channelOptions);
                }
                Log.i(TAG,"CatchupPage catalog="+queryCatalog+" total="+page.total+" offset="+page.offset+" cards="+entries.size()+" ms="+(android.os.SystemClock.elapsedRealtime()-queryStarted));
                prefetchMovistarArchiveArtwork(entries);
                // The player model is a snapshot, unlike the catalog's Compose
                // state. Publish newly loaded programmes to visible controls too.
                if (isTouchControlsVisibleForRemote()) refreshTouchControlsBar();
            }
        });
        });
    }

    // Called on UI only. Keep the last filter list while its replacement loads;
    // the database scan never queues ahead of a programme page.
    private void refreshArchiveGenres(String scope,int generation) {
        if(archiveStore==null || archiveDialog==null || !archiveDialog.isShowing())return;
        List<String> fresh=archiveStore.cachedGenres(scope,false);
        List<String> visible=fresh!=null?fresh:archiveStore.cachedGenres(scope,true);
        if(visible!=null && !visible.equals(archiveState.getGenres()))archiveState.setGenres(visible);
        if(fresh!=null || archiveGenresLoading)return;
        archiveGenresLoading=true;
        final U7dCatalogStore store=archiveStore;
        archiveGenreExecutor.execute(()->{
            android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);
            List<String> result=null;
            long started=android.os.SystemClock.elapsedRealtime();
            android.os.Trace.beginSection("Archive.genresRefresh");
            try { result=store.genres(scope); }
            catch(Exception error) { Log.w(TAG,"Catchup genre refresh failed"); }
            finally { android.os.Trace.endSection(); }
            final List<String> loaded=result;
            Log.i(TAG,"ArchiveGenres backgroundMs="+(android.os.SystemClock.elapsedRealtime()-started));
            postUiIfAlive(()->{
                archiveGenresLoading=false;
                if(archiveDialog==null || !archiveDialog.isShowing())return;
                if(generation!=archiveGeneration || !scope.equals(archiveScope)) {
                    refreshArchiveGenres(archiveScope,archiveGeneration);
                    return;
                }
                if(loaded!=null && !loaded.equals(archiveState.getGenres()))archiveState.setGenres(loaded);
            });
        });
    }

    private void runArchiveAction(ChannelItem c,Runnable action) {
        ChannelItem allowed=findAllowedHomeLiveChannel(c.id);
        if(allowed==null||!supportsU7d(allowed)){showStatus("Este canal ya no está disponible");return;}
        prefs.edit().putString("u7d_transport_"+android.net.Uri.encode(archiveScope),archiveState.getFormat()).apply();
        if(archiveDialog!=null)dismissModalForNextAction(archiveDialog,action);else action.run();
    }

    private void toggleArchiveSaved(EpgRepository.EpgProgram p,long expires) {
        setArchiveSaved(p,expires,null);
    }

    private void setArchiveSaved(EpgRepository.EpgProgram p,long expires,Boolean desired) {
        final String scope=archiveScope;final int generation=archiveGeneration;
        archiveStorageExecutor.execute(()->{
            try {
                archiveStore.setSaved(scope,p,expires,desired!=null?desired:!archiveStore.saved(scope,U7dCatalogStore.id(p)));List<EpgRepository.EpgProgram> saved=archiveStore.savedPrograms(scope);
                postUiIfAlive(()->{if(generation==archiveGeneration){publishArchiveEntries(saved);archiveState.setRevision(archiveState.getRevision()+1);}});
            }catch(Exception e){postUiIfAlive(()->showStatus("No se pudo guardar el programa"));}
        });
    }

    private boolean handleArchiveStripKey(KeyEvent event) {
        if(!isTouchControlsVisibleForRemote() || compactPlaybackHud || hasBlockingOverlaySurfaceVisible()) {archiveStripFocused=false;return false;}
        List<U7dCatalogEntry> items=archiveStrip();
        if(items.isEmpty()){archiveStripFocused=false;return false;}
        if(event.getAction()!=KeyEvent.ACTION_DOWN)return false;
        int key=event.getKeyCode();
        if(!archiveStripFocused) {
            // First Up belongs to timeshift; a separate second press enters Catchup.
            if(key!=KeyEvent.KEYCODE_DPAD_UP || !isTouchControlsTimeshiftFocused()) return false;
            if(event.getRepeatCount()>0) return true;
            archiveStripIndex=archiveStripSelection.resolve(items);
            archiveStripFocused=true;
        } else {
            if(key==KeyEvent.KEYCODE_DPAD_LEFT)archiveStripIndex=Math.max(0,archiveStripIndex-1);
            else if(key==KeyEvent.KEYCODE_DPAD_RIGHT)archiveStripIndex=Math.min(items.size()-1,archiveStripIndex+1);
            else if(key==KeyEvent.KEYCODE_DPAD_DOWN){archiveStripFocused=false;focusTouchControlsTimeshift();}
            else if(key==KeyEvent.KEYCODE_BACK){archiveStripFocused=false;hideTouchControlsForRemote();return true;}
            else if(key==KeyEvent.KEYCODE_DPAD_CENTER || key==KeyEvent.KEYCODE_ENTER) {
                U7dCatalogEntry e=items.get(Math.min(archiveStripIndex,items.size()-1));archiveStripFocused=false;
                if(e.end>System.currentTimeMillis())e.live.run();else e.play.run();return true;
            } else return key==KeyEvent.KEYCODE_DPAD_UP;
        }
        archiveStripSelection.remember(items,archiveStripIndex);
        refreshTouchControlsBar();scheduleTouchControlsAutoHide();return true;
    }

    private String archiveStripRequestedKey="";
    private List<U7dCatalogEntry> archiveStrip() {
        scheduleArchivePresentation();
        ChannelItem c=currentPlaybackU7dChannel!=null?currentPlaybackU7dChannel:getCurrentPlaybackChannelItem();
        if(c==null||!supportsU7d(c)||findAllowedHomeLiveChannel(c.id)==null)return java.util.Collections.emptyList();
        // A tune can reuse a guide preload already in progress. Read the cached strip
        // independently; otherwise the previous channel's presentation can remain empty.
        if(archiveStore!=null) {
            String key=archiveScope+"|"+archiveGeneration+"|"+c.id;
            if(!key.equals(archiveStripRequestedKey)) {
                archiveStripRequestedKey=key;
                final String scope=archiveScope; final int generation=archiveGeneration;
                archivePresentationExecutor.execute(()->{
                    List<EpgRepository.EpgProgram> saved=archiveStore.savedPrograms(scope);
                    postUiIfAlive(()->{if(generation==archiveGeneration && key.equals(archiveStripRequestedKey))publishArchiveEntries(saved);});
                });
            }
        }
        long from=java.time.LocalDate.now().minusDays(1).atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli();
        List<U7dCatalogEntry> out=new ArrayList<>();
        for(U7dCatalogEntry e:archiveState.getEntries())if(e.channelId.equals(c.id)&&e.start>=from)out.add(e);
        if (currentPlaybackU7dPreviewEntry != null && currentPlaybackU7dPreviewEntry.channelId.equals(c.id)
                && out.stream().noneMatch(e -> e.id.equals(currentPlaybackU7dPreviewEntry.id))) out.add(currentPlaybackU7dPreviewEntry);
        out.sort((a,b)->Long.compare(a.start,b.start));return out;
    }

    private void openMovistarIsmU7d(ChannelItem channel) {
        openArchiveCatalog(isU7dReplayItem(channel) ? currentPlaybackU7dChannel : channel, false);
    }

    private List<EpgRepository.EpgProgram> fetchMovistarIsmU7dPrograms(ChannelItem channel) throws Exception {
        List<EpgRepository.EpgProgram> programs;
        try {
            MovistarGuideRepository.Guide guide=directMovistarGuide().day(java.time.LocalDate.now(java.time.ZoneId.of("Europe/Madrid")).toString(),java.util.Collections.singletonList(channel));
            JSONObject identity=guide.identity(channel);
            programs=identity==null?new ArrayList<>():guide.programmes(channel,identity);
        }catch(Exception unavailable){programs=fetchMovistarIsmU7dProgramsFromBackend(channel);}
        if (!programs.isEmpty() || epgRepository == null) {
            return programs;
        }
        Log.i(TAG, "Movistar ISM U7D backend returned no matches, falling back to offline EPG channel=" + channel.id);
        return epgRepository.fetchPastChannelPrograms(channel, 80, 7);
    }

    private List<EpgRepository.EpgProgram> fetchMovistarIsmU7dProgramsFromBackend(ChannelItem channel) throws Exception {
        List<EpgRepository.EpgProgram> result = new ArrayList<>();
        if (channel == null || httpClient == null || baseUrl == null || baseUrl.trim().isEmpty()) {
            return result;
        }
        List<String> candidates = new ArrayList<>();
        addUniqueU7dBaseUrl(candidates, baseUrl);
        String token = catalogSnapshotStore == null ? "" : catalogSnapshotStore.getAccessToken();
        String deviceId = catalogSnapshotStore == null ? "" : catalogSnapshotStore.getDeviceId();
        Exception lastError = null;
        for (String candidateBaseUrl : candidates) {
            String url = buildMovistarU7dProgramsUrl(candidateBaseUrl, token, deviceId, channel);
            try {
                HttpClient.Response response = httpClient.get(url, 10000, 25000, buildAuthenticatedJsonHeaders());
                if (response == null || !response.isSuccessful()) {
                    int code = response == null ? 0 : response.code;
                    Log.w(TAG, "Movistar ISM U7D programs endpoint failed host=" + safeLogHost(candidateBaseUrl) + " http=" + code);
                    lastError = new IllegalStateException("cargando U7D Movistar: HTTP " + code);
                    continue;
                }
                Log.i(TAG, "Movistar ISM U7D programs endpoint ok host=" + safeLogHost(candidateBaseUrl));
                return parseMovistarU7dProgramsPayload(channel, response.body);
            } catch (Exception e) {
                Log.w(TAG, "Movistar ISM U7D programs endpoint exception host=" + safeLogHost(candidateBaseUrl), e);
                lastError = e;
            }
        }
        if (lastError != null) {
            throw lastError;
        }
        return result;
    }

    private void addUniqueU7dBaseUrl(List<String> candidates, String value) {
        String normalized = normalizeBaseUrl(value);
        if (normalized.isEmpty() || candidates.contains(normalized)) {
            return;
        }
        candidates.add(normalized);
    }

    private String buildMovistarU7dProgramsUrl(String candidateBaseUrl, String token, String deviceId, ChannelItem channel) {
        Uri.Builder uriBuilder = Uri.parse(candidateBaseUrl).buildUpon()
                .appendPath("api")
                .appendPath("offline")
                .appendPath("u7d")
                .appendPath(isOrangeChannel(channel) ? "orange" : "movistar-ism")
                .appendPath("programs");
        if (channel != null) {
            if (channel.id != null && !channel.id.trim().isEmpty()) {
                uriBuilder.appendQueryParameter("channel_id", channel.id.trim());
            }
            if (channel.tvgId != null && !channel.tvgId.trim().isEmpty()) {
                uriBuilder.appendQueryParameter("tvg_id", channel.tvgId.trim());
            }
            String channelName = displayName(channel);
            if (channelName != null && !channelName.trim().isEmpty()) {
                uriBuilder.appendQueryParameter("channel_name", channelName.trim());
            }
        }
        if (token != null && !token.trim().isEmpty()) {
            uriBuilder.appendQueryParameter("access_token", token.trim());
        }
        if (deviceId != null && !deviceId.trim().isEmpty()) {
            uriBuilder.appendQueryParameter("device_id", deviceId.trim());
        }
        return uriBuilder.build().toString();
    }

    private List<EpgRepository.EpgProgram> parseMovistarU7dProgramsPayload(ChannelItem channel, String responseBody) throws Exception {
        String body = responseBody == null ? "" : responseBody.trim();
        return parseMovistarU7dProgramsObject(channel,body.startsWith("[")?new JSONArray(body):new JSONObject(body));
    }

    private String archiveProgramTitle(JSONObject p) {
        String title=firstNonEmpty(p.optString("display_name",""),p.optString("title",""));
        String category=p.optString("genre","").toLowerCase(Locale.ROOT);
        String event=firstNonEmpty(p.optString("title_ep",""),p.optString("event_title",""),p.optString("subtitle",""));
        if((category.contains("deport")||category.contains("fútbol")||category.contains("sport")) && event.matches(".+\\s(?:-|–|vs\\.?)\\s.+") && !title.contains(event)) {
            return firstNonEmpty(p.optString("competition",""),p.optString("title_serie",""),title)+": "+event;
        }
        return title;
    }

    private List<EpgRepository.EpgProgram> parseMovistarU7dProgramsObject(ChannelItem channel,Object data) throws Exception {
        List<EpgRepository.EpgProgram> result = new ArrayList<>();
        if(data instanceof JSONArray)return parseFlatMovistarU7dPrograms(channel,(JSONArray)data);
        JSONObject payload=(JSONObject)data;
        JSONArray channelRows = payload.optJSONArray("channels");
        JSONArray flatRows = payload.optJSONArray("programs");
        if (flatRows != null) {
            return parseFlatMovistarU7dPrograms(channel, flatRows);
        }
        if (channelRows == null) {
            return result;
        }
        for (int i = 0; i < channelRows.length(); i++) {
            JSONObject row = channelRows.optJSONObject(i);
            if (!matchesMovistarU7dChannel(channel, row)) {
                continue;
            }
            if(archiveAvailability!=null && !isOrangeChannel(channel))archiveAvailability.register(archiveScope,channel,row.optString("code",""));
            JSONArray programRows = row.optJSONArray("programs");
            if (programRows == null) {
                continue;
            }
            for (int j = 0; j < programRows.length(); j++) {
                JSONObject program = programRows.optJSONObject(j);
                if (program == null) {
                    continue;
                }
                String start = firstNonEmpty(program.optString("start_dt", ""), program.optString("start_iso", ""));
                String end = firstNonEmpty(program.optString("end_iso", ""), program.optString("end_dt", ""));
                if (parseIsoMillis(start) <= 0L || parseIsoMillis(end) <= 0L) {
                    continue;
                }
                String title = archiveProgramTitle(program);
                String icon = isOrangeChannel(channel)
                        ? firstNonEmpty(channel.logoUrl, program.optString("logo", ""), program.optString("poster", ""))
                        : firstNonEmpty(program.optString("poster", ""), program.optString("logo", ""), row.optString("logo", ""), channel.logoUrl);
                String description = firstNonEmpty(program.optString("description", ""), program.optString("genre", ""));
                result.add(new EpgRepository.EpgProgram(
                        channel.id,
                        ArchiveText.channel(displayName(channel),row.optString("name","")),
                        channel.tvgId,
                        title,
                        icon,
                        description,
                        start,
                        end,
                        program.optString("genre", ""),
                        0
                ));
            }
            Log.i(TAG, "Movistar ISM U7D matched channel=" + displayName(channel) + " backend=" + row.optString("name", "") + " programs=" + result.size());
            return result;
        }
        return result;
    }

    private String safeLogHost(String value) {
        try {
            Uri uri = Uri.parse(value == null ? "" : value.trim());
            String host = uri.getHost();
            return host == null ? "" : host;
        } catch (Exception e) {
            return "";
        }
    }

    private List<EpgRepository.EpgProgram> parseFlatMovistarU7dPrograms(ChannelItem channel, JSONArray programRows) {
        List<EpgRepository.EpgProgram> result = new ArrayList<>();
        if (channel == null || programRows == null) {
            return result;
        }
        for (int i = 0; i < programRows.length(); i++) {
            JSONObject program = programRows.optJSONObject(i);
            if (program == null || !matchesFlatMovistarU7dProgram(channel, program)) {
                continue;
            }
            if(archiveAvailability!=null && !isOrangeChannel(channel))archiveAvailability.register(archiveScope,channel,program.optString("channel_code",""));
            String start = firstNonEmpty(program.optString("start_dt", ""), program.optString("start_iso", ""));
            String end = firstNonEmpty(program.optString("end_iso", ""), program.optString("end_dt", ""));
            if (parseIsoMillis(start) <= 0L || parseIsoMillis(end) <= 0L) {
                continue;
            }
            String title = archiveProgramTitle(program);
            String icon = isOrangeChannel(channel)
                    ? firstNonEmpty(channel.logoUrl, program.optString("logo", ""), program.optString("poster", ""))
                    : firstNonEmpty(program.optString("poster", ""), program.optString("logo", ""), channel.logoUrl);
            String description = firstNonEmpty(program.optString("description", ""), program.optString("genre", ""));
            result.add(new EpgRepository.EpgProgram(
                    channel.id,
                    ArchiveText.channel(displayName(channel),program.optString("channel_name","")),
                    channel.tvgId,
                    title,
                    icon,
                    description,
                    start,
                    end,
                    program.optString("genre", ""),
                    0
            ));
        }
        Log.i(TAG, "Movistar ISM U7D flat report matched channel=" + displayName(channel) + " programs=" + result.size());
        return result;
    }

    private boolean matchesFlatMovistarU7dProgram(ChannelItem channel, JSONObject program) {
        if (channel == null || program == null) {
            return false;
        }
        String backendCode = normalizeU7dMatchText(program.optString("channel_code", ""));
        String backendName = normalizeU7dMatchText(program.optString("channel_name", ""));
        String channelTvg = normalizeU7dMatchText(channel.tvgId);
        String channelName = normalizeU7dMatchText(displayName(channel));
        String rawName = normalizeU7dMatchText(channel.name);
        return u7dTextMatches(channelTvg, backendCode)
                || u7dTextMatches(channelTvg, backendName)
                || u7dTextMatches(channelName, backendName)
                || u7dTextMatches(rawName, backendName)
                || u7dTextMatches(channelName, backendCode)
                || u7dTextMatches(rawName, backendCode);
    }

    private boolean matchesMovistarU7dChannel(ChannelItem channel, JSONObject row) {
        if (channel == null || row == null) {
            return false;
        }
        String backendCode = normalizeU7dMatchText(row.optString("code", ""));
        String backendName = normalizeU7dMatchText(row.optString("name", ""));
        String channelTvg = normalizeU7dMatchText(channel.tvgId);
        String channelName = normalizeU7dMatchText(displayName(channel));
        String rawName = normalizeU7dMatchText(channel.name);
        return u7dTextMatches(channelTvg, backendCode)
                || u7dTextMatches(channelTvg, backendName)
                || u7dTextMatches(channelName, backendName)
                || u7dTextMatches(rawName, backendName)
                || u7dTextMatches(channelName, backendCode)
                || u7dTextMatches(rawName, backendCode);
    }

    private boolean u7dTextMatches(String left, String right) {
        if (left == null || right == null || left.isEmpty() || right.isEmpty()) {
            return false;
        }
        return U7dChannelIdentity.matches(left, right);
    }

    private String normalizeU7dMatchText(String value) {
        return U7dChannelIdentity.normalize(value);
    }

    private String firstNonEmpty(String... values) {
        if (values == null) {
            return "";
        }
        for (String value : values) {
            if (value != null && !value.trim().isEmpty()) {
                return value.trim();
            }
        }
        return "";
    }

    private void showMovistarIsmU7dMenu(ChannelItem channel, List<EpgRepository.EpgProgram> programs) {
        if (channel == null || programs == null || programs.isEmpty()) {
            showStatus(getString(R.string.status_u7d_empty));
            return;
        }
        prepareModalSurface();
        final Dialog[] holder = new Dialog[1];
        List<U7dBrowserRow> rows = new ArrayList<>();
        List<EpgRepository.EpgProgram> ordered = new ArrayList<>(programs);
        ordered.sort((a, b) -> Long.compare(b == null ? 0L : parseIsoMillis(b.startTime), a == null ? 0L : parseIsoMillis(a.startTime)));
        for (EpgRepository.EpgProgram program : ordered) {
            if (program == null || parseIsoMillis(program.startTime) <= 0L || parseIsoMillis(program.endTime) <= 0L) {
                continue;
            }
            long start = parseIsoMillis(program.startTime);
            long end = parseIsoMillis(program.endTime);
            if (end <= start) continue;
            String day = new SimpleDateFormat("EEE d MMM yyyy", Locale.getDefault()).format(new Date(start));
            String title = program.title == null || program.title.trim().isEmpty() ? displayName(channel) : program.title.trim();
            String meta = shortTime(program.startTime) + " – " + shortTime(program.endTime)
                    + " · " + formatDurationShort(end - start);
            String description = program.description == null || program.description.trim().isEmpty()
                    ? getString(R.string.timeline_program_desc_empty) : program.description.trim();
            String artwork = ProgramArtworkResolver.resolve(program, channel);
            rows.add(new U7dBrowserRow(day, title, meta, description,
                    image -> bindProgramPoster(image, artwork),
                    () -> dismissModalForNextAction(holder[0], () -> playMovistarIsmU7dProgram(channel, program)), start));
        }
        if (rows.isEmpty()) {
            showStatus(getString(R.string.status_u7d_empty));
            return;
        }
        ComposeView view = new ComposeView(this);
        attachDialogViewTreeOwners(view);
        U7dBrowserComposeBinder.bind(view, channel.id, getString(R.string.u7d_menu_title, displayName(channel)), rows,
                () -> { if (holder[0] != null) holder[0].dismiss(); });
        holder[0] = ComposeDialogHost.showFullscreen(this, view, this::handleModalDismissed);
        handleModalShown();
    }

    private boolean isTouchControlsVisibleForRemote() {
        return !touchDeviceMode && touchControlsBar != null && touchControlsBar.getVisibility() == View.VISIBLE;
    }

    private boolean isTouchControlsExpandedForRemote() {
        return !compactPlaybackHud;
    }

    private void hideTouchControlsForRemote() {
        if (touchControlsController != null) {
            touchControlsController.hideAllTransientControls();
            touchControlsController.cancelTimers();
        }
        if (touchControlsBar != null) {
            touchControlsBar.setVisibility(View.GONE);
        }
        if (timeshiftBarContainer != null) {
            timeshiftBarContainer.setVisibility(View.GONE);
        }
        overlaySurfaceState.setVisible(OfflineOverlayState.Surface.TOUCH_CONTROLS, false);
        overlaySurfaceState.setVisible(OfflineOverlayState.Surface.TIMESHIFT, false);
        touchControlsFocusState.clear();
        currentTouchControlsBarModel = null;
        compactPlaybackHud = false;
    }

    private void resetTouchControlsFocus() {
        touchControlsFocusState.reset(firstEnabledTouchActionIndex());
        refreshTouchControlsBar();
        updateTimeshiftBar();
    }

    private int firstEnabledTouchActionIndex() {
        TouchControlsBarUiModel model = currentTouchControlsBarModel;
        if (model == null || model.actions == null || model.actions.isEmpty()) {
            return 0;
        }
        for (int i = 0; i < model.actions.size(); i++) {
            ZapActionItem item = model.actions.get(i);
            if (item != null && item.enabled) {
                return i;
            }
        }
        return 0;
    }

    private void moveTouchControlsFocus(int delta) {
        TouchControlsBarUiModel model = currentTouchControlsBarModel;
        if (model == null || model.actions == null || model.actions.isEmpty()) {
            refreshTouchControlsBar();
            return;
        }
        boolean moved = touchControlsFocusState.moveToNextEnabledAction(delta, model.actions.size(), index -> {
            ZapActionItem item = model.actions.get(index);
            return item != null && item.enabled;
        });
        if (moved) {
            refreshTouchControlsBar();
            scheduleTouchControlsAutoHide();
        }
    }

    private boolean isTouchControlsTimeshiftFocused() {
        return touchControlsFocusState.timeshiftFocused();
    }

    private boolean canSeekPlaybackBack() {
        PlayerController.PlaybackSeekState state = getEffectivePlaybackSeekState();
        return state != null && state.currentMs > state.startMs;
    }

    private boolean canSeekPlaybackForward() {
        PlayerController.PlaybackSeekState state = getEffectivePlaybackSeekState();
        return state != null && state.currentMs < state.endMs;
    }

    private boolean canResumeLivePlayback() {
        if (isCurrentU7dPlayback()) return currentPlaybackU7dChannel != null;
        if (isCurrentOrangeVirtualTimeshiftPlayback()) {
            ChannelItem liveChannel = findChannelItemById(lastChannelId);
            return liveChannel != null && isOrangeChannel(liveChannel);
        }
        PlayerController.PlaybackSeekState state = getEffectivePlaybackSeekState();
        return state != null && state.liveCapable && state.currentMs < state.endMs;
    }

    private boolean resumeCurrentPlaybackLive() {
        if (isCurrentU7dPlayback()) { returnToLiveTv(); return true; }
        if (isCurrentOrangeVirtualTimeshiftPlayback()) {
            ChannelItem liveChannel = findChannelItemById(lastChannelId);
            if (liveChannel != null && isOrangeChannel(liveChannel)) {
                clearCurrentU7dPlayback();
                playChannelItemInternal(liveChannel, true, 0L);
                return true;
            }
        }
        return playerController != null && playerController.resumeTimeshiftLive();
    }

    private boolean seekTouchControlsBack() {
        if (isCurrentOrangeVirtualTimeshiftPlayback()) {
            PlayerController.PlaybackSeekState state = getEffectivePlaybackSeekState();
            seekOrangeLiveArchiveTo(state.currentMs - 30_000L);
            return true;
        }
        if (isCurrentU7dPlayback()) {
            PlayerController.PlaybackSeekState state = getCurrentU7dSeekState();
            if (state == null) {
                return false;
            }
            seekCurrentU7dPlaybackTo(state.currentMs - 30_000L);
            return true;
        }
        if (isCurrentOrangeLivePlayback()) {
            PlayerController.PlaybackSeekState state = getEffectivePlaybackSeekState();
            seekOrangeLiveArchiveTo(state.currentMs - 30_000L);
            return true;
        }
        return playerController != null && playerController.seekTimeshiftBack();
    }

    private boolean seekTouchControlsForward() {
        if (isCurrentOrangeVirtualTimeshiftPlayback()) {
            PlayerController.PlaybackSeekState state = getEffectivePlaybackSeekState();
            if (state.currentMs + 30_000L >= state.endMs) {
                ChannelItem liveChannel = findChannelItemById(lastChannelId);
                if (liveChannel != null) {
                    clearCurrentU7dPlayback();
                    playChannelItemInternal(liveChannel, true, 0L);
                    return true;
                }
            }
            seekOrangeLiveArchiveTo(state.currentMs + 30_000L);
            return true;
        }
        if (isCurrentU7dPlayback()) {
            PlayerController.PlaybackSeekState state = getCurrentU7dSeekState();
            if (state == null) {
                return false;
            }
            seekCurrentU7dPlaybackTo(state.currentMs + 30_000L);
            return true;
        }
        if (isCurrentOrangeLivePlayback()) {
            return false;
        }
        return playerController != null && playerController.seekTimeshiftForward();
    }

    private void focusTouchControlsTimeshift() {
        if (getEffectivePlaybackSeekState() == null) {
            showStatus(getString(R.string.timeshift_status_unavailable));
            scheduleTouchControlsAutoHide();
            return;
        }
        touchControlsFocusState.focusTimeshift();
        updateTimeshiftBar();
        scheduleTouchControlsAutoHide();
    }

    private void focusTouchControlsActions() {
        if (!touchControlsFocusState.focusActionsIfNeeded()) {
            scheduleTouchControlsAutoHide();
            return;
        }
        refreshTouchControlsBar();
        updateTimeshiftBar();
        scheduleTouchControlsAutoHide();
    }

    private void activateTouchControlsFocus() {
        TouchControlsBarUiModel model = currentTouchControlsBarModel;
        if (model == null || model.actions == null || model.actions.isEmpty()) {
            refreshTouchControlsBar();
            return;
        }
        int index = Math.max(0, Math.min(model.actions.size() - 1, touchControlsFocusState.actionIndex()));
        ZapActionItem item = model.actions.get(index);
        Log.w(TAG, "touch controls activate index=" + index
                + " label=" + (item == null ? "null" : item.label)
                + " enabled=" + (item != null && item.enabled));
        if (item != null && item.enabled && item.onClick != null) {
            item.onClick.run();
        } else {
            scheduleTouchControlsAutoHide();
        }
    }

    private String formatU7dProgramLabel(EpgRepository.EpgProgram program) {
        long startMs = parseIsoMillis(program.startTime);
        long endMs = parseIsoMillis(program.endTime);
        String day = startMs <= 0L ? "" : new SimpleDateFormat("EEE d MMM", Locale.getDefault()).format(new Date(startMs));
        String title = program.title == null || program.title.trim().isEmpty()
                ? getString(R.string.diagnostics_value_unknown)
                : program.title.trim();
        String duration = endMs > startMs ? " · " + formatDurationShort(endMs - startMs) : "";
        return day + " · " + shortTime(program.startTime) + "  " + title + duration;
    }

    private void playMovistarIsmU7dProgram(ChannelItem channel, EpgRepository.EpgProgram program) {
        playMovistarIsmU7dProgram(channel, program, 0L);
    }

    private void playMovistarIsmU7dProgram(
            ChannelItem channel,
            EpgRepository.EpgProgram program,
            long requestedOffsetMs
    ) {
        if (channel == null || program == null) {
            showStatus(getString(R.string.status_u7d_unavailable));
            return;
        }
        cancelPendingU7dSeek();
        if (touchHomeHub != null) touchHomeHub.setVisibility(View.GONE);
        hideOverlay();
        hideZapBanner();
        String baseReplayUrl = buildMovistarIsmU7dUrl(channel, program);
        if (baseReplayUrl.isEmpty()) {
            showStatus(getString(R.string.status_u7d_unavailable));
            return;
        }
        long startMs = parseIsoMillis(program.startTime);
        long endMs = parseIsoMillis(program.endTime);
        long durationMs = Math.max(0L, endMs - startMs);
        long offsetMs = Math.max(0L, Math.min(Math.max(0L, durationMs - 1_000L), requestedOffsetMs));
        String replayUrl = buildU7dUrlWithOffset(baseReplayUrl, offsetMs);
        String programTitle = program.title == null || program.title.trim().isEmpty()
                ? displayName(channel)
                : program.title.trim();
        ChannelItem replayItem = new ChannelItem(
                "u7d:" + channel.id + ":" + Math.max(0L, startMs),
                programTitle,
                channel.tvgId,
                ProgramArtworkResolver.resolve(program, channel),
                getString(R.string.u7d_replay_group),
                replayUrl,
                "",
                channel.originalOrder,
                channel.dashboardOrder,
                false,
                false,
                channel.platformId,
                getString(isOrangeChannel(channel)
                        ? R.string.u7d_replay_platform_orange
                        : R.string.u7d_replay_platform),
                new ArrayList<>(),
                "",
                "",
                "",
                true,
                program.description,
                "",
                endMs > startMs ? (endMs - startMs) / 1000L : 0L,
                "u7d_proxy"
        );
        replayItem.nowProgram = programTitle;
        replayItem.nextProgram = "";
        epgProgramPairByChannelId.put(
                replayItem.id,
                new EpgRepository.EpgProgramPair(program, null)
        );
        currentPlaybackU7dChannel = channel;
        currentPlaybackU7dPreviewEntry = null;
        for (U7dCatalogEntry e : archiveState.getEntries()) {
            if (e.channelId.equals(channel.id) && e.start == startMs) { currentPlaybackU7dPreviewEntry = e; break; }
        }
        if (currentPlaybackU7dPreviewEntry == null) {
            String fanart = archiveFanart == null ? null : archiveFanart.find(displayName(channel), program.tvgId, startMs, program.title);
            currentPlaybackU7dPreviewEntry = new U7dCatalogEntry(U7dCatalogStore.id(program), channel.id, displayName(channel), programTitle,
                    program.category, program.description, java.time.Instant.ofEpochMilli(startMs).atZone(java.time.ZoneId.systemDefault()).toLocalDate().toString(),
                    startMs, endMs, false, image -> bindMovistarArchiveArtwork(image,channel,program,fanart),
                    () -> playMovistarIsmU7dProgram(channel, program), () -> returnToLiveTv(), () -> {});
            currentPlaybackU7dPreviewEntry.programmeMetadata=programmeMetadata(channel,program);
            currentPlaybackU7dPreviewEntry.hasProgramArtwork = fanart != null || (!ProgramArtworkResolver.resolve(program.icon, "").isEmpty() && !ProgramArtworkResolver.resolve(program.icon, "").equals(channel.logoUrl));
            currentPlaybackU7dPreviewEntry.artworkKey = fanart != null ? fanart : ProgramArtworkResolver.resolve(program, channel);
        }
        u7dRecoveryAttempts = 0;
        u7dLastRecoveryPosition = offsetMs;
        currentPlaybackU7dBaseUrl = baseReplayUrl;
        currentPlaybackU7dDurationMs = durationMs;
        currentPlaybackU7dOffsetMs = offsetMs;
        currentPlaybackU7dProgramStartMs = startMs;
        currentPlaybackU7dProgramEndMs = endMs;
        currentPlaybackU7dItem = replayItem;
        currentPlaybackTransientItem = replayItem;
        String previousLastChannelId = lastChannelId;
        Log.i(TAG, "Opening selected catchup programme");
        playChannelItemInternal(replayItem, true, 0L);
        if (previousLastChannelId != null && !previousLastChannelId.trim().isEmpty()) {
            saveLastChannelId(previousLastChannelId);
        } else if (channel.id != null && !channel.id.trim().isEmpty()) {
            saveLastChannelId(channel.id);
        }
        updateVodLoadingState(
                replayItem,
                getString(R.string.u7d_loading_title),
                getString(R.string.u7d_loading_step_manifest),
                getString(R.string.u7d_loading_detail_manifest)
        );
    }

    private String buildMovistarIsmU7dUrl(ChannelItem channel, EpgRepository.EpgProgram program) {
        if (channel == null || program == null || baseUrl == null || baseUrl.trim().isEmpty()) {
            return "";
        }
        try {
            Uri.Builder builder = Uri.parse(resolveMovistarU7dStreamBaseUrl()).buildUpon()
                    .appendPath("api")
                    .appendPath("offline")
                    .appendPath("u7d")
                    .appendPath(isOrangeChannel(channel) ? "orange" : "movistar-ism")
                    .appendPath("stream")
                    .appendQueryParameter("channel_id", channel.id)
                    .appendQueryParameter("tvg_id", channel.tvgId)
                    .appendQueryParameter("channel_name", displayName(channel))
                    .appendQueryParameter("start_time", program.startTime)
                    .appendQueryParameter("end_time", program.endTime)
                    .appendQueryParameter("title", program.title);
            if (!isOrangeChannel(channel) && "beta".equals(BuildConfig.UPDATE_CHANNEL)) {
                builder.appendQueryParameter("native_channel", "1");
            }
            if (!isOrangeChannel(channel) && "beta".equals(BuildConfig.UPDATE_CHANNEL)
                    && !"MPEG-TS".equals(archiveState.getFormat())) {
                builder.appendQueryParameter("transport", "buffered_hls");
                builder.appendQueryParameter("buffer_profile", "extended_v1");
            }
            String token = catalogSnapshotStore == null ? "" : catalogSnapshotStore.getAccessToken();
            if (token != null && !token.trim().isEmpty()) {
                builder.appendQueryParameter("access_token", token.trim());
            }
            String deviceId = catalogSnapshotStore == null ? "" : catalogSnapshotStore.getDeviceId();
            if (deviceId != null && !deviceId.trim().isEmpty()) {
                builder.appendQueryParameter("device_id", deviceId.trim());
            }
            return builder.build().toString();
        } catch (Exception e) {
            Log.w(TAG, "failed to build Movistar ISM U7D url", e);
            return "";
        }
    }

    private String resolveMovistarU7dStreamBaseUrl() {
        String normalized = normalizeBaseUrl(baseUrl);
        if (!normalized.isEmpty()) {
            return normalized;
        }
        return normalizeBaseUrl(BuildConfig.OFFLINE_BASE_URL);
    }

