    private void showVodInfoDialog(ChannelItem channel) {
        showVodInfoDialog(channel, null);
    }

    private void showVodInfoDialog(ChannelItem channel, Runnable onBack) {
        showVodInfoDialog(channel, onBack, true);
    }

    private void showVodInfoDialog(ChannelItem channel, Runnable onBack, boolean refreshMetadata) {
        if (channel == null) {
            return;
        }
        if (isPrimeSeriesGroup(channel)) {
            showPrimeSeriesEpisodes(channel, onBack);
            return;
        }
        if (isDisneyplusItem(channel) && !allowsDisneyplusVod()) {
            showStatus("Disney+ no está habilitado para este usuario");
            return;
        }
        if (isProtectedItem(channel) && isProtectedContentLocked()) {
            ensureParentalAccessForItem(channel, () -> showVodInfoDialog(channel, onBack));
            return;
        }
        if (channel.playUrl != null && channel.playUrl.startsWith("sky-series:")) {
            List<ChannelItem> authorized = new ArrayList<>();
            for (ChannelItem item : allChannels) {
                if (item != null && isVodItemAuthorized(item) && !shouldHideProtectedItem(item)) authorized.add(item);
            }
            showPagedVodLibraryList(channel.name, skySeriesEpisodes(channel, authorized), onBack, 0);
            return;
        }
        if (isDynamicSeriesGroup(channel)) {
            showDynamicSeriesEpisodes(channel, onBack);
            return;
        }
        rememberCurrentVodPosition();
        prepareModalSurface();
        long resumeMs = getVodResumePosition(channel.id);
        final Dialog[] dialogHolder = new Dialog[1];
        final boolean[] navigationHandled = {false};
        Runnable panelBackAction = onBack == null ? null : () -> {
            navigationHandled[0] = true;
            dismissModalForNextAction(dialogHolder[0], onBack);
        };
        List<VodPanelActionUiModel> primaryActions = new ArrayList<>();
        long nowMs = System.currentTimeMillis();
        boolean daznScheduled = DaznEventPolicy.isScheduled(channel);
        boolean daznPlayable = !daznScheduled || DaznEventPolicy.isPlayableNow(channel, nowMs);
        boolean daznLiveEvent = DaznEventPolicy.isLiveEventInProgress(channel, nowMs);
        Runnable playFromStart = () -> dismissModalForNextAction(dialogHolder[0], () -> {
            clearVodResumePosition(channel.id);
            playChannelItemInternal(channel, true, 0L);
        });
        Runnable playDaznFromBeginning = () -> dismissModalForNextAction(dialogHolder[0], () -> {
            clearVodResumePosition(channel.id);
            // A positive explicit seek selects the beginning of DAZN's dynamic
            // event window; zero leaves Media3 at the live default position.
            playChannelItemInternal(channel, true, 1L);
        });
        if (daznScheduled && DaznEventPolicy.isUpcoming(channel, nowMs)) {
            primaryActions.add(new VodPanelActionUiModel(
                    getString(R.string.dazn_event_watch_action),
                    true,
                    playFromStart,
                    DaznEventPolicy.playableAtMs(channel),
                    getString(R.string.dazn_event_countdown_prefix),
                    getString(R.string.dazn_event_watch_action)
            ));
        } else if (!daznPlayable) {
            primaryActions.add(new VodPanelActionUiModel(
                    DaznEventPolicy.eventState(channel, nowMs),
                    false,
                    null
            ));
        } else if (daznLiveEvent) {
            primaryActions.add(new VodPanelActionUiModel(
                    getString(R.string.dazn_event_join_live_action),
                    true,
                    playFromStart,
                    "live"
            ));
            primaryActions.add(new VodPanelActionUiModel(
                    getString(R.string.dazn_event_start_over_action),
                    true,
                    playDaznFromBeginning,
                    "start_over"
            ));
        } else if (resumeMs <= 30_000L) {
            primaryActions.add(new VodPanelActionUiModel(
                    getString(daznScheduled ? R.string.dazn_event_watch_action : R.string.vod_action_play),
                    true,
                    playFromStart
            ));
        } else {
            primaryActions.add(new VodPanelActionUiModel(
                    getString(R.string.vod_action_continue),
                    true,
                    () -> dismissModalForNextAction(
                            dialogHolder[0],
                            () -> playChannelItemInternal(channel, true, getVodResumePosition(channel.id))
                    )
            ));
            primaryActions.add(new VodPanelActionUiModel(
                    getString(R.string.vod_action_start_over),
                    true,
                    playFromStart
            ));
        }
        List<VodPanelActionUiModel> secondaryActions = new ArrayList<>();
        secondaryActions.add(new VodPanelActionUiModel(getString(R.string.vod_action_more_vod), false, () -> {
            dismissModalForNextAction(dialogHolder[0], () -> showVodActionsDialog(channel, () -> showVodInfoDialog(channel, onBack)));
        }));
        secondaryActions.add(new VodPanelActionUiModel(getString(favoriteChannelIds.contains(channel.id) ? R.string.vod_action_remove_favorite : R.string.vod_action_add_favorite), false, () -> toggleFavoriteForChannel(channel)));
        if (resumeMs > 30_000L) {
            secondaryActions.add(new VodPanelActionUiModel(getString(R.string.vod_action_clear_progress_vod), false, () -> {
                clearVodResumePosition(channel.id);
                showStatus(getString(R.string.vod_status_progress_cleared));
            }));
        }
        ComposeView composeView = new ComposeView(this);
        attachDialogViewTreeOwners(composeView);
        VodDetailPanelComposeBinder.bind(
                composeView,
                new VodDetailPanelUiModel(
                        channel.name == null || channel.name.trim().isEmpty() ? getString(R.string.label_program_default) : channel.name.trim(),
                        buildVodInfoMeta(channel),
                        buildVodDescription(channel),
                        resumeMs > 0L ? buildVodProgressLabel(channel, resumeMs) : "",
                        channel.logoUrl,
                        getString(R.string.vod_detail_primary_actions),
                        getString(R.string.vod_detail_secondary_actions),
                        getString(R.string.vod_detail_action_hint),
                        primaryActions,
                        secondaryActions,
                        panelBackAction
                ),
                (imageView, item) -> bindRecordingPoster(imageView, item == null ? "" : item.posterUrl)
        );
        Dialog dialog = ComposeDialogHost.showFullscreen(this, composeView, () -> {
            if (onBack != null) {
                modalReturnAction = onBack;
            }
        }, this::handleModalDismissed);
        dialogHolder[0] = dialog;
        if (onBack != null) {
            dialog.setOnKeyListener((ignored, keyCode, event) -> {
                if (keyCode == KeyEvent.KEYCODE_BACK && event.getAction() == KeyEvent.ACTION_UP && !navigationHandled[0]) {
                    panelBackAction.run();
                    return true;
                }
                return false;
            });
        }
        handleModalShown();
    }

    static boolean isDisneyplusItem(ChannelItem item) {
        return item != null && ((item.id != null && item.id.startsWith("disneyplus:"))
                || (item.vodFilterKey != null && item.vodFilterKey.startsWith("vod:disneyplus:")));
    }

    private boolean allowsDisneyplusVod() {
        return currentOfflinePermissions != null && currentOfflinePermissions.allowsDisneyplusVod();
    }

    static boolean isDynamicSeriesGroup(ChannelItem item) {
        return item != null
                && item.playUrl != null
                && (item.playUrl.startsWith("prime-series:") || item.playUrl.startsWith("disneyplus-series:") || item.playUrl.startsWith("sky-series:"));
    }

    private void showDynamicSeriesEpisodes(ChannelItem series, Runnable onBack) {
        if (catalogRepository == null || series == null) {
            return;
        }
        boolean disney = series.playUrl.startsWith("disneyplus-series:");
        if (disney && !allowsDisneyplusVod()) return;
        long request = disney ? disneyVodLoadState.begin(false) : 0L;
        OfflinePermissions requestedPermissions = currentOfflinePermissions;
        String requestedToken = catalogSnapshotStore == null ? "" : catalogSnapshotStore.getAccessToken();
        CatalogRepository repository = catalogRepository;
        String assetId = series.playUrl.substring((disney ? "disneyplus-series:" : "prime-series:").length()).trim();
        showLoading(getString(R.string.tools_section_vod), series.name, "Cargando temporadas y episodios");
        long overlayGeneration = loadingOverlayGeneration;
        interactiveExecutor.execute(() -> {
            List<ChannelItem> episodes = new ArrayList<>();
            Exception failure = null;
            try {
                episodes.addAll(disney ? repository.fetchDisneyplusSeriesEpisodes(assetId) : repository.fetchPrimeSeriesEpisodes(assetId));
            } catch (Exception e) {
                failure = e;
                Log.w(TAG, "VOD series episodes request failed", e);
            }
            Exception finalFailure = failure;
            postUiIfAlive(() -> {
                if (disney) {
                    if (!finishDisneyLoad(disneyVodLoadState, request, false, false,
                            overlayGeneration, loadingOverlayGeneration, this::hideStartupLoading)) return;
                    if (!canApplyDisneyResult(requestedPermissions, currentOfflinePermissions,
                            requestedToken, catalogSnapshotStore == null ? "" : catalogSnapshotStore.getAccessToken())) return;
                } else {
                    hideStartupLoading();
                }
                if (finalFailure != null) {
                    showStatus("No se pudieron cargar los episodios de " + (disney ? "Disney+" : "Prime Video"));
                    if (onBack != null) {
                        onBack.run();
                    }
                    return;
                }
                episodes.sort((left, right) -> {
                    int byOrder = Integer.compare(left == null ? 0 : left.originalOrder, right == null ? 0 : right.originalOrder);
                    return byOrder != 0 ? byOrder : displayName(left).compareToIgnoreCase(displayName(right));
                });
                showPagedVodLibraryList(series.name, episodes, onBack, 0);
            });
        });
    }

    private boolean isPrimeSeriesGroup(ChannelItem item) {
        return item != null
                && item.playUrl != null
                && item.playUrl.startsWith("prime-series:");
    }

    private void showPrimeSeriesEpisodes(ChannelItem series, Runnable onBack) {
        if (catalogRepository == null || series == null) {
            return;
        }
        String assetId = series.playUrl.substring("prime-series:".length()).trim();
        showLoading(getString(R.string.tools_section_vod), series.name, "Cargando temporadas y episodios");
        interactiveExecutor.execute(() -> {
            List<ChannelItem> episodes = new ArrayList<>();
            Exception failure = null;
            try {
                episodes.addAll(catalogRepository.fetchPrimeSeriesEpisodes(assetId));
            } catch (Exception e) {
                failure = e;
                Log.w(TAG, "Prime series episodes request failed series=" + series.name, e);
            }
            Exception finalFailure = failure;
            postUiIfAlive(() -> {
                hideStartupLoading();
                if (finalFailure != null) {
                    showStatus("No se pudieron cargar los episodios de Prime Video");
                    if (onBack != null) {
                        onBack.run();
                    }
                    return;
                }
                episodes.sort((left, right) -> {
                    int byOrder = Integer.compare(left == null ? 0 : left.originalOrder, right == null ? 0 : right.originalOrder);
                    return byOrder != 0 ? byOrder : displayName(left).compareToIgnoreCase(displayName(right));
                });
                showPagedVodLibraryList(series.name, episodes, onBack, 0);
            });
        });
    }

    private String buildVodProgressLabel(ChannelItem channel, long resumeMs) {
        String progress = getString(R.string.vod_resume_meta, formatDurationShort(resumeMs));
        if (channel != null && channel.vodDurationSeconds > 0L) {
            long durationMs = channel.vodDurationSeconds * 1000L;
            int percent = (int) Math.max(1L, Math.min(99L, (resumeMs * 100L) / Math.max(1L, durationMs)));
            return getString(R.string.vod_resume_meta_percent, formatDurationShort(resumeMs), percent);
        }
        return progress;
    }

