    private boolean isActiveScheduledRecording(RecordingsRepository.RecordingItem item) {
        if (item == null || item.status == null) {
            return false;
        }
        switch (item.status.trim().toLowerCase(Locale.US)) {
            case "recording":
            case "running":
            case "in_progress":
                return true;
            default:
                return false;
        }
    }

