    private void showScheduledRecordingEditDialog(RecordingsRepository.RecordingItem item) {
        if (showOfflineRecordingsUnavailableIfNeeded()) {
            return;
        }
        if (item == null || item.playable) {
            return;
        }
        String[] options = new String[]{
                getString(R.string.recording_action_shift_earlier),
                getString(R.string.recording_action_shift_later),
                getString(R.string.recording_action_extend),
                getString(R.string.recording_action_shorten)
        };
        List<String> labels = Arrays.asList(options);
        List<Runnable> actions = new ArrayList<>();
        actions.add(() -> adjustScheduledRecording(item, -15L * 60L * 1000L, -15L * 60L * 1000L));
        actions.add(() -> adjustScheduledRecording(item, 15L * 60L * 1000L, 15L * 60L * 1000L));
        actions.add(() -> adjustScheduledRecording(item, 0L, 15L * 60L * 1000L));
        actions.add(() -> adjustScheduledRecording(item, 0L, -15L * 60L * 1000L));
        showTvOptionsDialog(R.string.title_recording_edit_time, null, labels, actions);
    }

    private void adjustSelectedScheduledRecording(long startDeltaMs, long endDeltaMs) {
        if (showOfflineRecordingsUnavailableIfNeeded()) {
            return;
        }
        RecordingsRepository.RecordingItem item = getSelectedRecordingItem();
        adjustScheduledRecording(item, startDeltaMs, endDeltaMs);
    }

    private void adjustScheduledRecording(RecordingsRepository.RecordingItem item, long startDeltaMs, long endDeltaMs) {
        if (showOfflineRecordingsUnavailableIfNeeded()) {
            return;
        }
        if (item == null || item.playable) {
            return;
        }
        long startMs = parseIsoMillis(item.startTime);
        long endMs = parseIsoMillis(item.endTime);
        if (startMs <= 0L || endMs <= 0L) {
            showStatus(getString(R.string.status_failed_update_scheduled_recording));
            return;
        }
        long updatedStart = startMs + startDeltaMs;
        long updatedEnd = endMs + endDeltaMs;
        if (updatedEnd <= updatedStart) {
            showStatus(getString(R.string.status_invalid_scheduled_recording_window));
            return;
        }
        showStatus(getString(R.string.status_updating_scheduled_recording));
        ioExecutor.execute(() -> {
            try {
                recordingsRepository.updateScheduledRecording(item.id, formatIsoMillis(updatedStart), formatIsoMillis(updatedEnd));
                postUiIfAlive(() -> {
                    showStatus(getString(R.string.status_scheduled_recording_updated));
                    refreshRecordingsPanel();
                });
            } catch (Exception e) {
                Log.w(TAG, "update scheduled recording failed", e);
                postUiIfAlive(() -> showStatus(getString(R.string.status_failed_update_scheduled_recording)));
            }
        });
    }

    private void playRecording(RecordingsRepository.RecordingItem item, String basePath) {
        if (showOfflineRecordingsUnavailableIfNeeded()) {
            return;
        }
        if (item == null || !item.playable) {
            showStatus(getString(R.string.status_recording_not_playable));
            return;
        }
        rememberCurrentVodPosition();
        currentPlaybackVodId = null;
        String url = recordingsRepository.buildPlaybackUrl(item, basePath);
        currentPlaybackRecordingId = item.id;
        currentPlaybackReturnChannelId = getCurrentChannelId();
        long resumePositionMs = getRecordingResumePosition(item.id);
        Runnable startFromBeginning = () -> {
            clearRecordingResumePosition(item.id);
            cancelRemoteZap();
            playerController.playRecording(buildRecordingTitle(item), url, 0L);
            hideRecordingsPanel();
            hideOverlay();
        };
        Runnable resumeFromSaved = () -> {
            cancelRemoteZap();
            playerController.playRecording(buildRecordingTitle(item), url, resumePositionMs);
            hideRecordingsPanel();
            hideOverlay();
        };
        if (resumePositionMs > 30_000L) {
            List<TvMessageActionUiModel> actions = new ArrayList<>();
            actions.add(new TvMessageActionUiModel(getString(R.string.recording_resume_continue), false, resumeFromSaved));
            actions.add(new TvMessageActionUiModel(getString(R.string.recording_resume_restart), true, startFromBeginning));
            showTvMessagePanel(getString(R.string.title_recordings_visual), getString(R.string.recording_resume_prompt, formatPlaybackPosition(resumePositionMs)), actions, null);
            return;
        }
        startFromBeginning.run();
    }

    private RecordingsRepository.RecordingItem getSelectedRecordingItem() {
        return recordingsController.getSelectedItem();
    }

    private void showRecordingActionsDialog() {
        RecordingsRepository.RecordingItem item = getSelectedRecordingItem();
        if (item == null) {
            return;
        }
        RecordingsRepository.RecordingsResult selectedResult = recordingsController.getCurrentResult();
        String selectedBasePath = selectedResult == null ? "" : selectedResult.basePath;
        prepareModalSurface();
        final Dialog[] dialogHolder = new Dialog[1];
        List<VodPanelActionUiModel> primaryActions = new ArrayList<>();
        List<VodPanelActionUiModel> secondaryActions = new ArrayList<>();
        if (item.playable) {
            primaryActions.add(new VodPanelActionUiModel(
                    getString(R.string.recording_action_play),
                    true,
                    () -> dismissModalForNextAction(dialogHolder[0], () -> playRecording(item, selectedBasePath))
            ));
            if (getRecordingResumePosition(item.id) > 30_000L) {
                secondaryActions.add(new VodPanelActionUiModel(
                        getString(R.string.recording_action_clear_progress),
                        false,
                        () -> dismissModalForNextAction(dialogHolder[0], () -> clearSelectedRecordingProgress(item))
                ));
            }
            secondaryActions.add(new VodPanelActionUiModel(
                    getString(R.string.recording_action_delete),
                    false,
                    () -> dismissModalForNextAction(dialogHolder[0], () -> confirmDeleteCompletedRecording(item))
            ));
        } else {
            if (isActiveScheduledRecording(item)) {
                primaryActions.add(new VodPanelActionUiModel(
                        getString(R.string.recording_action_stop),
                        true,
                        () -> dismissModalForNextAction(dialogHolder[0], () -> confirmStopScheduledRecording(item))
                ));
            } else {
                primaryActions.add(new VodPanelActionUiModel(
                        getString(R.string.recording_action_edit_time),
                        true,
                        () -> dismissModalForNextAction(dialogHolder[0], () -> showScheduledRecordingEditDialog(item))
                ));
                secondaryActions.add(new VodPanelActionUiModel(
                        getString(R.string.recording_action_cancel),
                        false,
                        () -> dismissModalForNextAction(dialogHolder[0], () -> confirmCancelScheduledRecording(item))
                ));
            }
        }
        secondaryActions.add(new VodPanelActionUiModel(
                getString(R.string.recording_action_more),
                false,
                () -> dismissModalForNextAction(dialogHolder[0], () -> showRecordingManagementActionsDialog(item))
        ));
        Runnable closeAction = () -> {
            if (dialogHolder[0] != null) {
                dialogHolder[0].dismiss();
            }
        };
        secondaryActions.add(new VodPanelActionUiModel(getString(R.string.dialog_close), false, closeAction));

        ComposeView composeView = new ComposeView(this);
        attachDialogViewTreeOwners(composeView);
        VodDetailPanelComposeBinder.bind(
                composeView,
                new VodDetailPanelUiModel(
                        buildRecordingTitle(item),
                        buildRecordingMeta(item),
                        buildRecordingDescription(item),
                        "",
                        item.poster,
                        getString(R.string.recording_detail_primary_actions),
                        getString(R.string.recording_detail_secondary_actions),
                        getString(R.string.recording_detail_action_hint),
                        primaryActions,
                        secondaryActions,
                        closeAction
                ),
                (imageView, model) -> bindRecordingPoster(imageView, model == null ? "" : model.posterUrl)
        );
        Dialog dialog = ComposeDialogHost.showFullscreen(this, composeView, null, this::handleModalDismissed);
        dialogHolder[0] = dialog;
    }

    private void showRecordingManagementActionsDialog(RecordingsRepository.RecordingItem item) {
        List<String> options = new ArrayList<>();
        List<Runnable> actions = new ArrayList<>();
        options.add(getString(R.string.recording_action_refresh));
        actions.add(this::refreshRecordingsPanel);
        options.add(getString(recordingsPanelController.isAutoRefreshEnabled() ? R.string.recording_action_auto_refresh_on : R.string.recording_action_auto_refresh_off));
        actions.add(this::toggleRecordingsAutoRefresh);
        options.add(getString(recordingsController.isScheduledMode() ? R.string.recording_action_switch_completed : R.string.recording_action_switch_scheduled));
        actions.add(() -> switchRecordingsMode(!recordingsController.isScheduledMode()));
        addRecordingFilterActions(options, actions, item);
        showTvOptionsDialog(R.string.title_recording_actions, null, options, actions);
    }

    private void confirmDeleteCompletedRecording(RecordingsRepository.RecordingItem item) {
        if (item == null || !item.playable) {
            return;
        }
        if (!canDeleteRecordings()) {
            showStatus(getString(R.string.status_recording_delete_permission_denied));
            return;
        }
        if (item.recordingId <= 0L && item.relatedPaths.isEmpty()) {
            showStatus(getString(R.string.status_recording_delete_unavailable));
            return;
        }
        List<TvMessageActionUiModel> actions = new ArrayList<>();
        actions.add(new TvMessageActionUiModel(
                getString(R.string.recording_action_delete_confirm),
                true,
                () -> deleteCompletedRecording(item)
        ));
        actions.add(new TvMessageActionUiModel(getString(R.string.dialog_cancel), false, null));
        showTvMessagePanel(
                getString(R.string.title_recording_delete_confirm),
                getString(R.string.recording_delete_confirm_message, buildRecordingTitle(item), buildRecordingMeta(item)),
                actions,
                null
        );
    }

    private void deleteCompletedRecording(RecordingsRepository.RecordingItem item) {
        if (item == null || !item.playable) {
            return;
        }
        showStatus(getString(R.string.status_deleting_recording));
        ioExecutor.execute(() -> {
            try {
                if (item.recordingId > 0L) {
                    recordingsRepository.deleteCompletedRecordings(item.relatedRecordingIds);
                } else {
                    recordingsRepository.deleteLegacyCompletedRecordings(item.relatedPaths);
                }
                postUiIfAlive(() -> {
                    clearRecordingResumePosition(item.id);
                    showStatus(getString(R.string.status_recording_deleted));
                    refreshRecordingsPanel();
                });
            } catch (Exception e) {
                Log.w(TAG, "delete completed recording failed", e);
                postUiIfAlive(() -> showStatus(getString(R.string.status_failed_delete_recording)));
            }
        });
    }

    private void clearSelectedRecordingProgress(RecordingsRepository.RecordingItem item) {
        if (item == null) {
            return;
        }
        clearRecordingResumePosition(item.id);
        refreshRecordingsPanelSurface();
        showStatus(getString(R.string.status_recording_progress_cleared));
    }

    private void addRecordingFilterActions(List<String> options, List<Runnable> actions, RecordingsRepository.RecordingItem item) {
        String itemChannel = item == null ? "" : cleanText(item.channelName);
        if (!itemChannel.isEmpty() && !itemChannel.equalsIgnoreCase(recordingsChannelFilter)) {
            options.add(getString(R.string.recording_action_filter_channel, itemChannel));
            actions.add(() -> applyRecordingsChannelFilter(itemChannel));
        }
        String currentChannel = cleanText(getCurrentChannelName());
        if (!currentChannel.isEmpty() && !currentChannel.equalsIgnoreCase(itemChannel) && !currentChannel.equalsIgnoreCase(recordingsChannelFilter)) {
            options.add(getString(R.string.recording_action_filter_current_channel, currentChannel));
            actions.add(() -> applyRecordingsChannelFilter(currentChannel));
        }
        if (!recordingsChannelFilter.trim().isEmpty() || !RECORDINGS_DAY_ALL.equals(recordingsDayFilter)) {
            options.add(getString(R.string.recording_action_clear_filters));
            actions.add(this::clearRecordingsFilters);
        }
        options.add(getString(R.string.recording_action_filter_today));
        actions.add(() -> applyRecordingsDayFilter(RECORDINGS_DAY_TODAY));
        options.add(getString(R.string.recording_action_filter_tomorrow));
        actions.add(() -> applyRecordingsDayFilter(RECORDINGS_DAY_TOMORROW));
        options.add(getString(R.string.recording_action_filter_week));
        actions.add(() -> applyRecordingsDayFilter(RECORDINGS_DAY_WEEK));
        if (!RECORDINGS_DAY_ALL.equals(recordingsDayFilter)) {
            options.add(getString(R.string.recording_action_filter_all_days));
            actions.add(() -> applyRecordingsDayFilter(RECORDINGS_DAY_ALL));
        }
    }

    private void applyRecordingsChannelFilter(String channelName) {
        recordingsChannelFilter = cleanText(channelName);
        showStatus(getString(R.string.status_recordings_filter_channel, recordingsChannelFilter));
        refreshRecordingsPanel();
    }

    private void applyRecordingsDayFilter(String dayFilter) {
        recordingsDayFilter = dayFilter == null || dayFilter.trim().isEmpty() ? RECORDINGS_DAY_ALL : dayFilter;
        showStatus(getString(R.string.status_recordings_filter_day, recordingsDayFilterLabel(recordingsDayFilter)));
        refreshRecordingsPanel();
    }

    private void clearRecordingsFilters() {
        recordingsChannelFilter = "";
        recordingsDayFilter = RECORDINGS_DAY_ALL;
        showStatus(getString(R.string.status_recordings_filters_cleared));
        refreshRecordingsPanel();
    }

    private void toggleRecordingsAutoRefresh() {
        boolean enabled = recordingsPanelController.toggleAutoRefresh();
        showStatus(getString(enabled ? R.string.recordings_panel_auto_refresh_on : R.string.recordings_panel_auto_refresh_off));
    }

    private void checkReminderNotifications() {
        if (reminderStore == null) {
            return;
        }
        List<ReminderStore.ReminderItem> dueItems = reminderStore.collectDueNotifications(System.currentTimeMillis());
        if (!dueItems.isEmpty()) {
            ReminderStore.ReminderItem lastDueItem = dueItems.get(dueItems.size() - 1);
            showStatus(getString(R.string.status_reminder_due, lastDueItem.channelName, lastDueItem.title));
            scheduleUserPreferencePush();
        }
    }

    private static long parseIsoMillis(String iso) {
        return EpgTimeCodec.parseEpochMillis(iso);
    }

    private static String shortTime(String iso) {
        long ms = parseIsoMillis(iso);
        if (ms <= 0L) {
            return "--:--";
        }
        return EpgClockFormatter.format(ms);
    }

    private static String formatIsoMillis(long value) {
        return EpgTimeCodec.formatUtc(value);
    }

    private void tuneRelative(int delta) {
        if (channels.isEmpty()) {
            return;
        }
        int size = channels.size();
        int anchor = overlayNavigationState.currentIndex < 0 ? 0 : overlayNavigationState.currentIndex;
        int next = ((anchor + delta) % size + size) % size;
        tuneToIndex(next, true);
    }

    private void tuneSelectedChannel() {
        tuneToIndex(overlayNavigationState.selectedOverlayIndex, true);
        hideOverlay();
    }

    private void moveOverlaySelection(int delta) {
        syncOverlayCoordinator();
        channelOverlayCoordinator.moveOverlaySelection(delta);
        // Moving the cursor does not change the filter or tuned channel. Avoid
        // persisting unchanged preferences and rebuilding the entire overlay.
        overlayNavigationState.selectedOverlayIndex = channelOverlayCoordinator.getSelectedOverlayIndex();
        scrollOverlayChannelListToPosition(overlayNavigationState.selectedOverlayIndex);
        requestLiveChannelGuide();
        if (channelOverlay != null && channelOverlay.getVisibility() == View.VISIBLE) {
            channelOverlayCoordinator.showOverlay(channelOverlay, uiHandler, hideOverlayRunnable,
                    touchDeviceMode || liveChannelGuideVisible ? 0L : channelMenuHideMs());
        } else {
            showOverlay();
        }
    }

    private ChannelItem findChannelItemById(String channelID) {
        return allChannels.find(channelID);
    }

    private int findChannelIndexById(String channelID) {
        if (channelID == null || channelID.trim().isEmpty()) {
            return -1;
        }
        for (int i = 0; i < channels.size(); i++) {
            if (channelID.equals(channels.get(i).id)) {
                return i;
            }
        }
        return -1;
    }

    private int resolveStartupPlaybackIndex() {
        if (channels.isEmpty()) {
            return 0;
        }
        if (lastChannelId != null && !lastChannelId.trim().isEmpty()) {
            int found = findChannelIndexById(lastChannelId);
            if (found >= 0 && isLinearStartupChannel(channels.get(found))) {
                return found;
            }
        }
        for (int i = 0; i < channels.size(); i++) {
            if (isLinearStartupChannel(channels.get(i))) {
                return i;
            }
        }
        return 0;
    }

    private boolean isLinearStartupChannel(ChannelItem item) {
        return item != null
                && !item.isVod
                && !PrivateChannelPolicy.privateItem(item, currentOfflinePermissions)
                && item.playUrl != null
                && !item.playUrl.trim().isEmpty();
    }

    private void saveLastChannelId(String channelID) {
        if (PrivateChannelPolicy.privateItem(findChannelItemById(channelID), currentOfflinePermissions)) {
            rememberSafeLiveFallback();
            return;
        }
        lastChannelId = channelID;
        if (prefs != null && channelID != null) {
            prefs.edit().putString(PREF_LAST_CHANNEL_ID, channelID).apply();
        }
        scheduleUserPreferencePush();
    }

    private void persistVerifiedStartupChannel(String channelID) {
        if (catalogSnapshotStore == null || channelID == null || !channelID.equals(lastChannelId)) {
            return;
        }
        ChannelItem channel = findChannelItemById(channelID);
        if (!isLinearStartupChannel(channel) || isProtectedItem(channel)) {
            return;
        }
        catalogSnapshotStore.saveStartupPlaybackChannel(BuildConfig.CATALOG_SNAPSHOT_URL, channel);
    }

    private void purgePrivateRecents() {
        if (recentChannelsStore != null) recentChannelsStore.removeIf(item ->
                PrivateChannelPolicy.adultLabel(item.channelName)
                || PrivateChannelPolicy.privateItem(findChannelItemById(item.channelId), currentOfflinePermissions));
    }

    private void rememberSafeLiveFallback() {
        ChannelItem fallback = PrivateChannelPolicy.fallback(allChannels, currentOfflinePermissions);
        lastChannelId = fallback == null ? "" : fallback.id;
        if (prefs != null) prefs.edit().putString(PREF_LAST_CHANNEL_ID, lastChannelId)
                .putString(PREF_LAST_FILTER_KEY, fallback == null ? "all" : "platform:" + fallback.platformId).apply();
        purgePrivateRecents();
        scheduleUserPreferencePush();
    }

    private boolean privateHomeProvider(String key) {
        for (StartupHomeHubUiModel.Provider entry : discoveryHomeState.liveProviders)
            if (entry.key.equals(key) && PrivateChannelPolicy.adultLabel(entry.title)) return true;
        String filterKey = key != null && key.startsWith("live:") ? "platform:" + key.substring(5) : key;
        for (ChannelFilter filter : filters) if (filter.key.equals(filterKey))
            return PrivateChannelPolicy.privateFilter(filter, currentOfflinePermissions);
        return PrivateChannelPolicy.adultLabel(key);
    }

    private String safeHomeProvider() {
        for (StartupHomeHubUiModel.Provider entry : discoveryHomeState.liveProviders)
            if (PrivateChannelPolicy.movistarIsm(entry.title) && !privateHomeProvider(entry.key)) return entry.key;
        for (StartupHomeHubUiModel.Provider entry : discoveryHomeState.liveProviders)
            if (!privateHomeProvider(entry.key)) return entry.key;
        return "";
    }

    private void persistNavigationState() {
        if (prefs == null) {
            return;
        }
        for (ChannelFilter filter : filters) {
            if (filter.key.equals(overlayNavigationState.selectedFilterKey)
                    && PrivateChannelPolicy.privateFilter(filter, currentOfflinePermissions)) {
                rememberSafeLiveFallback();
                return;
            }
        }
        prefs.edit()
                .putString(PREF_LAST_FILTER_KEY, overlayNavigationState.selectedFilterKey == null || overlayNavigationState.selectedFilterKey.trim().isEmpty() ? "all" : overlayNavigationState.selectedFilterKey)
                .putBoolean(PREF_FAVORITES_ONLY, overlayNavigationState.favoritesOnly)
                .apply();
    }

    private void cycleFilter(int delta) {
        ChannelFilter targetFilter = findAdjacentFilter(delta);
        if (targetFilter != null && isProtectedFilter(targetFilter) && isProtectedContentLocked()) {
            ensureParentalAccessForFilterKey(targetFilter.key, () -> cycleFilter(delta));
            return;
        }
        syncOverlayCoordinator();
        ChannelFilter filter = channelOverlayCoordinator.cycleFilter(delta);
        syncOverlayStateFromCoordinator();
        persistNavigationState();
        refreshOverlayChannelList();
        updateFilterText();
        updateOverlaySearchState();

        if (channels.isEmpty()) {
            showStatus(getString(R.string.status_no_channels_for_filter));
            showOverlay();
            return;
        }

        if (overlayNavigationState.currentIndex < 0) {
            tuneToIndex(0, true);
        } else if (overlayNavigationState.selectedOverlayIndex >= 0) {
            scrollOverlayChannelListToPosition(overlayNavigationState.selectedOverlayIndex);
        }

        if (filter != null) {
            showStatus(getString(R.string.status_filter_changed, decorateProtectedFilterLabel(filter)));
        }
        scheduleVisibleEpgLoad(OFFLINE_EPG_PRIORITY_DELAY_MS);
        showOverlay();
    }

    private void showFilterPickerDialog() {
        if (filters.isEmpty()) {
            showStatus(getString(R.string.status_no_channels_for_filter));
            return;
        }
        List<ChannelFilter> selectableFilters = new ArrayList<>();
        List<String> labels = new ArrayList<>();
        int checkedIndex = -1;
        boolean hasUserVisibleFilters = hasUserVisibleOverlayFilters();
        for (ChannelFilter filter : filters) {
            if (filter == null || filter.key == null || filter.key.trim().isEmpty()) {
                continue;
            }
            if (hasUserVisibleFilters && !isUserVisibleOverlayFilter(filter)) {
                continue;
            }
            selectableFilters.add(filter);
            labels.add(decorateProtectedFilterLabel(filter));
            if (filter.key.equals(overlayNavigationState.selectedFilterKey)) {
                checkedIndex = selectableFilters.size() - 1;
            }
        }
        if (selectableFilters.isEmpty()) {
            showStatus(getString(R.string.status_no_channels_for_filter));
            return;
        }
        List<Runnable> actions = new ArrayList<>();
        for (int i = 0; i < selectableFilters.size(); i++) {
            final ChannelFilter selected = selectableFilters.get(i);
            if (i == checkedIndex) {
                labels.set(i, getString(R.string.settings_selected_prefix, labels.get(i)));
            }
            actions.add(() -> applySelectedFilterFromPicker(selected));
        }
        if (touchDeviceMode) {
            showTouchFilterPickerDialog(selectableFilters, checkedIndex);
            return;
        }
        List<java.util.function.Consumer<ImageView>> artwork = new ArrayList<>();
        for (ChannelFilter filter : selectableFilters) {
            String logo = filterContextLogoUrl(filter, getCurrentPlaybackChannelItem());
            String name = cleanFilterLabel(filter);
            artwork.add(logo == null || logo.trim().isEmpty() ? null
                    : view -> bindChannelLogo(view, logo, name, 34, 34));
        }
        showTvOptionsDialog(getString(R.string.filter_navigation_hint), null, labels, actions, null, artwork);
    }

    private void showTouchFilterPickerDialog(List<ChannelFilter> selectableFilters, int checkedIndex) {
        if (selectableFilters == null || selectableFilters.isEmpty()) {
            showStatus(getString(R.string.status_no_channels_for_filter));
            return;
        }
        prepareModalSurface();
        if (touchControlsBar != null) {
            touchControlsBar.setVisibility(View.GONE);
        }
        ComposeView composeView = new ComposeView(this);
        attachDialogViewTreeOwners(composeView);
        final Dialog[] dialogHolder = new Dialog[1];
        List<TouchFilterPickerRowUiModel> rows = new ArrayList<>();
        for (int i = 0; i < selectableFilters.size(); i++) {
            final ChannelFilter filter = selectableFilters.get(i);
            boolean selected = i == checkedIndex;
            String filterTitle = cleanFilterLabel(filter);
            rows.add(new TouchFilterPickerRowUiModel(
                    filterTitle,
                    getString(R.string.touch_filter_picker_count, countChannelsForFilter(filter)),
                    filterContextLogoUrl(filter, getCurrentPlaybackChannelItem()),
                    TouchControlsUiFactory.compactMark(filterTitle),
                    selected,
                    isProtectedFilter(filter),
                    () -> {
                        Dialog dialog = dialogHolder[0];
                        if (dialog != null) {
                            dismissModalForNextAction(dialog, () -> applySelectedFilterFromPicker(filter));
                        } else {
                            applySelectedFilterFromPicker(filter);
                        }
                    }
            ));
        }
        Runnable close = () -> {
            Dialog dialog = dialogHolder[0];
            if (dialog != null) {
                dialog.dismiss();
            }
        };
        TouchFilterPickerComposeBinder.bind(composeView, new TouchFilterPickerUiModel(
                getString(R.string.touch_filter_picker_title),
                getString(R.string.touch_filter_picker_subtitle),
                getString(R.string.touch_filter_picker_selected, buildCurrentFilterLabel()),
                checkedIndex,
                rows,
                close
        ), new TouchControlsArtworkBinder() {
            @Override
            public void bindLogo(ImageView imageView, String logoUrl, String channelName, int widthDp, int heightDp) {
                bindChannelLogo(imageView, logoUrl, channelName, widthDp, heightDp);
            }

            @Override
            public void bindPoster(ImageView imageView, String posterUrl) {
                bindProgramPoster(imageView, posterUrl);
            }
        });
        Dialog dialog = ComposeDialogHost.showFullscreen(this, composeView, this::handleModalDismissed);
        dialogHolder[0] = dialog;
        handleModalShown();
    }

    private String cleanFilterLabel(ChannelFilter filter) {
        String label = decorateProtectedFilterLabel(filter);
        if (label == null || label.trim().isEmpty()) {
            return getString(R.string.filter_all_label);
        }
        return label
                .replace("Plataforma activa: ", "")
                .replace("Plataforma: ", "")
                .replace("Grupo: ", "")
                .trim();
    }

    private int countChannelsForFilter(ChannelFilter filter) {
        if (filter == null) {
            return allChannels.size();
        }
        if ("favorites".equals(filter.key) || filter.type == FILTER_FAVORITES) {
            return buildFavoriteQuickChannels().size();
        }
        int count = 0;
        for (ChannelItem item : allChannels) {
            if (item == null) {
                continue;
            }
            if (filter.type == FILTER_ALL || "all".equals(filter.key)) {
                count++;
            } else if (filter.type == FILTER_PLATFORM && item.platformId == filter.platformId && !item.isVod) {
                count++;
            } else if (filter.type == FILTER_CUSTOM_GROUP && item.customGroups != null) {
                for (String group : item.customGroups) {
                    if (group != null && group.equalsIgnoreCase(filter.groupName)) {
                        count++;
                        break;
                    }
                }
            } else if (filter.type == FILTER_VOD && item.isVod && !item.isAdultVod) {
                count++;
            } else if (filter.type == FILTER_VOD_ADULT && item.isVod && item.isAdultVod) {
                count++;
            }
        }
        return count;
    }

    private void applySelectedFilterFromPicker(ChannelFilter filter) {
        if (filter == null || filter.key == null || filter.key.trim().isEmpty()) {
            return;
        }
        if (isProtectedFilter(filter) && isProtectedContentLocked()) {
            ensureParentalAccessForFilterKey(filter.key, () -> applySelectedFilterFromPicker(filter));
            return;
        }
        if (BuildConfig.STANDALONE_MODE
                && (filter.type == FILTER_VOD || filter.type == FILTER_VOD_ADULT)
                && !hasLoadedVodItems()) {
            prepareVodCatalogOnDemand(filter);
            return;
        }
        syncOverlayCoordinator();
        channelOverlayCoordinator.setSearchQuery("");
        channelOverlayCoordinator.setFavoritesOnly("favorites".equals(filter.key));
        channelOverlayCoordinator.setSelectedFilterKey(filter.key);
        String currentId = overlayNavigationState.currentIndex >= 0 && overlayNavigationState.currentIndex < channels.size()
                ? channels.get(overlayNavigationState.currentIndex).id
                : lastChannelId == null ? "" : lastChannelId;
        channelOverlayCoordinator.refreshVisibleChannels(currentId, currentId);
        syncOverlayStateFromCoordinator();
        persistNavigationState();
        clearOverlaySearchQuery();
        refreshOverlayChannelList();
        updateFilterText();
        updateOverlaySearchState();
        if (channels.isEmpty()) {
            showStatus(getString(R.string.status_no_channels_for_filter));
        } else if (overlayNavigationState.currentIndex < 0) {
            tuneToIndex(overlayNavigationState.selectedOverlayIndex >= 0 ? overlayNavigationState.selectedOverlayIndex : 0, true);
        } else if (overlayNavigationState.selectedOverlayIndex >= 0) {
            scrollOverlayChannelListToPosition(overlayNavigationState.selectedOverlayIndex);
        }
        showStatus(getString(R.string.status_filter_changed, decorateProtectedFilterLabel(filter)));
        scheduleVisibleEpgLoad(OFFLINE_EPG_PRIORITY_DELAY_MS);
        showOverlay();
    }

    private boolean hasLoadedVodItems() {
        for (ChannelItem item : allChannels) {
            if (item != null && item.isVod) {
                return true;
            }
        }
        return false;
    }

    private void prepareVodCatalogOnDemand(ChannelFilter requestedFilter) {
        if (catalogRepository == null || offlineCatalogRefreshRunning) {
            showStatus("Preparando el catalogo VOD…");
            return;
        }
        offlineCatalogRefreshRunning = true;
        if (playerController != null) {
            playerController.setPlayWhenReady(false);
        }
        showStatus("Preparando el catalogo VOD. La TV queda en pausa mientras termina.");
        long startMs = System.currentTimeMillis();
        catalogHydrationExecutor.execute(() -> {
            try {
                CatalogLoadResult result = catalogRepository.hydrateFullStartupCatalog();
                if (result == null) {
                    result = catalogRepository.refreshSnapshotFromConfiguredUrl(BuildConfig.CATALOG_SNAPSHOT_URL);
                }
                CatalogLoadResult finalResult = result;
                long durationMs = System.currentTimeMillis() - startMs;
                postUiIfAlive(() -> {
                    offlineCatalogRefreshRunning = false;
                    applyHydratedStartupCatalog(finalResult);
                    applySelectedFilterFromPicker(requestedFilter);
                    showStatus("Catalogo VOD preparado en " + durationMs + " ms");
                });
            } catch (Exception | OutOfMemoryError e) {
                Log.e(TAG, "on-demand VOD catalog preparation failed", e);
                postUiIfAlive(() -> {
                    offlineCatalogRefreshRunning = false;
                    if (playerController != null) {
                        playerController.setPlayWhenReady(true);
                    }
                    showError("No se pudo preparar VOD: " + fallbackUnknown(e.getMessage()));
                });
            }
        });
    }

    private ChannelFilter findAdjacentFilter(int delta) {
        if (filters.isEmpty()) {
            return null;
        }
        int currentFilterIndex = 0;
        for (int i = 0; i < filters.size(); i++) {
            ChannelFilter filter = filters.get(i);
            if (filter != null && filter.key != null && filter.key.equals(overlayNavigationState.selectedFilterKey)) {
                currentFilterIndex = i;
                break;
            }
        }
        boolean hasUserVisibleFilters = hasUserVisibleOverlayFilters();
        int next = currentFilterIndex;
        for (int attempts = 0; attempts < filters.size(); attempts++) {
            next += delta;
            if (next < 0) {
                next = filters.size() - 1;
            }
            if (next >= filters.size()) {
                next = 0;
            }
            ChannelFilter candidate = filters.get(next);
            if (!hasUserVisibleFilters || isUserVisibleOverlayFilter(candidate)) {
                return candidate;
            }
        }
        return filters.get(currentFilterIndex);
    }

    private boolean hasUserVisibleOverlayFilters() {
        for (ChannelFilter filter : filters) {
            if (isUserVisibleOverlayFilter(filter)) {
                return true;
            }
        }
        return false;
    }

    private boolean isUserVisibleOverlayFilter(ChannelFilter filter) {
        return filter != null
                && filter.key != null
                && !filter.key.trim().isEmpty()
                && !"all".equals(filter.key)
                && filter.type != FILTER_ALL;
    }

    private void updateFilterText() {
        updateQuickAccessButtons();
    }

    private void saveFavorites() {
        if (prefs != null) {
            prefs.edit().putStringSet(PREF_FAVORITES, new HashSet<>(favoriteChannelIds)).apply();
        }
        favoriteOrderStore.syncToFavorites(favoriteChannelIds);
        scheduleUserPreferencePush();
    }

    private void pullUserPreferences() {
        if (!BuildConfig.STANDALONE_MODE
                || userPreferenceSyncRepository == null
                || !userPreferenceSyncRepository.isConfigured()
                || userPreferencesLoading
                || activityDestroyed) {
            return;
        }
        userPreferencesLoading = true;
        submitControlTask("user-preferences-pull", () -> {
            try {
                JSONObject payload = userPreferenceSyncRepository.load(baseUrl);
                postUiIfAlive(() -> {
                    userPreferencesLoading = false;
                    lastUserPreferencePullMs = System.currentTimeMillis();
                    applyRemoteUserPreferences(payload);
                    userPreferencesReady = true;
                    JSONObject remoteInterface = payload.optJSONObject("interface_preferences");
                    JSONObject remoteOrders = remoteInterface == null ? null : remoteInterface.optJSONObject("live_orders");
                    boolean pendingOrder = false;
                    JSONObject localOrders = homeLiveOrders();
                    java.util.Iterator<String> orderKeys = localOrders.keys();
                    while (orderKeys.hasNext()) {
                        String key = orderKeys.next();
                        JSONObject local = localOrders.optJSONObject(key), remote = remoteOrders == null ? null : remoteOrders.optJSONObject(key);
                        if (local != null && (remote == null || local.optLong("updated_at") > remote.optLong("updated_at"))) pendingOrder = true;
                    }
                    if (!payload.optBoolean("exists", false) || pendingOrder) scheduleUserPreferencePush();
                });
            } catch (Exception e) {
                Log.w(TAG, "user preference pull failed; keeping local state", e);
                postUiIfAlive(() -> {
                    userPreferencesLoading = false;
                    userPreferencesReady = true;
                });
            }
        });
    }

    private void applyRemoteUserPreferences(JSONObject payload) {
        if (payload == null || !payload.optBoolean("exists", false)) {
            remoteUserPreferences = payload == null ? new JSONObject() : payload;
            return;
        }
        remoteUserPreferences = payload;
        JSONObject remoteInterface = payload.optJSONObject("interface_preferences");
        mergeHomeLiveOrders(remoteInterface == null ? null : remoteInterface.optJSONObject("live_orders"));
        favoriteChannelIds.clear();
        favoriteChannelIds.addAll(jsonStringList(payload.optJSONArray("favorites"), 500));
        if (prefs != null) {
            prefs.edit().putStringSet(PREF_FAVORITES, new HashSet<>(favoriteChannelIds)).apply();
        }
        if (favoriteOrderStore != null) {
            favoriteOrderStore.syncToFavorites(favoriteChannelIds);
        }

        String remoteLastChannel = payload.optString("last_channel_id", "").trim();
        boolean localLastChannelAvailable = findChannelItemById(lastChannelId) != null;
        if (!remoteLastChannel.isEmpty()
                && findChannelItemById(remoteLastChannel) != null
                && !PrivateChannelPolicy.privateItem(findChannelItemById(remoteLastChannel), currentOfflinePermissions)
                && StartupChannelPolicy.shouldApplyRemoteLastChannel(lastChannelId, localLastChannelAvailable)) {
            lastChannelId = remoteLastChannel;
            if (prefs != null) {
                prefs.edit().putString(PREF_LAST_CHANNEL_ID, remoteLastChannel).apply();
            }
        }

        if (recentChannelsStore != null) {
            Map<String, String> namesById = new HashMap<>();
            for (ChannelItem item : allChannels) {
                if (item != null && item.id != null) {
                    namesById.put(item.id, displayName(item));
                }
            }
            recentChannelsStore.mergeIds(jsonStringList(payload.optJSONArray("recents"), 50), namesById);
            purgePrivateRecents();
        }

        hboHistory().merge(payload);
        saveHboHistory();
        JSONObject progress = payload.optJSONObject("vod_progress");
        if (progress != null) {
            Map<String, Long> localPositions = new HashMap<>(vodResumePositions);
            Map<String, Long> localUpdatedAt = new HashMap<>(vodResumeUpdatedAt);
            long remotePayloadUpdatedAt = parseIsoMillis(payload.optString("updated_at", ""));
            vodResumePositions.clear();
            vodResumeUpdatedAt.clear();
            java.util.Iterator<String> keys = progress.keys();
            while (keys.hasNext()) {
                String id = keys.next();
                if(id.startsWith("hbomax:"))continue;
                JSONObject entry = progress.optJSONObject(id);
                if (entry == null) {
                    continue;
                }
                long positionMs = Math.max(0L, Math.round(entry.optDouble("position", 0d) * 1000d));
                long durationMs = Math.max(0L, Math.round(entry.optDouble("duration", 0d) * 1000d));
                long updatedAtMs = Math.max(0L, entry.optLong("updated_at", remotePayloadUpdatedAt));
                if (id.startsWith("recording-") && id.length() > "recording-".length()) {
                    String recordingId = id.substring("recording-".length());
                    long localTime = recordingResumeUpdatedAt.getOrDefault(recordingId, 0L);
                    if (positionMs > 0L && durationMs > 60_000L && positionMs < durationMs * 0.98d && updatedAtMs >= localTime) {
                        recordingResumePositions.put(recordingId, positionMs);
                        recordingResumeDurations.put(recordingId, durationMs);
                        recordingResumeUpdatedAt.put(recordingId, updatedAtMs);
                    }
                    continue;
                }
                if (positionMs > 0L && durationMs > 60_000L && positionMs < durationMs * 0.98d) {
                    vodResumePositions.put(id, positionMs);
                    vodResumeDurations.put(id, durationMs);
                    vodResumeUpdatedAt.put(id, updatedAtMs);
                }
            }
            boolean preservedLocal = false;
            for (Map.Entry<String, Long> local : localPositions.entrySet()) {
                long localTime = Math.max(0L, localUpdatedAt.getOrDefault(local.getKey(), 0L));
                if (!vodResumePositions.containsKey(local.getKey())
                        && local.getValue() != null
                        && local.getValue() > 0L
                        && shouldPreserveLocalVodProgress(localTime, remotePayloadUpdatedAt,
                            progress.has(local.getKey()), vodResumeDuration(local.getKey()))) {
                    vodResumePositions.put(local.getKey(), local.getValue());
                    vodResumeUpdatedAt.put(local.getKey(), localTime);
                    preservedLocal = true;
                }
            }
            saveVodResumePositions(false);
            saveRecordingResumePositions();
            invalidateVodDerivedCaches();
            if (preservedLocal) {
                postUiDelayedIfAlive(this::scheduleUserPreferencePush, 100L);
            }
        }

        if (reminderStore != null && reminderStore.mergeRemote(payload.optJSONObject("epg_reminders"))) {
            ReminderScheduler.reschedulePending(this, reminderStore);
        }

        JSONObject presets = payload.optJSONObject("multiview_presets");
        if (presets != null && prefs != null) {
            java.util.Iterator<String> names = presets.keys();
            int index = 0;
            SharedPreferences.Editor editor = prefs.edit();
            while (names.hasNext() && index < MULTIVIEW_PRESET_COUNT) {
                List<String> ids = jsonStringList(presets.optJSONArray(names.next()), 4);
                if (ids.size() >= 2) {
                    editor.putString(getMultiViewPresetKey(index++), String.join("|", ids));
                }
            }
            editor.apply();
        }
        refreshOverlayChannelList();
        updateOverlaySearchState();
        refreshTouchControlsBar();
    }

    private void scheduleUserPreferencePush() {
        if (!userPreferencesReady || activityDestroyed) {
            return;
        }
        uiHandler.removeCallbacks(userPreferencePushRunnable);
        postUiDelayedIfAlive(userPreferencePushRunnable, USER_PREFERENCE_SYNC_DEBOUNCE_MS);
    }

    private void pushUserPreferences() {
        if (!userPreferencesReady
                || userPreferenceSyncRepository == null
                || !userPreferenceSyncRepository.isConfigured()
                || activityDestroyed) {
            return;
        }
        JSONObject payload = buildUserPreferencePayload();
        submitControlTask("user-preferences-push", () -> {
            try {
                JSONObject stored = userPreferenceSyncRepository.save(baseUrl, payload);
                postUiIfAlive(() -> remoteUserPreferences = stored == null ? new JSONObject() : stored);
            } catch (Exception e) {
                Log.w(TAG, "user preference push failed", e);
            }
        });
    }

    private String homeOrderPreferenceKey() {
        return "home_live_orders_" + Uri.encode(catalogSnapshotStore.getUserScope());
    }
    private JSONObject homeLiveOrders() {
        try { return new JSONObject(prefs.getString(homeOrderPreferenceKey(), "{}")); }
        catch (Exception ignored) { return new JSONObject(); }
    }
    private List<String> homeLiveOrder(String key) {
        String scope = homeOrderPreferenceKey();
        return jsonStringList(homeLiveOrderSnapshot.ids(scope, prefs.getString(scope, "{}"), key), 10000);
    }
    private void saveHomeLiveOrder(String key, List<String> ids) {
        JSONObject orders = homeLiveOrders();
        try { orders.put(key, new JSONObject().put("ids", new JSONArray(ids)).put("updated_at", System.currentTimeMillis())); }
        catch (Exception ignored) { return; }
        prefs.edit().putString(homeOrderPreferenceKey(), orders.toString()).apply();
        scheduleUserPreferencePush();
    }
    private void mergeHomeLiveOrders(JSONObject incoming) {
        if (incoming == null) return;
        JSONObject local = homeLiveOrders();
        java.util.Iterator<String> keys = incoming.keys();
        while (keys.hasNext()) {
            String key = keys.next();
            JSONObject remote = incoming.optJSONObject(key), old = local.optJSONObject(key);
            if (remote != null && (old == null || remote.optLong("updated_at") > old.optLong("updated_at"))) {
                try { local.put(key, remote); } catch (Exception ignored) { }
            }
        }
        prefs.edit().putString(homeOrderPreferenceKey(), local.toString()).apply();
    }

    private JSONObject buildUserPreferencePayload() {
        purgePrivateRecents();
        JSONObject payload = new JSONObject();
        try {
            payload.put("favorites", new JSONArray(favoriteChannelIds));
            List<String> recents = new ArrayList<>();
            if (recentChannelsStore != null) {
                for (RecentChannelsStore.RecentChannelItem item : recentChannelsStore.getItems()) {
                    if (item != null && item.channelId != null && !item.channelId.trim().isEmpty()) {
                        recents.add(item.channelId.trim());
                    }
                }
            }
            payload.put("recents", new JSONArray(recents));
            payload.put("last_channel_id", lastChannelId == null ? "" : lastChannelId);

            JSONObject progress = new JSONObject();
            for (Map.Entry<String, Long> saved : vodResumePositions.entrySet()) {
                ChannelItem item = findChannelItemById(saved.getKey());
                if (item == null) {
                    item = vodResumeItems.get(saved.getKey());
                }
                long durationMs = vodResumeDuration(saved.getKey());
                long positionMs = saved.getValue() == null ? 0L : Math.max(0L, saved.getValue());
                if (durationMs <= 60_000L || positionMs <= 0L || positionMs >= durationMs * 0.98d) {
                    continue;
                }
                progress.put(saved.getKey(), new JSONObject()
                        .put("position", positionMs / 1000d)
                        .put("duration", durationMs / 1000d)
                        .put("updated_at", Math.max(0L, vodResumeUpdatedAt.getOrDefault(saved.getKey(), System.currentTimeMillis()))));
            }
            for (Map.Entry<String, Long> saved : recordingResumePositions.entrySet()) {
                String recordingId = saved.getKey();
                long positionMs = saved.getValue() == null ? 0L : Math.max(0L, saved.getValue());
                long durationMs = Math.max(0L, recordingResumeDurations.getOrDefault(recordingId, 0L));
                if (recordingId == null || recordingId.trim().isEmpty() || durationMs <= 60_000L || positionMs <= 0L || positionMs >= durationMs * 0.98d) {
                    continue;
                }
                progress.put("recording-" + recordingId, new JSONObject()
                        .put("position", positionMs / 1000d)
                        .put("duration", durationMs / 1000d)
                        .put("updated_at", Math.max(0L, recordingResumeUpdatedAt.getOrDefault(recordingId, System.currentTimeMillis()))));
            }
            payload.put("vod_progress", progress);
            payload.put("epg_reminders", reminderStore == null ? new JSONObject() : reminderStore.toRemoteJson());
            payload.put("watchlist", remoteUserPreferences.optJSONArray("watchlist") == null
                    ? new JSONArray()
                    : new JSONArray(remoteUserPreferences.optJSONArray("watchlist").toString()));
            payload.put("watched", remoteUserPreferences.optJSONArray("watched") == null
                    ? new JSONArray()
                    : new JSONArray(remoteUserPreferences.optJSONArray("watched").toString()));
            payload.put("series_continuity", remoteUserPreferences.optJSONObject("series_continuity") == null
                    ? new JSONObject()
                    : new JSONObject(remoteUserPreferences.optJSONObject("series_continuity").toString()));
            hboHistory().exportInto(payload);
            if (remoteUserPreferences.optJSONObject("interface_preferences") != null) {
                payload.put("interface_preferences", new JSONObject(remoteUserPreferences.optJSONObject("interface_preferences").toString()));
            }

            JSONObject interfacePayload = payload.optJSONObject("interface_preferences");
            if (interfacePayload == null) interfacePayload = new JSONObject();
            interfacePayload.put("live_orders", homeLiveOrders());
            payload.put("interface_preferences", interfacePayload);
            JSONObject presets = new JSONObject();
            for (int index = 0; index < MULTIVIEW_PRESET_COUNT; index++) {
                List<String> ids = getMultiViewPresetIds(index);
                if (ids.size() >= 2) {
                    presets.put("Offline " + (index + 1), new JSONArray(ids));
                }
            }
            payload.put("multiview_presets", presets);
        } catch (Exception e) {
            Log.w(TAG, "failed to build user preference payload", e);
        }
        return payload;
    }

    private static List<String> jsonStringList(JSONArray values, int limit) {
        List<String> out = new ArrayList<>();
        if (values == null || limit <= 0) {
            return out;
        }
        Set<String> seen = new HashSet<>();
        for (int index = 0; index < values.length() && out.size() < limit; index++) {
            String value = values.optString(index, "").trim();
            if (!value.isEmpty() && seen.add(value)) {
                out.add(value);
            }
        }
        return out;
    }

    private void toggleFavoriteSelected() {
        if (channels.isEmpty() || overlayNavigationState.selectedOverlayIndex < 0 || overlayNavigationState.selectedOverlayIndex >= channels.size()) {
            return;
        }
        syncOverlayCoordinator();
        boolean added = channelOverlayCoordinator.toggleFavoriteSelected();
        syncOverlayStateFromCoordinator();
        showStatus(getString(added ? R.string.status_favorite_added : R.string.status_favorite_removed));
        String selectedId = overlayNavigationState.selectedOverlayIndex >= 0 && overlayNavigationState.selectedOverlayIndex < channels.size() ? channels.get(overlayNavigationState.selectedOverlayIndex).id : null;
        if (added) {
            favoriteOrderStore.addIfMissing(selectedId);
        } else {
            favoriteOrderStore.remove(selectedId);
        }
        saveFavorites();
        refreshOverlayChannelList();
        updateOverlaySearchState();
        if (overlayNavigationState.selectedOverlayIndex >= 0) {
            scrollOverlayChannelListToPosition(overlayNavigationState.selectedOverlayIndex);
        }
        showOverlay();
    }

    private void toggleFavoriteForChannel(ChannelItem channelItem) {
        if (channelItem == null || channelItem.id == null || channelItem.id.trim().isEmpty()) {
            showStatus(getString(R.string.diagnostics_none));
            return;
        }
        int index = findChannelIndexById(channelItem.id);
        if (index >= 0) {
            overlayNavigationState.selectedOverlayIndex = index;
            toggleFavoriteSelected();
            return;
        }
        boolean added;
        if (favoriteChannelIds.contains(channelItem.id)) {
            favoriteChannelIds.remove(channelItem.id);
            channelItem.favorite = false;
            favoriteOrderStore.remove(channelItem.id);
            added = false;
        } else {
            favoriteChannelIds.add(channelItem.id);
            channelItem.favorite = true;
            favoriteOrderStore.addIfMissing(channelItem.id);
            added = true;
        }
        for (ChannelItem item : allChannels) {
            if (item != null && channelItem.id.equals(item.id)) {
                item.favorite = channelItem.favorite;
            }
        }
        saveFavorites();
        refreshOverlayChannelList();
        updateOverlaySearchState();
        showStatus(getString(added ? R.string.status_favorite_added : R.string.status_favorite_removed));
    }

    private void toggleFavoriteChannel(ChannelItem channel) {
        if (channel == null || channel.id == null || channel.id.trim().isEmpty()) {
            return;
        }
        boolean added;
        if (favoriteChannelIds.contains(channel.id)) {
            favoriteChannelIds.remove(channel.id);
            favoriteOrderStore.remove(channel.id);
            added = false;
        } else {
            favoriteChannelIds.add(channel.id);
            favoriteOrderStore.addIfMissing(channel.id);
            added = true;
        }
        saveFavorites();
        refreshOverlayChannelList();
        updateOverlaySearchState();
        showStatus(getString(added ? R.string.status_favorite_added : R.string.status_favorite_removed));
    }

    private void moveFavoriteSelected(int delta) {
        if (channels.isEmpty() || overlayNavigationState.selectedOverlayIndex < 0 || overlayNavigationState.selectedOverlayIndex >= channels.size()) {
            return;
        }
        ChannelItem selected = channels.get(overlayNavigationState.selectedOverlayIndex);
        if (!selected.favorite) {
            showStatus(getString(R.string.status_favorite_move_unavailable));
            return;
        }
        boolean moved = favoriteOrderStore.move(selected.id, delta);
        if (!moved) {
            showStatus(getString(R.string.status_favorite_move_unavailable));
            return;
        }
        syncOverlayCoordinator();
        String currentId = overlayNavigationState.currentIndex >= 0 && overlayNavigationState.currentIndex < channels.size() ? channels.get(overlayNavigationState.currentIndex).id : "";
        channelOverlayCoordinator.refreshVisibleChannels(currentId, selected.id);
        syncOverlayStateFromCoordinator();
        refreshOverlayChannelList();
        if (overlayNavigationState.selectedOverlayIndex >= 0) {
            scrollOverlayChannelListToPosition(overlayNavigationState.selectedOverlayIndex);
        }
        showStatus(getString(delta < 0 ? R.string.status_favorite_moved_up : R.string.status_favorite_moved_down));
        showOverlay();
    }

    private void toggleFavoritesOnlyMode() {
        syncOverlayCoordinator();
        boolean nowFavoritesOnly = channelOverlayCoordinator.toggleFavoritesOnlyMode();
        syncOverlayStateFromCoordinator();
        refreshOverlayChannelList();
        updateOverlaySearchState();

        if (channels.isEmpty() && nowFavoritesOnly) {
            showStatus(getString(R.string.status_favorites_only_empty));
            return;
        }

        if (overlayNavigationState.selectedOverlayIndex >= 0) {
            scrollOverlayChannelListToPosition(overlayNavigationState.selectedOverlayIndex);
        }
        showStatus(getString(nowFavoritesOnly ? R.string.status_favorites_only_on : R.string.status_favorites_only_off));
        showOverlay();
    }

