    @Override
    public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (hasFocus) {
            enableImmersiveMode();
            // A window regain must not steal focus from a list or a Compose control.
            if (ComposeDialogHost.topWindow(this) == null) WindowFocusRecovery.recover(getWindow(), activeFocusFallback());
        }
    }

    private View activeFocusFallback() {
        View[] surfaces = {quickSearchOverlay, recordingsPanel, channelListComposeView,
                touchControlsComposeView, timeshiftComposeView, multiViewHeaderComposeView};
        for (View surface : surfaces) if (surface != null && surface.isShown()) return surface;
        return playerView;
    }

    private void enableImmersiveMode() {
        View decor = getWindow().getDecorView();
        decor.setSystemUiVisibility(
                View.SYSTEM_UI_FLAG_LAYOUT_STABLE
                        | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
                        | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
                        | View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
                        | View.SYSTEM_UI_FLAG_FULLSCREEN
                        | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
        );
    }

    private boolean submitIoTask(String label, Runnable task) {
        return submitExecutorTask(ioExecutor, label, task);
    }

    private boolean submitEpgTask(String label, Runnable task) {
        return submitExecutorTask(epgExecutor, label, task);
    }

    private boolean submitCatalogTask(String label, Runnable task) {
        return submitExecutorTask(catalogLoadExecutor, label, task);
    }

    private boolean submitControlTask(String label, Runnable task) {
        return submitExecutorTask(controlExecutor, label, task);
    }

    private boolean postUiIfAlive(Runnable task) {
        if (task == null || activityDestroyed) {
            return false;
        }
        return uiHandler.post(() -> {
            if (!activityDestroyed) {
                task.run();
            }
        });
    }

    private boolean postUiDelayedIfAlive(Runnable task, long delayMs) {
        if (task == null || activityDestroyed) {
            return false;
        }
        // Keep the original Runnable identity so removeCallbacks(task) continues to work.
        // onDestroy() clears the handler queue and prevents any later scheduling.
        return uiHandler.postDelayed(task, delayMs);
    }

    private boolean submitExecutorTask(ExecutorService executor, String label, Runnable task) {
        if (executor == null || task == null) {
            return false;
        }
        if (executor.isShutdown() || executor.isTerminated()) {
            Log.w(TAG, "executor task skipped after shutdown label=" + label);
            return false;
        }
        try {
            executor.execute(() -> {
                if (!activityDestroyed && !Thread.currentThread().isInterrupted()) {
                    task.run();
                }
            });
            return true;
        } catch (RejectedExecutionException e) {
            Log.w(TAG, "executor task rejected label=" + label, e);
            return false;
        }
    }

    @Override
    protected void onDestroy() {
        cancelRemoteZap();
        timelineLoadGeneration++; timelineDownloads.shutdownNow(); timelineCacheExecutor.shutdownNow();
        archiveGeneration++; movistarGuideExecutor.shutdownNow(); archiveExecutor.shutdownNow(); archiveStorageExecutor.shutdownNow(); archivePresentationExecutor.shutdownNow();archiveGenreExecutor.shutdownNow();archiveFanartExecutor.shutdownNow();if(archiveAvailability!=null)archiveAvailability.close();if(movistarArtwork!=null)movistarArtwork.close();if(movistarGuide!=null)movistarGuide.close();
        uiHandler.removeCallbacks(playlistImportTick);
        playlistStatusExecutor.shutdownNow();
        PlaylistImportIndicator.update("");
        closeLiveChannelGuide();
        closeU7dPrompt();
        if (deviceWebPanel != null) deviceWebPanel.close();
        uiHandler.removeCallbacks(devicePanelStatusTick);
        if (personalPlaylistController != null) personalPlaylistController.close();
        if (privateVodBrowser != null) privateVodBrowser.close();
        activityDestroyed = true;
        panelGuideRefreshGate.clear();
        sleepTimer.cancel();
        uiHandler.removeCallbacks(sleepTimerTick);
        closeSleepTimerWarning();
        if (playbackOutputMonitor != null) playbackOutputMonitor.close();
        dismissAppUpdatePanel();
        if (startupSummaryRequests != null) startupSummaryRequests.close();
        rememberCurrentVodPosition();
        rememberCurrentRecordingPosition();
        stopPlaybackHeartbeat("stop");
        if (remoteCommandEventClient != null) {
            remoteCommandEventClient.stop();
        }
        if (networkConnectivityMonitor != null) {
            networkConnectivityMonitor.stop();
            networkConnectivityMonitor = null;
        }
        if (touchControlsController != null) {
            touchControlsController.cancelTimers();
        }
        if (playbackOutputMonitor != null) playbackOutputMonitor.close();
        uiHandler.removeCallbacksAndMessages(null);
        globalSearch.close();
        ioExecutor.shutdownNow();
        channelLogoExecutor.shutdownNow();
        epgExecutor.shutdownNow();
        interactiveExecutor.shutdownNow();
        controlExecutor.shutdownNow();
        appUpdateExecutor.shutdownNow();
        catalogLoadExecutor.shutdownNow();
        catalogHydrationExecutor.shutdownNow();
        if (playerController != null) {
            playerController.release();
            playerController = null;
        }
        super.onDestroy();
    }

    @Override
    public void onTrimMemory(int level) {
        super.onTrimMemory(level);
        BlackBox.event(BlackBoxStore.Event.MEMORY_PRESSURE,0,level,0,0);
        Log.println(Log.INFO, TAG, "memoryTrim level=" + level + " multiview=" + isMultiViewVisible()
                + " closeForPressure=" + MultiviewMemoryPolicy.shouldClose(level));
        Glide.get(this).trimMemory(level);
        if (level >= android.content.ComponentCallbacks2.TRIM_MEMORY_RUNNING_LOW) {
            if(movistarArtwork!=null)movistarArtwork.clearMemory();
            channelLogoCache.evictAll();
            streamInfoByChannelId.clear();
        }
        if (MultiviewMemoryPolicy.shouldClose(level) && isMultiViewVisible()) {
            closeMultiView();
            showStatus(getString(R.string.status_multiview_closed_low_memory));
        }
    }

    @Override
    public void onLowMemory() {
        super.onLowMemory();
        Log.w(TAG, "memoryLow multiview=" + isMultiViewVisible());
        if(movistarArtwork!=null)movistarArtwork.clearMemory();
        channelLogoCache.evictAll();
        streamInfoByChannelId.clear();
        Glide.get(this).clearMemory();
        if (isMultiViewVisible()) {
            closeMultiView();
        }
    }
    private PlayerController.PlaybackRequest toPlaybackRequest(ChannelItem channelItem) {
        if (channelItem == null) {
            return null;
        }
        String playbackUrl = PublicBackendUrlPolicy.rebaseLegacyUrl(channelItem.playUrl, baseUrl);
        SkyNativePlayback.Route skyNative = channelItem.isVod ? SkyNativePlayback.resolve(playbackUrl, baseUrl) : null;
        if (skyNative != null && SkyNativeCapabilities.supportsUhd(this))
            skyNative = SkyNativePlayback.resolve(playbackUrl, baseUrl, true);
        return new PlayerController.PlaybackRequest(
                channelItem.id,
                displayName(channelItem),
                channelItem.platformName,
                skyNative == null ? playbackUrl : skyNative.manifest,
                skyNative == null ? PublicBackendUrlPolicy.rebaseLegacyUrl(channelItem.fallbackPlayUrl, baseUrl) : "",
                resolvePlaybackModeForRequest(channelItem),
                skyNative == null ? channelItem.drmScheme : "widevine",
                skyNative == null ? PublicBackendUrlPolicy.rebaseLegacyUrl(channelItem.drmLicenseUrl, baseUrl) : skyNative.license,
                skyNative != null || channelItem.directPlayback,
                channelItem.isVod,
                skyNative == null ? channelItem.playbackProfile : ""
        ).withPlaylistHeaders(channelItem.playlistStreamHeaders, channelItem.playlistLicenseHeaders, channelItem.playlistMimeType);
    }

    private String resolvePlaybackModeForRequest(ChannelItem channelItem) {
        expireLearnedPlaybackModes();
        return PlaybackModeResolver.resolve(channelItem, playbackModeStore, temporaryPlaybackModesByChannelId, learnedPlaybackModesByChannelId, new PlaybackModeResolver.Host() {
            @Override
            public boolean standaloneMode() {
                return BuildConfig.STANDALONE_MODE;
            }

            @Override
            public boolean playbackRepairEnabled() {
                return MainActivity.this.playbackRepairEnabled;
            }

            @Override
            public boolean proxyManifestProfile(ChannelItem item) {
                return isProxyManifestProfile(item);
            }

            @Override
            public void saveLearnedModes() {
                saveLearnedPlaybackModes();
            }
        });
    }

    private boolean isProxyManifestProfile(ChannelItem channelItem) {
        return channelItem != null && "proxy_manifest".equals(safeLower(channelItem.playbackProfile));
    }

    private ChannelItem getCurrentPlaybackChannelItem() {
        if (!currentPlaybackRequestedChannelId.isEmpty()) {
            ChannelItem requested = findChannelItemById(currentPlaybackRequestedChannelId);
            if (requested != null) {
                return requested;
            }
        }
        if (currentPlaybackTransientItem != null) {
            return currentPlaybackTransientItem;
        }
        String playbackChannelId = playerController == null ? "" : playerController.getCurrentRequestChannelId();
        if (!playbackChannelId.isEmpty()) {
            ChannelItem playbackChannel = findChannelItemById(playbackChannelId);
            if (playbackChannel != null) {
                return playbackChannel;
            }
        }
        if (overlayNavigationState.currentIndex >= 0 && overlayNavigationState.currentIndex < channels.size()) {
            return channels.get(overlayNavigationState.currentIndex);
        }
        return findChannelItemById(lastChannelId);
    }

    private void retryCurrentPlayback() {
        ChannelItem channelItem = getCurrentPlaybackChannelItem();
        if (channelItem == null) {
            showStatus(getString(R.string.diagnostics_none));
            return;
        }
        showStatus(getString(R.string.status_retry_channel, displayName(channelItem)));
        overlayNavigationState.currentIndex = findChannelIndexById(channelItem.id);
        if (overlayNavigationState.currentIndex >= 0) {
            overlayNavigationState.selectedOverlayIndex = overlayNavigationState.currentIndex;
            refreshOverlayChannelList();
            tuneToIndex(overlayNavigationState.currentIndex, true);
            return;
        }
        playChannelItem(channelItem, true);
    }

