    private void openMultiView() {
        showTvOptionsDialog(R.string.multiview_layout_title, null,
                Arrays.asList(getString(R.string.multiview_layout_mosaic), getString(R.string.multiview_layout_pip)),
                Arrays.asList(() -> { multiViewPipMode = false; openMultiView(buildMultiViewChannels()); },
                        () -> {
                            multiViewPipMode = true;
                            List<ChannelItem> items = buildMultiViewChannels();
                            openMultiView(new ArrayList<>(items.subList(0, Math.min(2, items.size()))));
                        }));
    }

    private void openMultiView(List<ChannelItem> selected) {
        if (selected == null || selected.size() < 2) {
            showStatus(getString(R.string.status_multiview_not_enough_channels));
            return;
        }
        int supportedStreams = devicePerformanceProfile == null ? 2 : devicePerformanceProfile.maxMultiViewStreams;
        boolean limitedByDevice = false;
        if (selected.size() > supportedStreams) {
            selected = new ArrayList<>(selected.subList(0, supportedStreams));
            limitedByDevice = true;
        }
        hideOverlay();
        hideRecordingsPanel();
        clearQuickSearchOverlay();
        if (touchControlsBar != null) {
            touchControlsBar.setVisibility(View.GONE);
        }
        if (touchHomeHub != null) {
            touchHomeHub.setVisibility(View.GONE);
        }
        if (timeshiftBarContainer != null) {
            timeshiftBarContainer.setVisibility(View.GONE);
        }
        mainWasPlayingBeforeMultiView = playerController != null && playerController.isPlaying();
        // These are rebuildable artwork caches, not the persisted user catalog.
        // Release them before allocating a second video decoder.
        stopStartupLivePreview();
        channelLogoCache.evictAll();
        Glide.get(this).clearMemory();
        if (playerController != null) {
            playerController.setMuted(true);
            playerController.setPlayWhenReady(false);
            playerController.suspendForMultiView();
        }
        initializeMultiViewLayout();
        multiViewPrimaryIndex = 0;
        if (selected.size() != 2) multiViewPipMode = false;
        ensureMultiViewControllers();
        multiCompositionPendingStart = shouldStartSharedMultiComposition();
        multiViewChannels.clear();
        multiViewChannels.addAll(selected);
        for (int i = 0; i < multiViewChannelIds.length; i++) {
            multiViewChannelIds[i] = i < selected.size() ? selected.get(i).id : null;
        }
        multiViewActiveIndex = 0;
        multiViewFocusedIndex = 0;
        multiViewExpandedIndex = -1;
        multiViewPrimaryIndex = 0;
        multiViewControlsOpen = false;
        if (selected.size() != 2) multiViewPipMode = false;
        for (int i = 0; i < multiTiles.length; i++) {
            if (multiTiles[i] == null) {
                continue;
            }
            if (i < selected.size()) {
                ChannelItem item = selected.get(i);
                multiTiles[i].setVisibility(View.VISIBLE);
                if (!multiCompositionPendingStart) playInitialMultiViewChannel(i,item);
            } else {
                multiTiles[i].setVisibility(View.INVISIBLE);
            }
        }
        refreshMultiViewHeader();
        updateMultiViewFocus();
        if (multiViewContainer != null) {
            multiViewContainer.setVisibility(View.VISIBLE);
        }
        overlaySurfaceState.setVisible(OfflineOverlayState.Surface.MULTIVIEW, true);
        startSharedMultiComposition();
        multiViewContainer.post(this::applyMultiViewLayout);
        revealMultiViewHud();
        Log.println(Log.INFO, TAG, "multiview opened");
        showStatus(limitedByDevice
                ? getString(R.string.status_multiview_device_limit, supportedStreams)
                : getString(R.string.multiview_title));
    }

    private void playInitialMultiViewChannel(int i,ChannelItem item) {
                PlayerController controller = multiPlayerControllers.get(i);
                controller.setMuted(i != multiViewActiveIndex);
                PlayerController.PlaybackRequest request = toPlaybackRequest(item);
                PlayerController.StreamInfo cachedStreamInfo = streamInfoByChannelId.get(item.id);
                if (shouldResolveStreamInfoBeforePlayback(item, request)) {
                    controller.playChannelAfterResolvingStreamInfo(request, true, streamInfoByChannelId, 0L);
                } else {
                    controller.playChannel(request, true, cachedStreamInfo);
                }
                if (request != null && !shouldResolveStreamInfoBeforePlayback(item, request) && !request.directPlayback) {
                    controller.resolveStreamInfoAndReplayIfNeeded(request, true, streamInfoByChannelId);
                }
    }

    private void closeMultiView() {
        multiViewExpandedIndex = -1;
        uiHandler.removeCallbacks(hideMultiViewHud);
        multiViewControlsOpen = false;
        if (multiViewContainer != null && multiViewContainer.getVisibility() != View.VISIBLE) {
            return;
        }
        Log.println(Log.INFO, TAG, "multiview closed");
        if (multiViewContainer != null) {
            multiViewContainer.setVisibility(View.GONE);
        }
        overlaySurfaceState.setVisible(OfflineOverlayState.Surface.MULTIVIEW, false);
        releaseMultiViewControllers();
        multiViewChannels.clear();
        for (int i = 0; i < multiViewChannelIds.length; i++) {
            multiViewChannelIds[i] = null;
        }
        if (playerController != null) {
            playerController.resumeAfterMultiView();
            playerController.setMuted(false);
            playerController.setPlayWhenReady(mainWasPlayingBeforeMultiView);
        }
        mainWasPlayingBeforeMultiView = false;
        updateTouchHomeHub();
    }

    private SharedMultiViewCompositor multiCompositor;
    private boolean multiCompositionDisabledForSession;
    private boolean multiCompositionPendingStart;
    private boolean shouldStartSharedMultiComposition() {
        return "beta".equalsIgnoreCase(BuildConfig.UPDATE_CHANNEL) && !multiCompositionDisabledForSession
                && prefs.getBoolean("multiview_shared_composition",true) && multiCompositor==null;
    }
    private void completeMultiCompositionStart() {
        if(!multiCompositionPendingStart || !isMultiViewVisible())return;
        multiCompositionPendingStart=false;
        for(int i=0;i<multiViewChannels.size();i++)playInitialMultiViewChannel(i,multiViewChannels.get(i));
    }
    private boolean usesSharedMultiComposition() { return multiCompositor != null; }

    private void startSharedMultiComposition() {
        Log.i("SharedMultiGL","start disabled="+multiCompositionDisabledForSession+" preference="+prefs.getBoolean("multiview_shared_composition",true)+" existing="+(multiCompositor!=null));
        if (!shouldStartSharedMultiComposition() || !isMultiViewVisible() || multiPlayerControllers.isEmpty()) return;
        final SharedMultiViewCompositor[] holder = new SharedMultiViewCompositor[1];
        holder[0] = new SharedMultiViewCompositor(this, multiPlayerControllers.size(), surfaces -> {
            if (multiCompositor != holder[0] || !isMultiViewVisible()) return;
            for (int i=0;i<surfaces.length && i<multiPlayerControllers.size();i++) {
                final int slot=i;
                multiPlayerControllers.get(i).setMultiCompositionSurface(surfaces[i], (ratio,fps) -> holder[0].configureSlot(slot,ratio.floatValue(),fps));
            }
            updateMultiViewFocus(); applyMultiViewLayout();
            completeMultiCompositionStart();
        }, () -> {
            if (multiCompositor == holder[0]) {
                multiCompositionDisabledForSession=true;
                stopSharedMultiComposition();
                updateMultiViewFocus(); applyMultiViewLayout();
                completeMultiCompositionStart();
                Log.w("SharedMultiGL","fallback to independent surfaces");
            }
        });
        multiCompositor=holder[0];
        ((FrameLayout)multiViewContainer).addView(multiCompositor,0,new FrameLayout.LayoutParams(-1,-1));
        uiHandler.postDelayed(() -> {
            if(multiCompositor==holder[0] && multiCompositionPendingStart) {
                multiCompositionDisabledForSession=true;stopSharedMultiComposition();
                updateMultiViewFocus();applyMultiViewLayout();completeMultiCompositionStart();
                Log.w("SharedMultiGL","initialization timeout; using classic output");
            }
        },8000L);
    }

    private void stopSharedMultiComposition() {
        SharedMultiViewCompositor previous=multiCompositor;
        if(previous==null)return;
        multiCompositor=null;
        for(PlayerController pc:multiPlayerControllers)pc.setMultiCompositionSurface(null,null);
        ((FrameLayout)multiViewContainer).removeView(previous);
        previous.close();
    }

    private void ensureMultiViewControllers() {
        if (!multiPlayerControllers.isEmpty()) {
            return;
        }
        int supportedStreams = devicePerformanceProfile == null ? 2 : devicePerformanceProfile.maxMultiViewStreams;
        int[] playerStubIds = {R.id.multiPlayerStub1, R.id.multiPlayerStub2, R.id.multiPlayerStub3, R.id.multiPlayerStub4};
        for (int i = 0; i < Math.min(multiPlayerViews.length, supportedStreams); i++) {
            final int slot = i;
            PlayerView mv = multiPlayerViews[i];
            if (mv == null) {
                android.view.ViewStub stub = findViewById(playerStubIds[i]);
                if (stub != null) {
                    mv = (PlayerView) stub.inflate();
                    multiPlayerViews[i] = mv;
                    Log.d(TAG, "multiview player view created on demand slot=" + i);
                }
            }
            if (mv == null) {
                continue;
            }
            PlayerController controller = new PlayerController(this, mv, baseUrl, ioExecutor, uiHandler, new PlayerController.Host() {
                @Override
                public void showStatus(String text) {
                }

                @Override
                public void showError(String text) {
                }

                @Override
                public void hideError() {
                }

                @Override
                public boolean isChannelCurrent(String channelId) {
                    return channelId != null && channelId.equals(multiViewChannelIds[slot]);
                }

                @Override
                public void showHdrBadge(String label) {
                }

                @Override
                public boolean isPlaybackRepairEnabled() {
                    return MainActivity.this.playbackRepairEnabled;
                }

                @Override
                public boolean isMultiViewPlayback() {
                    return true;
                }

                @Override
                public int multiViewQualityRole() {
                    return MultiViewQualityPolicy.role(multiViewPipMode, slot, multiViewPrimaryIndex);
                }

                @Override
                public void recordPlaybackError(PlayerController.PlaybackRequest request, PlayerController.PlaybackDiagnostics diagnostics) {
                    MainActivity.this.recordPlaybackError(request, diagnostics);
                }

                @Override
                public void onPlaybackReady(PlayerController.PlaybackRequest request, PlayerController.PlaybackDiagnostics diagnostics, boolean recoveredFromRebuffer) {
                }

                @Override
                public void onFirstVideoFrameRendered(String channelId) {
                }
            });
            controller.initialize();
            multiPlayerControllers.add(controller);
        }
    }

    private void releaseMultiViewControllers() {
        multiCompositionPendingStart=false;
        for (PlayerController controller : multiPlayerControllers) {
            if (controller != null) {
                controller.release();
            }
        }
        multiPlayerControllers.clear();
        stopSharedMultiComposition();
    }

    private List<ChannelItem> buildMultiViewChannels() {
        List<ChannelItem> selected = new ArrayList<>();
        Set<String> added = new HashSet<>();
        int maxStreams = devicePerformanceProfile == null ? 2 : devicePerformanceProfile.maxMultiViewStreams;
        if (overlayNavigationState.currentIndex >= 0 && overlayNavigationState.currentIndex < channels.size()) {
            ChannelItem current = channels.get(overlayNavigationState.currentIndex);
            if (current != null && !current.isVod && current.id != null && added.add(current.id)) {
                selected.add(current);
            }
        }
        for (ChannelItem item : channels) {
            if (selected.size() >= maxStreams) {
                break;
            }
            if (item == null || item.isVod || item.id == null || !added.add(item.id)) {
                continue;
            }
            selected.add(item);
        }
        if (selected.size() < maxStreams) {
            for (ChannelItem item : allChannels) {
                if (selected.size() >= maxStreams) {
                    break;
                }
                if (item == null || item.isVod || item.id == null || !added.add(item.id)) {
                    continue;
                }
                selected.add(item);
            }
        }
        return selected;
    }

    private List<ChannelItem> buildCurrentMultiViewSelectionForSave() {
        List<ChannelItem> selected = new ArrayList<>();
        Set<String> added = new HashSet<>();
        if (isMultiViewVisible()) {
            for (ChannelItem item : multiViewChannels) {
                if (item != null && item.id != null && added.add(item.id)) {
                    selected.add(item);
                }
            }
        }
        if (selected.size() >= 2) {
            return selected;
        }
        return buildMultiViewChannels();
    }

    private String getMultiViewPresetKey(int presetIndex) {
        return PREF_MULTIVIEW_PRESET_PREFIX + presetIndex;
    }

    private List<String> getMultiViewPresetIds(int presetIndex) {
        List<String> ids = new ArrayList<>();
        if (prefs == null) {
            return ids;
        }
        String raw = prefs.getString(getMultiViewPresetKey(presetIndex), "");
        if (raw == null || raw.trim().isEmpty()) {
            return ids;
        }
        for (String part : raw.split("\\|")) {
            if (part == null) {
                continue;
            }
            String id = part.trim();
            if (!id.isEmpty()) {
                ids.add(id);
            }
        }
        return ids;
    }

    private List<ChannelItem> resolveMultiViewPreset(int presetIndex) {
        List<ChannelItem> result = new ArrayList<>();
        Set<String> added = new HashSet<>();
        for (String id : getMultiViewPresetIds(presetIndex)) {
            ChannelItem item = findChannelItemById(id);
            if (item != null && !item.isVod && item.id != null && added.add(item.id)) {
                result.add(item);
            }
        }
        return result;
    }

    private void saveMultiViewPreset(int presetIndex, List<ChannelItem> items) {
        if (prefs == null) {
            return;
        }
        List<String> ids = new ArrayList<>();
        Set<String> added = new HashSet<>();
        for (ChannelItem item : items) {
            if (item != null && item.id != null && !item.id.trim().isEmpty() && added.add(item.id)) {
                ids.add(item.id);
            }
        }
        prefs.edit().putString(getMultiViewPresetKey(presetIndex), String.join("|", ids)).apply();
        scheduleUserPreferencePush();
    }

    private String buildMultiViewPresetLabel(int presetIndex) {
        int count = resolveMultiViewPreset(presetIndex).size();
        return getString(R.string.multiview_preset_label, presetIndex + 1, count);
    }

    private void showSaveMultiViewPresetDialog() {
        List<ChannelItem> source = buildCurrentMultiViewSelectionForSave();
        if (source.size() < 2) {
            showStatus(getString(R.string.status_multiview_not_enough_channels));
            return;
        }
        String[] labels = new String[MULTIVIEW_PRESET_COUNT];
        for (int i = 0; i < MULTIVIEW_PRESET_COUNT; i++) {
            labels[i] = buildMultiViewPresetLabel(i);
        }
        List<String> options = Arrays.asList(labels);
        List<Runnable> actions = new ArrayList<>();
        for (int i = 0; i < labels.length; i++) {
            final int which = i;
            actions.add(() -> {
                    saveMultiViewPreset(which, source);
                    showStatus(getString(R.string.status_multiview_preset_saved, which + 1));
            });
        }
        showTvOptionsDialog(R.string.multiview_save_preset_title, null, options, actions);
    }

    private void showOpenMultiViewPresetDialog() {
        String[] labels = new String[MULTIVIEW_PRESET_COUNT];
        for (int i = 0; i < MULTIVIEW_PRESET_COUNT; i++) {
            labels[i] = buildMultiViewPresetLabel(i);
        }
        List<String> options = Arrays.asList(labels);
        List<Runnable> actions = new ArrayList<>();
        for (int i = 0; i < labels.length; i++) {
            final int which = i;
            actions.add(() -> {
                    List<ChannelItem> preset = resolveMultiViewPreset(which);
                    if (preset.size() < 2) {
                        showStatus(getString(R.string.status_multiview_preset_empty));
                        return;
                    }
                    openMultiView(preset);
            });
        }
        showTvOptionsDialog(R.string.multiview_open_preset_title, null, options, actions);
    }

    private void showAddMultiViewScreenPicker() {
        if (isMultiViewVisible()) {
            showMultiViewControls();
            return;
        }
        final ChannelItem current = getCurrentPlaybackChannelItem();
        if (current == null || current.isVod || "u7d_proxy".equalsIgnoreCase(current.playbackProfile)) return;
        if (devicePerformanceProfile != null && devicePerformanceProfile.maxMultiViewStreams < 2) return;
        List<ChannelItem> items = MultiViewChannelSelector.selectable(allChannels, Arrays.asList(current), 1);
        showMultiViewPlatformPicker(-1, items, item -> {
            if (item == null) return;
            multiViewPipMode = false;
            openMultiView(Arrays.asList(current, item));
        });
    }

    private void showMultiViewChannelPicker(int slot) {
        if (slot < 0 || slot >= multiViewChannels.size()) {
            return;
        }
        List<ChannelItem> items = buildSelectableMultiViewChannels(slot);
        if (items.isEmpty()) {
            showStatus(getString(R.string.status_multiview_not_enough_channels));
            return;
        }
        showMultiViewPlatformPicker(slot, items);
    }

    private void showMultiViewPlatformPicker(int slot, List<ChannelItem> items) {
        showMultiViewPlatformPicker(slot, items, item -> tuneMultiViewSlotChannel(slot, item));
    }

    private void showMultiViewPlatformPicker(int slot, List<ChannelItem> items, QuickChannelSelectionAction onSelected) {
        List<MultiViewChannelSelector.PlatformGroup> platformGroups = MultiViewChannelSelector.groupByPlatform(items);
        if (platformGroups.isEmpty()) {
            showStatus(getString(R.string.status_multiview_not_enough_channels));
            return;
        }
        List<ChannelItem> platformRows = new ArrayList<>();
        Map<String, MultiViewChannelSelector.PlatformGroup> platformByRowId = new LinkedHashMap<>();
        int order = 1;
        for (MultiViewChannelSelector.PlatformGroup group : platformGroups) {
            String rowId = "multiview-platform-" + group.key;
            String platformName = group.name.trim().isEmpty()
                    ? getString(R.string.multiview_platform_unknown)
                    : group.name.trim();
            int channelCount = group.channels.size();
            ChannelItem row = new ChannelItem(
                    rowId,
                    platformName,
                    "",
                    group.logoUrl,
                    getResources().getQuantityString(R.plurals.multiview_platform_channels_available, channelCount, channelCount),
                    "",
                    "",
                    order,
                    order,
                    false,
                    false,
                    group.platformId,
                    "",
                    new ArrayList<>(),
                    "",
                    "",
                    "",
                    false
            );
            row.platformLogoUrl = group.logoUrl;
            platformRows.add(row);
            platformByRowId.put(rowId, group);
            order++;
        }
        showRememberedMultiViewPicker(
                "platform:"+slot,
                getString(R.string.multiview_select_platform_title),
                getString(R.string.multiview_select_platform_subtitle, platformGroups.size(), items.size()),
                platformRows,
                getString(R.string.overlay_no_results),
                row -> {
                    MultiViewChannelSelector.PlatformGroup group = row == null ? null : platformByRowId.get(row.id);
                    if (group != null) {
                        showMultiViewPlatformChannels(slot, items, group, onSelected);
                    }
                },
                null,
                null
        );
    }

    private void showMultiViewPlatformChannels(
            int slot,
            List<ChannelItem> allSelectable,
            MultiViewChannelSelector.PlatformGroup group,
            QuickChannelSelectionAction onSelected
    ) {
        String platformName = group.name.trim().isEmpty()
                ? getString(R.string.multiview_platform_unknown)
                : group.name.trim();
        int channelCount = group.channels.size();
        showRememberedMultiViewPicker(
                "channels:"+slot+":"+group.key,
                getString(R.string.multiview_select_platform_channels_title, platformName),
                getResources().getQuantityString(R.plurals.multiview_platform_channels_available, channelCount, channelCount),
                group.channels,
                getString(R.string.overlay_no_results),
                onSelected,
                () -> showMultiViewPlatformPicker(slot, allSelectable, onSelected),
                null
        );
    }

    private List<ChannelItem> buildSelectableMultiViewChannels(int slot) {
        return MultiViewChannelSelector.selectable(allChannels, multiViewChannels, slot);
    }

    private void tuneMultiViewSlotChannel(int slot, ChannelItem item) {
        if (slot < 0 || slot >= multiPlayerControllers.size() || item == null || item.id == null) {
            return;
        }
        while (multiViewChannels.size() <= slot) {
            multiViewChannels.add(null);
        }
        multiViewChannels.set(slot, item);
        multiViewChannelIds[slot] = item.id;
        PlayerController controller = multiPlayerControllers.get(slot);
        controller.setMuted(slot != multiViewActiveIndex);
        PlayerController.PlaybackRequest request = toPlaybackRequest(item);
        PlayerController.StreamInfo cachedStreamInfo = streamInfoByChannelId.get(item.id);
        if (shouldResolveStreamInfoBeforePlayback(item, request)) {
            controller.playChannelAfterResolvingStreamInfo(request, true, streamInfoByChannelId, 0L);
        } else {
            controller.playChannel(request, true, cachedStreamInfo);
        }
        if (request != null && !shouldResolveStreamInfoBeforePlayback(item, request) && !request.directPlayback) {
            controller.resolveStreamInfoAndReplayIfNeeded(request, true, streamInfoByChannelId);
        }
        updateMultiViewFocus();
    }

    private void focusMultiViewSlot(int slot) {
        if (slot < 0 || slot >= multiViewChannels.size()) {
            return;
        }
        multiViewFocusedIndex = slot;
        if (touchDeviceMode && slot == multiViewActiveIndex) { showMultiViewControls(); return; }
        if (slot == multiViewActiveIndex) {
            multiViewExpandedIndex = multiViewExpandedIndex == slot ? -1 : slot;
            applyMultiViewLayout(); updateMultiViewFocus(); return;
        }
        multiViewActiveIndex = slot;
        for (int i = 0; i < multiPlayerControllers.size(); i++) {
            multiPlayerControllers.get(i).setMuted(i != multiViewActiveIndex);
        }
        updateMultiViewFocus();
    }

    private void moveMultiViewSelection(int columnDelta, int rowDelta) {
        if (!isMultiViewVisible() || multiViewChannels.isEmpty()) {
            return;
        }
        int currentSlot = Math.max(0, Math.min(multiViewFocusedIndex, multiViewChannels.size() - 1));
        int currentColumn = currentSlot % 2;
        int currentRow = currentSlot / 2;
        int nextColumn = Math.max(0, Math.min(1, currentColumn + columnDelta));
        int nextRow = Math.max(0, Math.min(1, currentRow + rowDelta));
        int nextSlot = (nextRow * 2) + nextColumn;
        if (nextSlot >= multiViewChannels.size() || nextSlot == currentSlot) {
            return;
        }
        multiViewFocusedIndex = nextSlot;
        if (multiViewExpandedIndex >= 0) { multiViewExpandedIndex=-1; applyMultiViewLayout(); }
        updateMultiViewFocus();
    }

    private void openMultiViewSlotFullscreen(int slot) {
        if (slot < 0 || slot >= multiViewChannels.size()) {
            return;
        }
        multiViewFocusedIndex = slot;
        multiViewActiveIndex = slot;
        for(int i=0;i<multiPlayerControllers.size();i++)multiPlayerControllers.get(i).setMuted(i!=slot);
        multiViewExpandedIndex = slot;
        applyMultiViewLayout();updateMultiViewFocus();
    }

    private void refreshMultiViewHeader() {
        int capacity = devicePerformanceProfile == null ? 2 : devicePerformanceProfile.maxMultiViewStreams;
        MultiViewHeaderComposeBinder.bind(
                multiViewHeaderComposeView,
                new MultiViewHeaderUiModel(
                        getString(R.string.multiview_title_capacity, multiViewChannels.size(), capacity),
                        touchDeviceMode ? getString(R.string.multiview_hint_touch) : getString(R.string.multiview_hint_tv),
                        getString(R.string.multiview_close),
                        this::closeMultiView
                )
        );
    }

    private void refreshMultiViewOverlays() {
        for (int i = 0; i < multiOverlayViews.length; i++) {
            boolean hasChannel = i < multiViewChannels.size() && multiViewChannels.get(i) != null;
            ChannelItem item = hasChannel ? multiViewChannels.get(i) : null;
            MultiViewTileOverlayComposeBinder.bind(
                    multiOverlayViews[i],
                    new MultiViewTileOverlayUiModel(
                            item == null ? "" : item.name,
                            getString(R.string.multiview_slot_label, i + 1),
                            getString(R.string.multiview_active_audio),
                            touchDeviceMode ? getString(R.string.multiview_tile_hint_touch) : getString(R.string.multiview_tile_hint_tv),
                            hasChannel,
                            i == multiViewActiveIndex && hasChannel,
                            false,
                            ""
                    )
            );
        }
    }

    private void updateMultiViewFocus() {
        for (int i = 0; i < multiTiles.length; i++) {
            if (multiTiles[i] == null) {
                continue;
            }
            boolean hasChannel = i < multiViewChannels.size();
            boolean active = i == multiViewFocusedIndex && hasChannel;
            GradientDrawable tileBackground = new GradientDrawable();
            tileBackground.setColor(usesSharedMultiComposition() ? Color.TRANSPARENT : Color.parseColor("#FF1A1730"));
            tileBackground.setStroke(active ? dpToPx(4) : dpToPx(2), active ? Color.parseColor("#FFA889FF") : Color.parseColor("#663A2857"));
            multiTiles[i].setBackground(tileBackground);
            multiTiles[i].setAlpha(hasChannel ? 1f : 0.7f);
        }
        refreshMultiViewOverlays();
        revealMultiViewHud();
    }

    private void initializeMultiViewLayout() {
        if (multiViewLayoutInitialized) return;
        FrameLayout container = (FrameLayout) multiViewContainer;
        // Do this before inflating/attaching players. Later swaps resize in place.
        for (View tile : multiTiles) ((ViewGroup) tile.getParent()).removeView(tile);
        ((ViewGroup) multiViewHeaderComposeView.getParent()).removeView(multiViewHeaderComposeView);
        container.removeAllViews();
        for (View tile : multiTiles) container.addView(tile, new FrameLayout.LayoutParams(1, 1));
        FrameLayout.LayoutParams headerParams = new FrameLayout.LayoutParams(-1, -2);
        headerParams.gravity = android.view.Gravity.BOTTOM;
        container.addView(multiViewHeaderComposeView, headerParams);
        container.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob) -> {
            if (r-l != or-ol || b-t != ob-ot) applyMultiViewLayout();
        });
        multiViewLayoutInitialized = true;
    }

    private void applyMultiViewLayout() {
        if (!multiViewLayoutInitialized || multiViewChannels.isEmpty()) return;
        int w = multiViewContainer.getWidth(), h = multiViewContainer.getHeight();
        if (w <= 0 || h <= 0) return;
        int[][] compositionBounds = new int[multiViewChannels.size()][];
        for (int i=0;i<multiViewChannels.size();i++) {
            int[] b = MultiViewLayoutPolicy.bounds(w,h,multiViewChannels.size(),i,
                    multiViewPipMode,multiViewPrimaryIndex,multiViewPipCorner,dp(16));
            if (multiViewExpandedIndex >= 0) b = MultiViewLayoutPolicy.expandedBounds(w,h,i,multiViewExpandedIndex);
            compositionBounds[i]=b;
            FrameLayout.LayoutParams p = new FrameLayout.LayoutParams(b[2],b[3]);
            p.leftMargin=b[0]; p.topMargin=b[1];
            multiTiles[i].setLayoutParams(p);
            multiTiles[i].setElevation(multiViewPipMode && i != multiViewPrimaryIndex ? dp(8) : 0);
        }
        if (multiCompositor != null) multiCompositor.layout(compositionBounds,multiViewPipMode && multiViewExpandedIndex < 0,multiViewPrimaryIndex);
        multiViewHeaderComposeView.setElevation(dp(12));
        // Lower the old primary first; no prepare/seek or surface reattachment.
        for (int i=0; i<multiPlayerControllers.size(); i++)
            if (i != multiViewPrimaryIndex) multiPlayerControllers.get(i).refreshMultiViewVideoQuality();
        if (multiViewPrimaryIndex < multiPlayerControllers.size())
            multiPlayerControllers.get(multiViewPrimaryIndex).refreshMultiViewVideoQuality();
    }

    private void revealMultiViewHud() {
        if (multiViewHeaderComposeView == null) return;
        multiViewHeaderComposeView.setVisibility(View.VISIBLE);
        for (ComposeView overlay : multiOverlayViews) if (overlay != null) overlay.setVisibility(View.VISIBLE);
        uiHandler.removeCallbacks(hideMultiViewHud);
        if (isMultiViewVisible() && !multiViewControlsOpen) uiHandler.postDelayed(hideMultiViewHud, 3000L);
    }

    private Runnable multiViewAction(Runnable action) {
        return () -> { multiViewControlsOpen = false; action.run(); revealMultiViewHud(); };
    }

    private void showMultiViewControls() {
        multiViewControlsOpen = true;
        revealMultiViewHud();
        List<String> labels = new ArrayList<>();
        List<Runnable> actions = new ArrayList<>();
        if (multiViewChannels.size() == 2) {
            labels.add(getString(multiViewPipMode ? R.string.multiview_layout_mosaic : R.string.multiview_layout_pip));
            actions.add(multiViewAction(() -> { multiViewPipMode = !multiViewPipMode; applyMultiViewLayout(); }));
            if (multiViewPipMode) {
                labels.add(getString(R.string.multiview_swap));
                actions.add(multiViewAction(() -> {
                    multiViewPrimaryIndex = 1 - multiViewPrimaryIndex;
                    multiViewActiveIndex = multiViewPrimaryIndex;
                    for (int i=0;i<multiPlayerControllers.size();i++) multiPlayerControllers.get(i).setMuted(i != multiViewActiveIndex);
                    applyMultiViewLayout(); updateMultiViewFocus();
                    Log.println(Log.INFO,TAG,"multiview swap primary=" + multiViewPrimaryIndex);
                }));
                labels.add(getString(R.string.multiview_move_thumbnail));
                actions.add(multiViewAction(() -> { multiViewPipCorner = (multiViewPipCorner+1)%4; applyMultiViewLayout(); }));
            }
            labels.add(getString(R.string.multiview_switch_audio));
            actions.add(multiViewAction(() -> {
                multiViewActiveIndex = 1-multiViewActiveIndex;
                for (int i=0;i<multiPlayerControllers.size();i++) multiPlayerControllers.get(i).setMuted(i != multiViewActiveIndex);
                updateMultiViewFocus();
            }));
        }
        labels.add(getString(R.string.multiview_change_channel));
        actions.add(multiViewAction(() -> showMultiViewChannelPicker(multiViewFocusedIndex)));
        labels.add(getString(R.string.multiview_fullscreen));
        actions.add(multiViewAction(() -> openMultiViewSlotFullscreen(multiViewFocusedIndex)));
        if ("beta".equalsIgnoreCase(BuildConfig.UPDATE_CHANNEL)) {
            labels.add(usesSharedMultiComposition() ? "Composición: compartida · cambiar a clásica" : "Composición: clásica · probar compartida");
            actions.add(multiViewAction(() -> {
                boolean enable=!usesSharedMultiComposition();
                prefs.edit().putBoolean("multiview_shared_composition",enable).apply();
                if(enable){multiCompositionDisabledForSession=false;startSharedMultiComposition();}
                else stopSharedMultiComposition();
                updateMultiViewFocus();applyMultiViewLayout();
            }));
        }
        labels.add(getString(R.string.multiview_close));
        actions.add(multiViewAction(this::closeMultiView));
        showTvOptionsDialog(R.string.multiview_controls, null, labels, actions,
                () -> { multiViewControlsOpen = false; revealMultiViewHud(); });
    }

    private int dpToPx(int dp) {
        return Math.round(dp * getResources().getDisplayMetrics().density);
    }

    private CharSequence buildHighlightedText(String value, String query, boolean favorite) {
        String base = value == null ? "" : value;
        String prefix = favorite ? "★ " : "";
        SpannableStringBuilder builder = new SpannableStringBuilder(prefix + base);
        if (query == null || query.trim().isEmpty() || base.isEmpty()) {
            return builder;
        }
        String lowerBase = base.toLowerCase(Locale.ROOT);
        String lowerQuery = query.trim().toLowerCase(Locale.ROOT);
        int start = 0;
        while (start < lowerBase.length()) {
            int index = lowerBase.indexOf(lowerQuery, start);
            if (index < 0) {
                break;
            }
            int spanStart = prefix.length() + index;
            int spanEnd = spanStart + lowerQuery.length();
            builder.setSpan(new ForegroundColorSpan(0xFF9BD0FF), spanStart, spanEnd, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
            builder.setSpan(new StyleSpan(Typeface.BOLD), spanStart, spanEnd, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
            start = index + lowerQuery.length();
        }
        return builder;
    }

    private void syncOverlayCoordinator() {
        channelOverlayCoordinator.syncState(overlayNavigationState.currentIndex, overlayNavigationState.selectedOverlayIndex, overlayNavigationState.favoritesOnly, overlayNavigationState.selectedFilterKey);
    }

    private void syncOverlayStateFromCoordinator() {
        overlayNavigationState.currentIndex = channelOverlayCoordinator.getCurrentIndex();
        overlayNavigationState.selectedOverlayIndex = channelOverlayCoordinator.getSelectedOverlayIndex();
        overlayNavigationState.favoritesOnly = channelOverlayCoordinator.isFavoritesOnly();
        overlayNavigationState.selectedFilterKey = channelOverlayCoordinator.getSelectedFilterKey();
        persistNavigationState();
    }

