        if (activityDestroyed) {
            return;
        }
        uiHandler.removeCallbacks(playbackQualityUiRefreshRunnable);
        postUiDelayedIfAlive(playbackQualityUiRefreshRunnable, PLAYBACK_QUALITY_UI_COALESCE_MS);
