    /** Refresh only the requested web day; native filters and saved metadata stay intact. */
    private boolean queuePanelCatchupDay(JSONObject request,List<ChannelItem> permitted) throws Exception {
        if(request.optBoolean("saved"))return panelGuideRefreshGate.busy();
        String day=request.optString("day",java.time.LocalDate.now().toString());
        if(day.isEmpty())day=java.time.LocalDate.now().toString();
        java.time.LocalDate selected;
        try {selected=java.time.LocalDate.parse(day);}
        catch(Exception invalid){throw new DeviceWebPanel.PanelError("Día no válido.");}
        java.time.LocalDate today=java.time.LocalDate.now();
        if(selected.isAfter(today)||selected.isBefore(today.minusDays(7)))throw new DeviceWebPanel.PanelError("Día fuera de la ventana disponible.");
        String requestedChannel=request.optString("channel");
        List<ChannelItem> snapshot=new ArrayList<>();
        boolean allowed=requestedChannel.isEmpty();
        for(ChannelItem channel:permitted) {
            if(!requestedChannel.isEmpty()&&!requestedChannel.equals(channel.id))continue;
            allowed=true;if(!isOrangeChannel(channel))snapshot.add(channel);
        }
        if(!allowed)throw new DeviceWebPanel.PanelError("Canal no disponible.");
        if(snapshot.isEmpty())return panelGuideRefreshGate.busy();
        final String scope=archiveScope, requestedDay=day;
        final int generation=archiveGeneration;
        final String key=scope+"|"+generation+"|"+day+"|"+requestedChannel;
        PanelGuideRefreshGate.Ticket ticket=panelGuideRefreshGate.begin(key,android.os.SystemClock.elapsedRealtime());
        if(ticket!=null)try {
            movistarGuideExecutor.execute(()->{
                boolean success=false;
                try {
                    if(activityDestroyed||!panelGuideRefreshGate.current(ticket))return;
                    MovistarGuideRepository.Guide guide=directMovistarGuide().day(requestedDay,snapshot,partial->{
                        if(!panelGuideRefreshGate.current(ticket))return;
                        java.util.Map<String,List<EpgRepository.EpgProgram>> changed=new java.util.LinkedHashMap<>();
                        for(ChannelItem channel:snapshot) {
                            JSONObject identity=partial.identity(channel);if(identity==null)continue;
                            try{changed.put(channel.id,partial.programmes(channel,identity));}catch(Exception invalid){}
                        }
                        if(!changed.isEmpty())try{archiveStore.indexAll(scope,changed);}
                        catch(Exception failure){throw new IllegalStateException("Panel guide index unavailable",failure);}
                        if(!changed.isEmpty())postUiIfAlive(()->{
                            if(generation==archiveGeneration&&archiveDialog!=null)archiveState.setRevision(archiveState.getRevision()+1);
                        });
                    });
                    success=guide.complete;
                }catch(Exception failure){Log.w(TAG,"Panel guide refresh unavailable: "+failure.getClass().getSimpleName());}
                finally{panelGuideRefreshGate.complete(ticket,android.os.SystemClock.elapsedRealtime(),success);}
            });
        } catch(RuntimeException stopped) {
            panelGuideRefreshGate.complete(ticket,android.os.SystemClock.elapsedRealtime(),false);
            throw stopped;
        }
        return panelGuideRefreshGate.busy();
    }

    private byte[] devicePanelArtwork(String id)throws Exception {
        java.util.concurrent.FutureTask<String> scopeTask=new java.util.concurrent.FutureTask<>(()->{ensureArchiveScope();return archiveScope;});
        uiHandler.post(scopeTask);final String scope=scopeTask.get(5,java.util.concurrent.TimeUnit.SECONDS);
        final EpgRepository.EpgProgram stored=archiveStore.find(scope,id);
        java.util.concurrent.FutureTask<JSONObject> lookup=new java.util.concurrent.FutureTask<>(()->{
            if(movistarArtwork==null)movistarArtwork=new MovistarArtworkRepository(getCacheDir());
            for(U7dCatalogEntry e:archiveState.getEntries())if(e.id.equals(id)){
                ChannelItem c=findAllowedHomeLiveChannel(e.channelId);String provider=c==null||isOrangeChannel(c)||archiveAvailability==null?"":archiveAvailability.provider(archiveScope,c);
                return new JSONObject().put("fallback",e.artworkKey).put("provider",provider).put("start",e.start).put("title",e.title);
            }
            if(stored!=null && scope.equals(archiveScope)) {
                ChannelItem c=findAllowedHomeLiveChannel(stored.channelId);
                if(c!=null && supportsU7d(c))return new JSONObject().put("fallback",ProgramArtworkResolver.resolve(stored,c))
                    .put("provider",isOrangeChannel(c)||archiveAvailability==null?"":archiveAvailability.provider(scope,c))
                    .put("start",EpgTimeCodec.parseEpochMillis(stored.startTime)).put("title",stored.title);
            }
            return new JSONObject();
        });uiHandler.post(lookup);JSONObject metadata=lookup.get(5,java.util.concurrent.TimeUnit.SECONDS);
        String fallback=metadata.optString("fallback"),url=MovistarGuideRepository.officialImage(fallback)?fallback:"",provider=metadata.optString("provider");
        if(url.isEmpty()&&!provider.isEmpty()){
            java.util.concurrent.CompletableFuture<String> result=new java.util.concurrent.CompletableFuture<>();
            movistarArtwork.request(provider,metadata.optLong("start"),metadata.optString("title"),result::complete);
            try{url=result.get(16,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception ignored){}
        }
        if(url.isEmpty())url=fallback;if(url.isEmpty())throw new java.io.IOException("Artwork unavailable");
        com.bumptech.glide.RequestBuilder<android.graphics.Bitmap> request=Glide.with(getApplicationContext()).asBitmap().load(authenticatedPosterModel(url)).diskCacheStrategy(DiskCacheStrategy.ALL).fitCenter().override(480,270);
        if(!fallback.isEmpty()&&!fallback.equals(url))request=request.error(Glide.with(getApplicationContext()).asBitmap().load(authenticatedPosterModel(fallback)).fitCenter().override(480,270));
        com.bumptech.glide.request.FutureTarget<android.graphics.Bitmap> target=request.submit();
        try {android.graphics.Bitmap bitmap=target.get(12,java.util.concurrent.TimeUnit.SECONDS);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,85,out);return out.toByteArray();}finally{Glide.with(getApplicationContext()).clear(target);}
    }

    private String manageDevicePanel(String text,PersonalPlaylistController importer)throws Exception {
        JSONObject request=new JSONObject(text);String action=request.optString("action");
        if(action.startsWith("guide-") && "__drbep".equals(request.optString("source"))) {
            java.util.concurrent.FutureTask<java.util.List<ChannelItem>> snapshot = new java.util.concurrent.FutureTask<>(() -> new ArrayList<>(channels));
            uiHandler.post(snapshot);
            try(TimelineEpgStore store=new TimelineEpgStore(getApplicationContext())) {
                return ServerGuidePanel.manage(request,snapshot.get(5,java.util.concurrent.TimeUnit.SECONDS),epgRepository,store);
            }
        }
        if(!action.startsWith("remote")&&!action.startsWith("catchup")) {
            String result=importer.manageWeb(text);
            if(action.equals("clear-history")) {
                java.util.Set<String> episodeIds=importer.seriesIds(request.optString("source"),request.optString("series"));
                java.util.concurrent.FutureTask<Void> clear=new java.util.concurrent.FutureTask<>(()->{for(String id:episodeIds)vodResumePositions.remove(id);saveVodResumePositions();return null;});
                uiHandler.post(clear);clear.get(5,java.util.concurrent.TimeUnit.SECONDS);
            }
            return result;
        }
        if(action.startsWith("catchup"))return devicePanelCatchup(request);
        java.util.concurrent.FutureTask<String> task=new java.util.concurrent.FutureTask<>(()->devicePanelOnUi(request));
        uiHandler.post(task);try{return task.get(5,java.util.concurrent.TimeUnit.SECONDS);}catch(java.util.concurrent.ExecutionException e){if(e.getCause() instanceof Exception)throw (Exception)e.getCause();throw e;}catch(java.util.concurrent.TimeoutException e){task.cancel(false);throw new DeviceWebPanel.PanelError("El dispositivo está ocupado. Vuelve a intentarlo.");}
    }
    private String devicePanelCatchup(JSONObject request)throws Exception {
        final String action=request.optString("action");
        java.util.concurrent.FutureTask<Object[]> capture=new java.util.concurrent.FutureTask<>(()->{
            if(activityDestroyed)throw new DeviceWebPanel.PanelError("El reproductor está cerrado.");
            ensureArchiveScope();if(archiveWindowKey.isEmpty())loadArchiveCatalog(false);
            java.util.Map<String,String> allowed=new java.util.LinkedHashMap<>();
            List<ChannelItem> permitted=archiveChannels();
            for(ChannelItem c:permitted)allowed.put(c.id,displayName(c));
            boolean panelLoading=action.equals("catchup-list")&&queuePanelCatchupDay(request,permitted);
            return new Object[]{archiveScope,allowed,archiveState.getLoading()||panelLoading};
        });
        uiHandler.post(capture);Object[] context;
        try{context=capture.get(5,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception e){capture.cancel(false);throw e;}
        String scope=(String)context[0];
        @SuppressWarnings("unchecked") java.util.Map<String,String> allowed=(java.util.Map<String,String>)context[1];
        if(action.equals("catchup-list")) {
            String day=request.optString("day",java.time.LocalDate.now().toString());if(day.isEmpty())day=java.time.LocalDate.now().toString();
            String query=request.optString("query");if(query.length()>200)throw new DeviceWebPanel.PanelError("La búsqueda es demasiado larga.");
            long now=System.currentTimeMillis();
            U7dCatalogStore.Page page=archiveStore.page(scope,new ArrayList<>(allowed.keySet()),day,request.optString("channel"),request.optString("genre"),query,request.optBoolean("saved"),Math.max(0,request.optInt("offset")),51,now);
            JSONArray rows=new JSONArray(),days=new JSONArray(),channels=new JSONArray(),genres=new JSONArray();
            for(EpgRepository.EpgProgram p:page.programs){long start=EpgTimeCodec.parseEpochMillis(p.startTime),end=EpgTimeCodec.parseEpochMillis(p.endTime);rows.put(new JSONObject().put("id",U7dCatalogStore.id(p)).put("title",p.title).put("channel",allowed.get(p.channelId)).put("genre",p.category).put("description",p.description).put("start",start).put("end",end).put("saved",archiveStore.saved(scope,U7dCatalogStore.id(p))).put("airing",start<=now&&end>now).put("available",end+7L*86400000>now));}
            for(int i=0;i<=7;i++)days.put(java.time.LocalDate.now().minusDays(i).toString());
            for(java.util.Map.Entry<String,String> e:allowed.entrySet())channels.put(new JSONObject().put("id",e.getKey()).put("name",e.getValue()));
            for(String genre:archiveStore.genres(scope))genres.put(genre);
            return new JSONObject().put("rows",rows).put("total",page.total).put("days",days).put("channels",channels).put("genres",genres).put("day",day).put("loading",context[2]).toString();
        }
        if(!action.equals("catchup-play")&&!action.equals("catchup-save"))throw new DeviceWebPanel.PanelError("Operación no disponible.");
        EpgRepository.EpgProgram p=archiveStore.find(scope,request.getString("id"));
        if(p==null||!allowed.containsKey(p.channelId))throw new DeviceWebPanel.PanelError("Programa no disponible.");
        java.util.concurrent.FutureTask<String> command=new java.util.concurrent.FutureTask<>(()->{
            if(!scope.equals(archiveScope))throw new DeviceWebPanel.PanelError("La cuenta ha cambiado.");
            ChannelItem c=findAllowedHomeLiveChannel(p.channelId);if(c==null||!supportsU7d(c))throw new DeviceWebPanel.PanelError("Canal no disponible.");
            long expires=EpgTimeCodec.parseEpochMillis(p.endTime)+7L*86400000;
            if(action.equals("catchup-save"))toggleArchiveSaved(p,expires);
            else {if(expires<System.currentTimeMillis())throw new DeviceWebPanel.PanelError("El programa ha caducado.");runArchiveAction(c,()->playFromDevicePanel(()->playMovistarIsmU7dProgram(c,p)));}
            return "{\"ok\":true}";
        });
        uiHandler.post(command);try{return command.get(5,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception e){command.cancel(false);throw e;}
    }
    private String devicePanelOnUi(JSONObject request)throws Exception {
        if(activityDestroyed)throw new DeviceWebPanel.PanelError("El reproductor está cerrado.");
        String action=request.optString("action");JSONObject out=new JSONObject();
        if(action.equals("remote-status")) {
            ChannelItem current=getCurrentPlaybackChannelItem();boolean media=playerController!=null&&current!=null&&!"IDLE".equals(playerController.getPlaybackDiagnostics().playbackState);
            boolean live=media&&!current.isVod&&!isCurrentU7dPlayback();
            return out.put("title",current==null?"Sin reproducción":displayName(current)).put("hasMedia",media).put("playing",media&&playerController.isPlaying()).put("live",live)
                .put("seekable",media&&(isCurrentU7dPlayback()||playerController.isPanelSeekable())).put("canPrevious",live).put("canNext",live).put("canLive",isCurrentU7dPlayback()).toString();
        }
        if(action.equals("remote-command")) {
            if(playerController==null||getCurrentPlaybackChannelItem()==null)throw new DeviceWebPanel.PanelError("No hay una reproducción activa.");
            String command=request.getString("command");
            switch(command){
                case "pause":playerController.setPlayWhenReady(!playerController.isPlaying());break;
                case "stop":playerController.stopForSourceSwitch();break;
                case "previous":case "next":if(getCurrentPlaybackChannelItem().isVod||isCurrentU7dPlayback())throw new DeviceWebPanel.PanelError("El contenido no tiene un canal siguiente.");tuneRelative(command.equals("next")?1:-1);break;
                case "seek":long delta=request.optLong("delta");if(Math.abs(delta)>60000)throw new DeviceWebPanel.PanelError("Salto no válido.");if(isCurrentU7dPlayback())seekCurrentU7dPlaybackTo(Math.max(0,currentPlaybackU7dOffsetMs+playerController.getCurrentPlaybackPosition()+delta));else {if(!playerController.isPanelSeekable())throw new DeviceWebPanel.PanelError("Esta reproducción no permite avanzar ni retroceder.");playerController.seekToPosition(Math.max(0,Math.min(playerController.getCurrentVodDurationMs(),playerController.getCurrentPlaybackPosition()+delta)));}break;
                case "live":if(!isCurrentU7dPlayback()||currentPlaybackU7dChannel==null)throw new DeviceWebPanel.PanelError("Ya estás en directo.");tuneChannelById(currentPlaybackU7dChannel.id);break;
                default:throw new DeviceWebPanel.PanelError("Control no disponible.");
            }
            return out.put("ok",true).toString();
        }
        throw new DeviceWebPanel.PanelError("Operación no disponible.");
    }

