    private void showVodLibraryList(int titleResId, List<ChannelItem> items, boolean progressFirst, Runnable onBack, int pageIndex) {
        if (progressFirst) {
            sortVodLibraryItems(items);
        }
        showPagedVodLibraryList(getString(titleResId), items, onBack, pageIndex);
    }

    private void showPagedVodLibraryList(String title, List<ChannelItem> items, Runnable onBack, int pageIndex) {
        List<ChannelItem> sourceItems = items == null ? new ArrayList<>() : items;
        int total = sourceItems.size();
        if (total <= VOD_DENSE_PAGE_SIZE) {
            Runnable returnToList = () -> showPagedVodLibraryList(title, sourceItems, onBack, 0);
            showQuickChannelListDialog(
                    title,
                    sourceItems,
                    getString(R.string.vod_library_empty),
                    item -> showVodInfoDialog(item, returnToList),
                    onBack
            );
            return;
        }
        int totalPages = Math.max(1, (int) Math.ceil(total / (double) VOD_DENSE_PAGE_SIZE));
        int safePage = Math.max(0, Math.min(pageIndex, totalPages - 1));
        int start = safePage * VOD_DENSE_PAGE_SIZE;
        int end = Math.min(total, start + VOD_DENSE_PAGE_SIZE);
        List<ChannelItem> pageItems = new ArrayList<>(sourceItems.subList(start, end));
        Runnable returnToPage = () -> showPagedVodLibraryList(title, sourceItems, onBack, safePage);
        List<ZapActionItem> actions = new ArrayList<>();
        actions.add(new ZapActionItem(
                getString(R.string.vod_dense_prev_page),
                safePage > 0,
                false,
                false,
                safePage > 0 ? () -> showPagedVodLibraryList(title, sourceItems, onBack, safePage - 1) : null
        ));
        actions.add(new ZapActionItem(
                getString(R.string.vod_dense_next_page),
                safePage < totalPages - 1,
                false,
                false,
                safePage < totalPages - 1 ? () -> showPagedVodLibraryList(title, sourceItems, onBack, safePage + 1) : null
        ));
        String subtitle = getString(R.string.vod_dense_page_subtitle, start + 1, end, total, safePage + 1, totalPages);
        showQuickChannelListDialog(
                title,
                subtitle,
                pageItems,
                getString(R.string.vod_library_empty),
                item -> showVodInfoDialog(item, returnToPage),
                onBack,
                actions
        );
    }

    private void showPlexVodBrowser(Runnable onBack) {
        if (catalogRepository == null) {
            showStatus(getString(R.string.vod_plex_unavailable));
            return;
        }
        showLoading(
                getString(R.string.vod_library_plex),
                getString(R.string.vod_plex_loading),
                getString(R.string.vod_plex_all_libraries)
        );
        interactiveExecutor.execute(() -> {
            List<PlexVodLibrary> libraries = null;
            Exception failure = null;
            try {
                libraries = catalogRepository.fetchPlexVodLibraries();
            } catch (Exception e) {
                failure = e;
                Log.w(TAG, "Plex VOD libraries request failed", e);
            }
            List<PlexVodLibrary> loaded = libraries == null ? new ArrayList<>() : libraries;
            Exception finalFailure = failure;
            postUiIfAlive(() -> {
                hideStartupLoading();
                if (finalFailure != null || loaded.isEmpty()) {
                    showStatus(getString(R.string.vod_plex_unavailable));
                    if (onBack != null) {
                        onBack.run();
                    }
                    return;
                }
                showPlexVodTypeDialog(loaded, onBack);
            });
        });
    }

    private void showPlexVodTypeDialog(List<PlexVodLibrary> libraries, Runnable onBack) {
        int movies = 0;
        int series = 0;
        int episodes = 0;
        for (PlexVodLibrary library : libraries) {
            if (library == null) {
                continue;
            }
            movies += library.movies;
            series += library.series;
            episodes += library.episodes;
        }
        List<String> options = new ArrayList<>();
        List<Runnable> actions = new ArrayList<>();
        options.add(getString(R.string.vod_plex_library_count, getString(R.string.vod_plex_movies), movies));
        actions.add(() -> showPlexVodLibrariesDialog("movies", libraries, () -> showPlexVodTypeDialog(libraries, onBack)));
        options.add(getString(R.string.vod_plex_series_count, getString(R.string.vod_plex_series), series, episodes));
        actions.add(() -> showPlexVodLibrariesDialog("series", libraries, () -> showPlexVodTypeDialog(libraries, onBack)));
        showTvOptionsDialog(R.string.vod_library_plex, null, options, actions, onBack);
    }

    private void showPlexVodLibrariesDialog(String kind, List<PlexVodLibrary> libraries, Runnable onBack) {
        boolean series = "series".equals(kind);
        int total = 0;
        for (PlexVodLibrary library : libraries) {
            if (library != null) {
                total += series ? library.series : library.movies;
            }
        }
        List<String> options = new ArrayList<>();
        List<Runnable> actions = new ArrayList<>();
        String allLabel = series
                ? getString(R.string.vod_plex_series_count, getString(R.string.vod_plex_all_libraries), total, plexEpisodeCount(libraries))
                : getString(R.string.vod_plex_library_count, getString(R.string.vod_plex_all_libraries), total);
        options.add(allLabel);
        actions.add(() -> openPlexVodSelection(kind, 0L, getString(R.string.vod_plex_all_libraries), "", "recent", 0, () -> showPlexVodLibrariesDialog(kind, libraries, onBack)));
        for (PlexVodLibrary library : libraries) {
            if (library == null) {
                continue;
            }
            int count = series ? library.series : library.movies;
            if (count <= 0) {
                continue;
            }
            String baseLabel = library.sourceName + " · " + library.title;
            String label = series
                    ? getString(R.string.vod_plex_series_count, baseLabel, library.series, library.episodes)
                    : getString(R.string.vod_plex_library_count, baseLabel, library.movies);
            options.add(label);
            actions.add(() -> openPlexVodSelection(kind, library.id, baseLabel, "", "recent", 0, () -> showPlexVodLibrariesDialog(kind, libraries, onBack)));
        }
        showTvOptionsDialog(
                R.string.vod_library_plex,
                series ? getString(R.string.vod_plex_series) : getString(R.string.vod_plex_movies),
                options,
                actions,
                onBack
        );
    }

    private int plexEpisodeCount(List<PlexVodLibrary> libraries) {
        int total = 0;
        if (libraries != null) {
            for (PlexVodLibrary library : libraries) {
                if (library != null) {
                    total += library.episodes;
                }
            }
        }
        return total;
    }

    private void openPlexVodSelection(String kind, long libraryId, String libraryLabel, String query, String sort, int offset, Runnable onBack) {
        if ("series".equals(kind)) {
            showPlexSeriesPage(libraryId, libraryLabel, query, sort, offset, onBack);
        } else {
            showPlexMoviesPage(libraryId, libraryLabel, query, sort, offset, onBack);
        }
    }

    private void showPlexMoviesPage(long libraryId, String libraryLabel, String query, String sort, int offset, Runnable onBack) {
        showLoading(getString(R.string.vod_library_plex), getString(R.string.vod_plex_loading), libraryLabel);
        interactiveExecutor.execute(() -> {
            PlexVodPage page = null;
            Exception failure = null;
            try {
                page = catalogRepository.fetchPlexVodPage("movies", libraryId, "", query, offset, 100, sort);
            } catch (Exception e) {
                failure = e;
                Log.w(TAG, "Plex movies request failed library=" + libraryId + " offset=" + offset, e);
            }
            PlexVodPage loaded = page;
            Exception finalFailure = failure;
            postUiIfAlive(() -> {
                hideStartupLoading();
                if (finalFailure != null || loaded == null) {
                    showStatus(getString(R.string.vod_plex_unavailable));
                    if (onBack != null) {
                        onBack.run();
                    }
                    return;
                }
                if (loaded.items.isEmpty()) {
                    showStatus(getString(R.string.vod_plex_empty));
                    if (onBack != null) {
                        onBack.run();
                    }
                    return;
                }
                Runnable returnToPage = () -> showPlexMoviesPage(libraryId, libraryLabel, query, sort, loaded.offset, onBack);
                List<ZapActionItem> panelActions = buildPlexPageActions(
                        loaded.offset,
                        loaded.nextOffset,
                        loaded.hasMore,
                        () -> showPlexMoviesPage(libraryId, libraryLabel, query, sort, Math.max(0, loaded.offset - 100), onBack),
                        () -> showPlexMoviesPage(libraryId, libraryLabel, query, sort, loaded.nextOffset, onBack),
                        () -> showPlexSearchDialog("movies", libraryId, libraryLabel, query, sort, onBack),
                        "recent".equals(sort),
                        () -> showPlexMoviesPage(libraryId, libraryLabel, query, nextPlexSort(sort), 0, onBack)
                );
                showQuickChannelListDialog(
                        getString(R.string.vod_plex_movies) + " · " + libraryLabel,
                        plexPageSubtitle(loaded.offset, loaded.items.size(), loaded.total),
                        loaded.items,
                        getString(R.string.vod_plex_empty),
                        item -> showVodInfoDialog(item, returnToPage),
                        onBack,
                        panelActions
                );
            });
        });
    }

    private void showPlexSeriesPage(long libraryId, String libraryLabel, String query, String sort, int offset, Runnable onBack) {
        showLoading(getString(R.string.vod_library_plex), getString(R.string.vod_plex_loading), libraryLabel);
        interactiveExecutor.execute(() -> {
            PlexVodSeriesPage page = null;
            Exception failure = null;
            try {
                page = catalogRepository.fetchPlexVodSeriesPage(libraryId, query, offset, 100, sort);
            } catch (Exception e) {
                failure = e;
                Log.w(TAG, "Plex series request failed library=" + libraryId + " offset=" + offset, e);
            }
            PlexVodSeriesPage loaded = page;
            Exception finalFailure = failure;
            postUiIfAlive(() -> {
                hideStartupLoading();
                if (finalFailure != null || loaded == null) {
                    showStatus(getString(R.string.vod_plex_unavailable));
                    if (onBack != null) {
                        onBack.run();
                    }
                    return;
                }
                if (loaded.items.isEmpty()) {
                    showStatus(getString(R.string.vod_plex_empty));
                    if (onBack != null) {
                        onBack.run();
                    }
                    return;
                }
                List<ChannelItem> displayItems = new ArrayList<>();
                Map<String, PlexVodSeries> byID = new LinkedHashMap<>();
                int order = 1;
                for (PlexVodSeries series : loaded.items) {
                    String id = "plex-series-" + series.libraryId + "-" + Integer.toHexString(series.title.hashCode());
                    ChannelItem item = new ChannelItem(
                            id,
                            series.title,
                            "",
                            series.posterUrl,
                            series.libraryTitle,
                            "",
                            "",
                            order,
                            order,
                            true,
                            false,
                            0,
                            series.sourceName.isEmpty() ? "Plex" : "Plex · " + series.sourceName,
                            new ArrayList<>(),
                            "",
                            "",
                            "vod:plex:series",
                            false,
                            getString(R.string.vod_plex_series_meta, series.seasons, series.episodes),
                            series.year > 0 ? String.valueOf(series.year) : "",
                            0L
                    );
                    displayItems.add(item);
                    byID.put(id, series);
                    order++;
                }
                Runnable returnToPage = () -> showPlexSeriesPage(libraryId, libraryLabel, query, sort, loaded.offset, onBack);
                List<ZapActionItem> panelActions = buildPlexPageActions(
                        loaded.offset,
                        loaded.nextOffset,
                        loaded.hasMore,
                        () -> showPlexSeriesPage(libraryId, libraryLabel, query, sort, Math.max(0, loaded.offset - 100), onBack),
                        () -> showPlexSeriesPage(libraryId, libraryLabel, query, sort, loaded.nextOffset, onBack),
                        () -> showPlexSearchDialog("series", libraryId, libraryLabel, query, sort, onBack),
                        "recent".equals(sort),
                        () -> showPlexSeriesPage(libraryId, libraryLabel, query, nextPlexSort(sort), 0, onBack)
                );
                showQuickChannelListDialog(
                        getString(R.string.vod_plex_series) + " · " + libraryLabel,
                        plexPageSubtitle(loaded.offset, displayItems.size(), loaded.total),
                        displayItems,
                        getString(R.string.vod_plex_empty),
                        item -> {
                            PlexVodSeries selected = item == null ? null : byID.get(item.id);
                            if (selected != null) {
                                showPlexEpisodesPage(selected, 0, returnToPage);
                            }
                        },
                        onBack,
                        panelActions
                );
            });
        });
    }

    private void showPlexEpisodesPage(PlexVodSeries series, int offset, Runnable onBack) {
        showLoading(getString(R.string.vod_library_plex), getString(R.string.vod_plex_loading), series.title);
        interactiveExecutor.execute(() -> {
            PlexVodPage page = null;
            Exception failure = null;
            try {
                page = catalogRepository.fetchPlexVodPage("series", series.libraryId, series.title, "", offset, 100);
            } catch (Exception e) {
                failure = e;
                Log.w(TAG, "Plex episodes request failed series=" + series.title + " offset=" + offset, e);
            }
            PlexVodPage loaded = page;
            Exception finalFailure = failure;
            postUiIfAlive(() -> {
                hideStartupLoading();
                if (finalFailure != null || loaded == null || loaded.items.isEmpty()) {
                    showStatus(finalFailure == null ? getString(R.string.vod_plex_empty) : getString(R.string.vod_plex_unavailable));
                    if (onBack != null) {
                        onBack.run();
                    }
                    return;
                }
                Runnable returnToPage = () -> showPlexEpisodesPage(series, loaded.offset, onBack);
                List<ZapActionItem> actions = buildPlexPageActions(
                        loaded.offset,
                        loaded.nextOffset,
                        loaded.hasMore,
                        () -> showPlexEpisodesPage(series, Math.max(0, loaded.offset - 100), onBack),
                        () -> showPlexEpisodesPage(series, loaded.nextOffset, onBack),
                        null,
                        false,
                        null
                );
                showQuickChannelListDialog(
                        series.title,
                        plexPageSubtitle(loaded.offset, loaded.items.size(), loaded.total),
                        loaded.items,
                        getString(R.string.vod_plex_empty),
                        item -> showVodInfoDialog(item, returnToPage),
                        onBack,
                        actions
                );
            });
        });
    }

    private List<ZapActionItem> buildPlexPageActions(
            int offset,
            int nextOffset,
            boolean hasMore,
            Runnable previous,
            Runnable next,
            Runnable search,
            boolean recentSort,
            Runnable toggleSort
    ) {
        List<ZapActionItem> actions = new ArrayList<>();
        actions.add(new ZapActionItem(
                getString(R.string.vod_dense_prev_page),
                offset > 0,
                false,
                false,
                offset > 0 ? previous : null
        ));
        actions.add(new ZapActionItem(
                getString(R.string.vod_dense_next_page),
                hasMore && nextOffset > offset,
                false,
                false,
                hasMore && nextOffset > offset ? next : null
        ));
        if (search != null) {
            actions.add(new ZapActionItem(getString(R.string.vod_plex_search), true, true, false, search));
        }
        if (toggleSort != null) {
            actions.add(new ZapActionItem(
                    getString(recentSort ? R.string.vod_plex_sort_recent : R.string.vod_plex_sort_title),
                    true,
                    false,
                    recentSort,
                    toggleSort
            ));
        }
        return actions;
    }

    private String nextPlexSort(String sort) {
        return "recent".equals(sort) ? "title" : "recent";
    }

    private void showPlexSearchDialog(String kind, long libraryId, String libraryLabel, String initialQuery, String sort, Runnable onBack) {
        showTvTextInputPanel(new TvTextInputPanelUiModel(
                getString(R.string.vod_plex_search),
                libraryLabel,
                getString(R.string.search_channel_dialog_action),
                getString(R.string.dialog_cancel),
                getString(R.string.vod_search_all),
                java.util.Collections.singletonList(new TvTextInputFieldUiModel(
                        getString(R.string.vod_search_hint),
                        initialQuery == null ? "" : initialQuery,
                        false,
                        false
                )),
                values -> {
                    String query = values == null || values.isEmpty() ? "" : values.get(0);
                    openPlexVodSelection(kind, libraryId, libraryLabel, query, sort, 0, onBack);
                },
                onBack,
                () -> openPlexVodSelection(kind, libraryId, libraryLabel, "", sort, 0, onBack)
        ));
    }

    private String plexPageSubtitle(int offset, int pageSize, int total) {
        int start = total <= 0 || pageSize <= 0 ? 0 : offset + 1;
        int end = Math.min(total, offset + pageSize);
        return getString(R.string.vod_plex_page_subtitle, start, end, total);
    }

    private String buildVodLibrarySummary() {
        int total = 0;
        int adult = 0;
        int progress = 0;
        for (ChannelItem item : allChannels) {
            if (item == null || !item.isVod) {
                continue;
            }
            total++;
            if (item.isAdultVod) {
                adult++;
            }
            if (getVodResumePosition(item.id) > 30_000L) {
                progress++;
            }
        }
        return getString(R.string.vod_library_summary, total, adult, progress);
    }

    private String buildVodLibraryOptionLabel(int titleResId, List<ChannelItem> items) {
        int count = items == null ? 0 : items.size();
        return getString(titleResId) + " (" + count + ")";
    }

    private enum VodSortMode {
        ALPHA,
        YEAR_DESC,
        DURATION_DESC
    }

    enum VodVisualTypeFilter {
        GENERAL("Todo"),
        MOVIES("Peliculas"),
        SERIES("Series"),
        ADULT("Adulto"),
        ALL("Todo");

        final String label;

        VodVisualTypeFilter(String label) {
            this.label = label;
        }

        VodVisualTypeFilter next() {
            if (this == ADULT || this == ALL) return GENERAL;
            VodVisualTypeFilter[] values = values();
            return values[(ordinal() + 1) % values.length];
        }
    }

    enum VodVisualPlatformFilter {
        ALL("Mis plataformas"),
        HBO("HBO Max"),
        MOVISTAR("Movistar"),
        TIVIFY("Tivify"),
        RUNTIME("Runtime"),
        PLEX("Plex"),
        DAZN("DAZN"),
        PRIME("Prime Video"),
        SKYSHOWTIME("SkyShowtime"),
        DISNEYPLUS("Disney+"),
        APPLETV("Apple TV+"),
        NETFLIX("Netflix"),
        OTHER("Otros");

        final String label;

        VodVisualPlatformFilter(String label) {
            this.label = label;
        }

        VodVisualPlatformFilter next() {
            VodVisualPlatformFilter[] values = values();
            return values[(ordinal() + 1) % values.length];
        }
    }

    enum VodVisualStatusFilter {
        ALL("Todo"),
        CONTINUE("Pendientes"),
        PROGRESS("Con progreso"),
        NOT_STARTED("Sin empezar"),
        WATCHED("Vistos");

        final String label;

        VodVisualStatusFilter(String label) {
            this.label = label;
        }

        VodVisualStatusFilter next() {
            if (this == CONTINUE || this == PROGRESS) return NOT_STARTED;
            VodVisualStatusFilter[] values = values();
            return values[(ordinal() + 1) % values.length];
        }
    }

    enum VodVisualSortFilter {
        SMART("Recomendado"),
        ALPHA("A-Z"),
        RECENT("Últimos vistos"),
        YEAR("Ano"),
        DURATION("Duracion");

        final String label;

        VodVisualSortFilter(String label) {
            this.label = label;
        }

        VodVisualSortFilter next() {
            VodVisualSortFilter[] values = values();
            return values[(ordinal() + 1) % values.length];
        }
    }

    private boolean isDefaultVodVisualFilter(VodVisualTypeFilter typeFilter, VodVisualPlatformFilter platformFilter, VodVisualStatusFilter statusFilter, VodVisualSortFilter sortFilter) {
        return typeFilter == VodVisualTypeFilter.GENERAL
                && statusFilter == VodVisualStatusFilter.ALL
                && sortFilter == VodVisualSortFilter.SMART;
    }

    private List<ChannelItem> buildVodVisualFilteredItems(VodVisualTypeFilter typeFilter, VodVisualPlatformFilter platformFilter, VodVisualStatusFilter statusFilter, VodVisualSortFilter sortFilter) {
        return buildVodVisualFilteredItems(typeFilter, platformFilter, statusFilter, sortFilter, "");
    }

    private boolean isVodItemAuthorized(ChannelItem item) {
        if (item == null || !canOpenVodLibrary()) return false;
        if (item.isAdultVod) return currentOfflinePermissions.allowsTivifyAdultVod();
        for (VodVisualPlatformFilter origin : VodVisualPlatformFilter.values()) {
            if (origin == VodVisualPlatformFilter.ALL || origin == VodVisualPlatformFilter.OTHER) continue;
            if (matchesVodVisualPlatform(item, origin)) return isVodPlatformFilterAvailable(origin, 0);
        }
        return false;
    }

    private List<ChannelItem> filterVisibleVodOrigin(List<ChannelItem> source, VodVisualPlatformFilter origin) {
        List<ChannelItem> visible = new ArrayList<>();
        for (ChannelItem item : source) if (isVodItemAuthorized(item) && !item.isAdultVod && matchesVodVisualPlatform(item, origin) && !shouldHideProtectedItem(item)) visible.add(item);
        return visible;
    }

    private void searchVodOrigin(String query, VodVisualTypeFilter type, VodVisualPlatformFilter origin,
            VodVisualStatusFilter status, VodVisualSortFilter sort, Runnable back) {
        Runnable restore = () -> showVodVisualLibraryDialog(type, origin, status, sort, query, back);
        showTvTextInputPanel(new TvTextInputPanelUiModel("Buscar · " + origin.label, "", "Buscar", "Cancelar", "",
                java.util.Collections.singletonList(new TvTextInputFieldUiModel("Título o serie", query, false, false)),
                values -> showVodVisualLibraryDialog(type, origin, status, sort, values.isEmpty() ? "" : values.get(0), back), restore, null));
    }

    private List<ChannelItem> buildVodVisualFilteredItems(VodVisualTypeFilter typeFilter, VodVisualPlatformFilter platformFilter, VodVisualStatusFilter statusFilter, VodVisualSortFilter sortFilter, String query) {
        String trimmedQuery = query == null ? "" : query.trim();
        List<ChannelItem> items = new ArrayList<>();
        for (ChannelItem item : allChannels) {
            if (item == null || !item.isVod || !isVodItemAuthorized(item) || shouldHideProtectedItem(item) || !matchesVodVisualType(item, typeFilter) || !matchesVodVisualPlatform(item, platformFilter) || !matchesVodVisualStatus(item, statusFilter)) {
                continue;
            }
            if (!matchesVodSearchQuery(item, trimmedQuery)) {
                continue;
            }
            items.add(item);
        }
        if (statusFilter == VodVisualStatusFilter.ALL) items = groupSkySeries(items);
        sortVodVisualFilteredItems(items, sortFilter);
        return items;
    }

    static List<ChannelItem> skySeriesEpisodes(ChannelItem series, List<ChannelItem> source) {
        List<ChannelItem> result = new ArrayList<>();
        if (series == null || series.playUrl == null || !series.playUrl.startsWith("sky-series:")) return result;
        String seriesId = series.playUrl.substring("sky-series:".length());
        if (seriesId.isEmpty()) return result;
        for (ChannelItem item : source) {
            if (item != null && item.isVod && "SkyShowtime".equals(item.platformName)
                    && seriesId.equals(item.vodSeriesId) && item.playUrl != null
                    && !item.playUrl.startsWith("sky-series:")) result.add(item);
        }
        result.sort(java.util.Comparator.comparingInt((ChannelItem item) -> item.vodSeason)
                .thenComparingInt(item -> item.vodEpisode).thenComparingInt(item -> item.originalOrder));
        return result;
    }

    static List<ChannelItem> groupSkySeries(List<ChannelItem> items) {
        List<ChannelItem> grouped = new ArrayList<>();
        Map<String, ChannelItem> series = new LinkedHashMap<>();
        for (ChannelItem item : items) {
            if (!"SkyShowtime".equals(item.platformName) || item.vodSeriesId == null || item.vodSeriesId.isEmpty()) {
                grouped.add(item); continue;
            }
            ChannelItem card = series.get(item.vodSeriesId);
            if (card == null) {
                String title = item.vodSeriesTitle == null || item.vodSeriesTitle.isEmpty() ? item.name : item.vodSeriesTitle;
                card = new ChannelItem("sky-series:" + item.vodSeriesId, title, "", item.logoUrl, item.group,
                        "sky-series:" + item.vodSeriesId, "", item.originalOrder, item.dashboardOrder,
                        true, false, item.platformId, item.platformName, new ArrayList<>(), "", "", "vod:skyshowtime:series", false);
                card.vodReleaseDate = item.vodReleaseDate;
                series.put(item.vodSeriesId, card); grouped.add(card);
            } else if (VodCatalogOrder.dateKey(item) > VodCatalogOrder.dateKey(card)) card.vodReleaseDate = item.vodReleaseDate;
        }
        return grouped;
    }

    private boolean matchesVodSearchQuery(ChannelItem item, String query) {
        if (query == null || query.trim().isEmpty()) {
            return true;
        }
        if (item == null) {
            return false;
        }
        String haystack = displayName(item) + " " + item.group + " " + item.platformName + " " + item.vodYear + " " + item.vodSeriesTitle;
        return matchesSearch(haystack, query);
    }

    private String buildVodSearchSummary(String query) {
        List<ChannelItem> all = buildVodVisualFilteredItems(VodVisualTypeFilter.ALL, VodVisualPlatformFilter.ALL, VodVisualStatusFilter.ALL, VodVisualSortFilter.SMART, query);
        int movistar = 0;
        int tivify = 0;
        int runtime = 0;
        int adult = 0;
        int progress = 0;
        for (ChannelItem item : all) {
            if (item == null) {
                continue;
            }
            if (item.isAdultVod) {
                adult++;
            }
            if (matchesVodVisualPlatform(item, VodVisualPlatformFilter.MOVISTAR)) {
                movistar++;
            } else if (matchesVodVisualPlatform(item, VodVisualPlatformFilter.TIVIFY)) {
                tivify++;
            } else if (matchesVodVisualPlatform(item, VodVisualPlatformFilter.RUNTIME)) {
                runtime++;
            }
            if (getVodResumePosition(item.id) > 30_000L) {
                progress++;
            }
        }
        return getString(R.string.vod_search_visual_summary, all.size(), movistar, tivify, runtime, adult, progress);
    }

    private boolean matchesVodVisualType(ChannelItem item, VodVisualTypeFilter typeFilter) {
        if (typeFilter == VodVisualTypeFilter.ALL) {
            return true;
        }
        if (typeFilter == VodVisualTypeFilter.ADULT) {
            return item.isAdultVod;
        }
        if (item.isAdultVod) {
            return false;
        }
        String filterKey = item.vodFilterKey == null ? "" : item.vodFilterKey.toLowerCase(Locale.ROOT);
        if (typeFilter == VodVisualTypeFilter.MOVIES) {
            return filterKey.contains(":movies") || filterKey.contains(":movie");
        }
        if (typeFilter == VodVisualTypeFilter.SERIES) {
            return filterKey.contains(":series") || filterKey.contains(":show") || filterKey.contains(":episodes");
        }
        return true;
    }

    static boolean matchesVodVisualPlatform(ChannelItem item, VodVisualPlatformFilter platformFilter) {
        if (platformFilter == VodVisualPlatformFilter.ALL) {
            return true;
        }
        String filterKey = item.vodFilterKey == null ? "" : item.vodFilterKey.toLowerCase(Locale.ROOT);
        String platform = item.platformName == null ? "" : item.platformName.toLowerCase(Locale.ROOT);
        boolean isMovistar = filterKey.contains("movistar") || platform.contains("movistar");
        if (platformFilter == VodVisualPlatformFilter.MOVISTAR) return isMovistar;
        boolean isTivify = filterKey.contains("tivify") || platform.contains("tivify");
        if (platformFilter == VodVisualPlatformFilter.TIVIFY) return isTivify;
        boolean isRuntime = filterKey.contains("runtime") || platform.contains("runtime");
        if (platformFilter == VodVisualPlatformFilter.RUNTIME) return isRuntime;
        boolean isPlex = filterKey.contains("plex") || platform.contains("plex");
        if (platformFilter == VodVisualPlatformFilter.PLEX) return isPlex;
        boolean isDazn = filterKey.contains("dazn") || platform.contains("dazn");
        if (platformFilter == VodVisualPlatformFilter.DAZN) return isDazn;
        boolean isPrime = filterKey.contains("prime") || platform.contains("prime");
        if (platformFilter == VodVisualPlatformFilter.PRIME) return isPrime;
        boolean isSkyshowtime = filterKey.contains("skyshowtime") || platform.contains("skyshowtime");
        if (platformFilter == VodVisualPlatformFilter.SKYSHOWTIME) return isSkyshowtime;
        boolean isHbo = filterKey.contains("hbomax") || platform.contains("hbo");
        if (platformFilter == VodVisualPlatformFilter.HBO) return isHbo;
        boolean isApple = filterKey.contains("appletv") || platform.contains("apple tv")
                || platform.contains("appletv") || (item.id != null && item.id.startsWith("appletv:"));
        if (platformFilter == VodVisualPlatformFilter.APPLETV) return isApple;
        boolean isNetflix = filterKey.contains("netflix") || platform.contains("netflix")
                || (item.id != null && item.id.startsWith("netflix:"));
        if (platformFilter == VodVisualPlatformFilter.NETFLIX) return isNetflix;
        boolean isDisneyplus = isDisneyplusItem(item);
        if (platformFilter == VodVisualPlatformFilter.DISNEYPLUS) {
            return isDisneyplus;
        }
        return !isMovistar && !isTivify && !isRuntime && !isPlex && !isDazn && !isPrime && !isSkyshowtime && !isDisneyplus
                && !isHbo && !isApple && !isNetflix;
    }

    private boolean matchesVodVisualStatus(ChannelItem item, VodVisualStatusFilter statusFilter) {
        if (statusFilter == VodVisualStatusFilter.ALL) {
            return true;
        }
        long progress = getVodResumePosition(item == null ? null : item.id);
        boolean watched = item != null && (item.id.startsWith("hbomax:")
                ? hboHistory().get(item.id) != null && hboHistory().get(item.id).completed
                : item.vodDurationSeconds > 0 && progress >= item.vodDurationSeconds * 950L);
        if (statusFilter == VodVisualStatusFilter.WATCHED) return watched;
        if (statusFilter == VodVisualStatusFilter.CONTINUE || statusFilter == VodVisualStatusFilter.PROGRESS) {
            return progress > 30_000L && !watched;
        }
        return progress <= 0L;
    }

    private void sortVodVisualFilteredItems(List<ChannelItem> items, VodVisualSortFilter sortFilter) {
        if (items == null) {
            return;
        }
        if (sortFilter == VodVisualSortFilter.ALPHA) {
            items.sort((left, right) -> displayName(left).compareToIgnoreCase(displayName(right)));
        } else if (sortFilter == VodVisualSortFilter.YEAR) {
            items.sort((left, right) -> {
                int yearCompare = Integer.compare(parseVodYear(right), parseVodYear(left));
                return yearCompare != 0 ? yearCompare : displayName(left).compareToIgnoreCase(displayName(right));
            });
        } else if (sortFilter == VodVisualSortFilter.DURATION) {
            items.sort((left, right) -> {
                int durationCompare = Long.compare(right == null ? 0L : right.vodDurationSeconds, left == null ? 0L : left.vodDurationSeconds);
                return durationCompare != 0 ? durationCompare : displayName(left).compareToIgnoreCase(displayName(right));
            });
        } else if (sortFilter == VodVisualSortFilter.RECENT) {
            Map<String, Integer> recentRanks = buildRecentVodRankMap();
            items.sort((left, right) -> {
                int leftRank = recentRanks.getOrDefault(left == null ? "" : left.id, Integer.MAX_VALUE);
                int rightRank = recentRanks.getOrDefault(right == null ? "" : right.id, Integer.MAX_VALUE);
                int rankCompare = Integer.compare(leftRank, rightRank);
                return rankCompare != 0 ? rankCompare : displayName(left).compareToIgnoreCase(displayName(right));
            });
        } else {
            VodCatalogOrder.newest(items);
        }
    }

    private Map<String, Integer> buildRecentVodRankMap() {
        Map<String, Integer> ranks = new HashMap<>();
        List<RecentChannelsStore.RecentChannelItem> recents = recentChannelsStore == null ? new ArrayList<>() : recentChannelsStore.getItems();
        int rank = 0;
        for (RecentChannelsStore.RecentChannelItem recent : recents) {
            if (recent == null || recent.channelId == null || ranks.containsKey(recent.channelId)) {
                continue;
            }
            ranks.put(recent.channelId, rank++);
        }
        return ranks;
    }

    private List<ChannelItem> buildAllVodLibraryItems(boolean includeAdult) {
        List<ChannelItem> items = new ArrayList<>();
        for (ChannelItem item : allChannels) {
            if (item == null || !item.isVod || shouldHideProtectedItem(item)) {
                continue;
            }
            if (!includeAdult && item.isAdultVod) {
                continue;
            }
            items.add(item);
        }
        sortVodLibraryItems(items);
        return items;
    }

    private List<ChannelItem> buildVodSortedItems(VodSortMode sortMode) {
        List<ChannelItem> items = buildAllVodLibraryItems(false);
        if (sortMode == VodSortMode.YEAR_DESC) {
            items.sort((left, right) -> {
                int yearCompare = Integer.compare(parseVodYear(right), parseVodYear(left));
                if (yearCompare != 0) {
                    return yearCompare;
                }
                return displayName(left).compareToIgnoreCase(displayName(right));
            });
        } else if (sortMode == VodSortMode.DURATION_DESC) {
            items.sort((left, right) -> {
                int durationCompare = Long.compare(right == null ? 0L : right.vodDurationSeconds, left == null ? 0L : left.vodDurationSeconds);
                if (durationCompare != 0) {
                    return durationCompare;
                }
                return displayName(left).compareToIgnoreCase(displayName(right));
            });
        }
        return items;
    }

    private int parseVodYear(ChannelItem item) {
        if (item == null || item.vodYear == null || item.vodYear.trim().isEmpty()) {
            return 0;
        }
        try {
            return Integer.parseInt(item.vodYear.trim());
        } catch (Exception e) {
            return 0;
        }
    }

    private void showVodCategoriesDialog() {
        showVodCategoriesDialog(null);
    }

    private void showVodCategoriesDialog(Runnable onBack) {
        LinkedHashMap<String, List<ChannelItem>> categories = new LinkedHashMap<>();
        for (ChannelItem item : buildAllVodLibraryItems(false)) {
            String category = item.group == null || item.group.trim().isEmpty() ? getString(R.string.vod_library_uncategorized) : item.group.trim();
            List<ChannelItem> bucket = categories.get(category);
            if (bucket == null) {
                bucket = new ArrayList<>();
                categories.put(category, bucket);
            }
            bucket.add(item);
        }
        if (categories.isEmpty()) {
            showStatus(getString(R.string.vod_library_empty));
            return;
        }
        List<Map.Entry<String, List<ChannelItem>>> entries = new ArrayList<>(categories.entrySet());
        entries.sort((left, right) -> {
            int countCompare = Integer.compare(right.getValue().size(), left.getValue().size());
            if (countCompare != 0) {
                return countCompare;
            }
            return left.getKey().compareToIgnoreCase(right.getKey());
        });
        for (Map.Entry<String, List<ChannelItem>> entry : entries) {
            List<ChannelItem> categoryItems = new ArrayList<>(entry.getValue());
            sortVodLibraryItems(categoryItems);
            entry.setValue(categoryItems);
        }
        Runnable returnToCategories = () -> showVodCategoriesDialog(onBack);
        TvOptionsMenuModel menu = VodLibraryMenuUiFactory.buildCategories(entries, new VodLibraryMenuUiFactory.AdvancedHost() {
            @Override
            public String text(int resId) {
                return getString(resId);
            }

            @Override
            public String displayName(ChannelItem item) {
                return MainActivity.this.displayName(item);
            }

            @Override
            public void openCategory(String title, List<ChannelItem> items) {
                showPagedVodLibraryList(title, items, returnToCategories, 0);
            }

            @Override
            public void continueVod(ChannelItem item) {
            }

            @Override
            public void startOver(ChannelItem item) {
            }

            @Override
            public void clearProgress(ChannelItem item) {
            }
        });
        showTvOptionsDialog(R.string.vod_library_categories, menu.message, menu.options, menu.actions, onBack);
    }

    private List<ChannelItem> buildVodContinueItems() {
        List<ChannelItem> items = new ArrayList<>();
        Set<String> added = new HashSet<>();
        ChannelItem last = findChannelItemById(lastVodId);
        if (last != null && last.isVod && getVodResumePosition(last.id) > 30_000L && added.add(last.id)) {
            items.add(last);
        }
        for (ChannelItem item : buildRecentVodItems()) {
            if (item != null && getVodResumePosition(item.id) > 30_000L && added.add(item.id)) {
                items.add(item);
            }
        }
        for (ChannelItem item : buildVodProgressItems()) {
            if (item != null && added.add(item.id)) {
                items.add(item);
            }
        }
        List<ChannelItem> continuing = withHboContinue(items);
        continuing.sort((a, b) -> Long.compare(vodLastViewed(b), vodLastViewed(a)));
        return continuing;
    }

    private long vodLastViewed(ChannelItem item) {
        if (item.id.startsWith("hbomax:")) {
            HboWatchHistory.Entry entry = hboHistory().get(item.id);
            return entry == null ? 0L : entry.updated;
        }
        return vodResumeUpdatedAt.getOrDefault(item.id, 0L);
    }

    private List<ChannelItem> buildRecentVodItems() {
        List<ChannelItem> items = new ArrayList<>();
        Set<String> added = new HashSet<>();
        List<RecentChannelsStore.RecentChannelItem> recents = recentChannelsStore == null ? new ArrayList<>() : recentChannelsStore.getItems();
        for (RecentChannelsStore.RecentChannelItem recent : recents) {
            if (recent == null || recent.channelId == null || !added.add(recent.channelId)) {
                continue;
            }
            ChannelItem item = findChannelItemById(recent.channelId);
            if (item != null && item.isVod && !shouldHideProtectedItem(item)) {
                items.add(item);
            }
            if (items.size() >= 80) {
                break;
            }
        }
        return items;
    }

    private List<ChannelItem> buildVodItemsByFilter(String vodFilterKey, boolean includeAdult) {
        List<ChannelItem> items = new ArrayList<>();
        for (ChannelItem item : allChannels) {
            if (item == null || !item.isVod || shouldHideProtectedItem(item)) {
                continue;
            }
            if (!includeAdult && item.isAdultVod) {
                continue;
            }
            if (vodFilterKey != null && !vodFilterKey.equals(item.vodFilterKey)) {
                continue;
            }
            items.add(item);
        }
        sortVodLibraryItems(items);
        return items;
    }

    private List<ChannelItem> buildMovistarVodItems() {
        if (cachedMovistarVodItemsValid) {
            return new ArrayList<>(cachedMovistarVodItems);
        }
        List<ChannelItem> items = new ArrayList<>();
        Set<String> added = new HashSet<>();
        for (ChannelItem item : allChannels) {
            if (item == null || !item.isVod || item.isAdultVod || shouldHideProtectedItem(item)) {
                continue;
            }
            String filterKey = item.vodFilterKey == null ? "" : item.vodFilterKey.toLowerCase(Locale.ROOT);
            String platform = item.platformName == null ? "" : item.platformName.toLowerCase(Locale.ROOT);
            if ((filterKey.contains("movistar") || platform.contains("movistar")) && added.add(item.id)) {
                items.add(item);
            }
        }
        sortVodLibraryItems(items);
        cachedMovistarVodItems.clear();
        cachedMovistarVodItems.addAll(items);
        cachedMovistarVodItemsValid = true;
        return items;
    }

    private void invalidateVodDerivedCaches() {
        vodOriginLogos.clear();
        cachedMovistarVodItems.clear();
        cachedMovistarVodItemsValid = false;
    }

    private List<ChannelItem> buildVodProgressItems() {
        List<ChannelItem> items = new ArrayList<>();
        for (Map.Entry<String, Long> entry : vodResumePositions.entrySet()) {
            if (entry == null || entry.getKey() == null || entry.getValue() == null || entry.getValue() <= 30_000L) {
                continue;
            }
            ChannelItem item = findChannelItemById(entry.getKey());
            if (item == null) item = vodResumeItems.get(entry.getKey());
            if (item != null && item.isVod && !shouldHideProtectedItem(item)) {
                items.add(item);
            }
        }
        sortVodLibraryItems(items);
        return items;
    }

    private List<ChannelItem> buildVodNotStartedItems() {
        List<ChannelItem> items = new ArrayList<>();
        for (ChannelItem item : allChannels) {
            if (item == null || !item.isVod || shouldHideProtectedItem(item) || item.isAdultVod || getVodResumePosition(item.id) > 0L) {
                continue;
            }
            items.add(item);
            if (items.size() >= 120) {
                break;
            }
        }
        sortVodLibraryItems(items);
        return items;
    }

    private void sortVodLibraryItems(List<ChannelItem> items) {
        if (items == null) {
            return;
        }
        items.sort((left, right) -> {
            long leftProgress = getVodResumePosition(left == null ? null : left.id);
            long rightProgress = getVodResumePosition(right == null ? null : right.id);
            int progressCompare = Long.compare(rightProgress, leftProgress);
            if (progressCompare != 0) {
                return progressCompare;
            }
            String leftPlatform = left == null || left.platformName == null ? "" : left.platformName;
            String rightPlatform = right == null || right.platformName == null ? "" : right.platformName;
            int platformCompare = leftPlatform.compareToIgnoreCase(rightPlatform);
            if (platformCompare != 0) {
                return platformCompare;
            }
            return displayName(left).compareToIgnoreCase(displayName(right));
        });
    }

