    private void showQuickChannelListDialog(String title, String subtitle, List<ChannelItem> items, String emptyMessage, QuickChannelSelectionAction action, Runnable onBack, List<ZapActionItem> panelActions,String pickerKey) {
        QuickChannelDialogUiFactory.Host dialogHost = buildQuickChannelDialogUiHost();
        if (!QuickChannelDialogUiFactory.hasItems(items)) {
            showStatus(QuickChannelDialogUiFactory.emptyMessage(emptyMessage, dialogHost));
            return;
        }
        prepareModalSurface();
        if (touchControlsBar != null) {
            touchControlsBar.setVisibility(View.GONE);
        }
        prefetchChannelLogos(items, SEARCH_LOGO_PREFETCH_LIMIT, 42, 42);
        ComposeView quickChannelListComposeView = new ComposeView(this);
        attachDialogViewTreeOwners(quickChannelListComposeView);
        final Dialog[] dialogHolder = new Dialog[1];
        final boolean[] navigationHandled = {false};
        Runnable panelBackAction = onBack == null ? null : () -> {
            navigationHandled[0] = true;
            dismissModalForNextAction(dialogHolder[0], onBack);
        };
        List<ZapActionItem> modalPanelActions = new ArrayList<>();
        if (panelActions != null) {
            for (ZapActionItem panelAction : panelActions) {
                if (panelAction == null) {
                    continue;
                }
                Runnable wrappedClick = panelAction.onClick == null
                        ? null
                        : () -> dismissModalForNextAction(dialogHolder[0], panelAction.onClick);
                Runnable wrappedLongClick = panelAction.onLongClick == null
                        ? null
                        : () -> dismissModalForNextAction(dialogHolder[0], panelAction.onLongClick);
                modalPanelActions.add(new ZapActionItem(
                        panelAction.label,
                        panelAction.enabled,
                        panelAction.highlighted,
                        panelAction.selected,
                        wrappedClick,
                        wrappedLongClick
                ));
            }
        }
        QuickChannelListUiModel quickModel = buildQuickChannelListUiModel(
                title,
                subtitle == null ? QuickChannelDialogUiFactory.subtitle(items, dialogHost) : subtitle,
                modalPanelActions,
                items,
                dialogHolder,
                action,
                panelBackAction
        );
        if (pickerKey != null) {
            quickModel.rememberedChannelId = multiViewPickerPositions.getOrDefault(pickerKey, "");
            quickModel.onChannelFocused = id -> multiViewPickerPositions.put(pickerKey,id);
        }
        QuickChannelListComposeBinder.bind(quickChannelListComposeView, quickModel, (imageView, item) -> {
            if (imageView == null || item == null) {
                return;
            }
            if (item.vod) {
                bindVodPosterList(imageView, item.logoUrl);
            } else {
                bindChannelLogo(imageView, item.logoUrl, item.channelName, 42, 42);
            }
        });
        Dialog dialog = ComposeDialogHost.showFullscreen(this, quickChannelListComposeView, () -> {
            if (onBack != null) {
                modalReturnAction = onBack;
            }
        }, this::handleModalDismissed);
        dialogHolder[0] = dialog;
        if (onBack != null) {
            dialog.setOnKeyListener((ignored, keyCode, event) -> {
                if (keyCode == KeyEvent.KEYCODE_BACK && event.getAction() == KeyEvent.ACTION_UP && !navigationHandled[0]) {
                    panelBackAction.run();
                    return true;
                }
                return false;
            });
        }
        handleModalShown();
    }

