    private String routeDiagnosticTone(String routeLabel) {
        String normalized = safeLower(routeLabel);
        if (normalized.contains("directo")) {
            return "ok";
        }
        if (normalized.contains("proxy") || normalized.contains("compat")) {
            return "warn";
        }
        return "";
    }

