    private void exitRecordingToPreviousChannel() {
        rememberCurrentRecordingPosition();
        String channelId = currentPlaybackReturnChannelId;
        currentPlaybackRecordingId = null;
        currentPlaybackReturnChannelId = null;
        if (channelId != null && !channelId.trim().isEmpty()) {
            ChannelItem returnChannel = findChannelItemById(channelId);
            if (returnChannel != null) {
                int visibleIndex = findChannelIndexById(channelId);
                if (visibleIndex >= 0) {
                    tuneToIndex(visibleIndex, true);
                    return;
                }
                playChannelItem(returnChannel, true);
                return;
            }
        }
        openRecordingsBrowser();
    }

    private void rememberCurrentRecordingPosition() {
        if (playerController == null || currentPlaybackRecordingId == null || currentPlaybackRecordingId.trim().isEmpty()) {
            return;
        }
        long positionMs = playerController.getCurrentPlaybackPosition();
        if (positionMs <= 0L) {
            return;
        }
        PlayerController.PlaybackSeekState seekState = playerController.getPlaybackSeekState();
        long durationMs = seekState == null ? 0L : Math.max(0L, seekState.endMs - seekState.startMs);
        long retainedDuration = durationMs > 60_000L ? durationMs : recordingResumeDurations.getOrDefault(currentPlaybackRecordingId, 0L);
        if (recordingResumePositions.getOrDefault(currentPlaybackRecordingId, 0L) == positionMs
                && recordingResumeDurations.getOrDefault(currentPlaybackRecordingId, 0L) == retainedDuration) {
            if (ownsResumeProgressSession()) resumeProgressStore.retry(resumeProgressSession, PREF_RECORDING_RESUME_POSITIONS);
            return;
        }
        recordingResumePositions.put(currentPlaybackRecordingId, positionMs);
        if (durationMs > 60_000L) {
            recordingResumeDurations.put(currentPlaybackRecordingId, durationMs);
        }
        recordingResumeUpdatedAt.put(currentPlaybackRecordingId, System.currentTimeMillis());
        saveRecordingResumePositions();
        scheduleUserPreferencePush();
    }

    private long getRecordingResumePosition(String recordingId) {
        if (recordingId == null || recordingId.trim().isEmpty()) {
            return 0L;
        }
        Long value = recordingResumePositions.get(recordingId);
        return value == null ? 0L : Math.max(0L, value);
    }

    private void clearRecordingResumePosition(String recordingId) {
        if (recordingId == null || recordingId.trim().isEmpty()) {
            return;
        }
        if (recordingResumePositions.remove(recordingId) != null) {
            recordingResumeDurations.remove(recordingId);
            recordingResumeUpdatedAt.remove(recordingId);
            saveRecordingResumePositions();
            scheduleUserPreferencePush();
        }
    }

    private void rememberCurrentVodPosition() {
        if (currentPlaybackVodId != null && currentPlaybackVodId.equals(endedVodId)) return;
        if (playerController == null || currentPlaybackVodId == null || currentPlaybackVodId.trim().isEmpty()) {
            return;
        }
        long positionMs = playerController.getCurrentPlaybackPosition();
        if (positionMs <= 0L) {
            return;
        }
        if(currentPlaybackVodId.startsWith("hbomax:")) {
            if(hboHistory().record(currentPlaybackVodId,positionMs,playerController.getCurrentVodDurationMs(),System.currentTimeMillis()))
                resolveNextHboEpisode(currentPlaybackVodId);
            saveHboHistory();scheduleUserPreferencePush();return;
        }
        long detectedDuration = playerController.getCurrentVodDurationMs();
        long retainedDuration = detectedDuration > 60_000L ? detectedDuration : vodResumeDurations.getOrDefault(currentPlaybackVodId, 0L);
        if (vodResumePositions.getOrDefault(currentPlaybackVodId, 0L) == positionMs
                && vodResumeDurations.getOrDefault(currentPlaybackVodId, 0L) == retainedDuration) {
            if (ownsResumeProgressSession()) resumeProgressStore.retry(resumeProgressSession, PREF_VOD_RESUME_POSITIONS);
            return;
        }
        vodResumePositions.put(currentPlaybackVodId, positionMs);
        if (detectedDuration > 60_000L) vodResumeDurations.put(currentPlaybackVodId, detectedDuration);
        vodResumeUpdatedAt.put(currentPlaybackVodId, System.currentTimeMillis());
        ChannelItem item = currentPlaybackTransientItem;
        if (item == null || !currentPlaybackVodId.equals(item.id)) {
            item = findChannelItemById(currentPlaybackVodId);
        }
        rememberVodResumeItem(item);
        invalidateVodDerivedCaches();
        saveVodResumePositions();
    }

    private long getVodResumePosition(String vodId) {
        if (vodId == null || vodId.trim().isEmpty()) {
            return 0L;
        }
        if(vodId.startsWith("hbomax:")){HboWatchHistory.Entry e=hboHistory().get(vodId);return e==null||e.completed?0L:e.position;}
        Long value = vodResumePositions.get(vodId);
        return value == null ? 0L : Math.max(0L, value);
    }

    private void clearVodResumePosition(String vodId) {
        if (vodId == null || vodId.trim().isEmpty()) {
            return;
        }
        if (vodResumePositions.remove(vodId) != null) {
            vodResumeDurations.remove(vodId);
            vodResumeUpdatedAt.remove(vodId);
            vodResumeItems.remove(vodId);
            if (catalogSnapshotStore != null) {
                catalogSnapshotStore.removeVodResumeItem(vodId);
            }
            invalidateVodDerivedCaches();
            saveVodResumePositions();
        }
    }

    private void loadVodResumePositions() {
        vodResumePositions.clear();
        vodResumeDurations.clear();
        vodResumeUpdatedAt.clear();
        invalidateVodDerivedCaches();
        if (prefs == null) {
            return;
        }
        ResumeProgressStore.Snapshot latest = resumeProgressStore.latest(resumeProgressSession, PREF_VOD_RESUME_POSITIONS);
        if (latest != null) {
            latest.restore(vodResumePositions, vodResumeDurations, vodResumeUpdatedAt);
            return;
        }
        String raw = prefs.getString(PREF_VOD_RESUME_POSITIONS, "");
        if (raw == null || raw.trim().isEmpty()) {
            return;
        }
        try {
            JSONObject json = new JSONObject(raw);
            java.util.Iterator<String> keys = json.keys();
            while (keys.hasNext()) {
                String key = keys.next();
                Object rawValue = json.opt(key);
                if (rawValue instanceof JSONObject) {
                    JSONObject entry = (JSONObject) rawValue;
                    vodResumePositions.put(key, Math.max(0L, entry.optLong("position", 0L)));
                    vodResumeDurations.put(key, Math.max(0L, entry.optLong("duration", 0L)));
                    vodResumeUpdatedAt.put(key, Math.max(0L, entry.optLong("updated_at", 0L)));
                } else {
                    long position = Math.max(0L, json.optLong(key, 0L));
                    if (position > 0L) {
                        vodResumePositions.put(key, position);
                        // Legacy entries did not carry a timestamp. Mark them as local now so
                        // an older empty server payload cannot erase freshly watched Plex VOD.
                        vodResumeUpdatedAt.put(key, System.currentTimeMillis());
                    }
                }
            }
        } catch (Exception e) {
            Log.w(TAG, "failed to load vod resume positions", e);
        }
    }

    private void saveVodResumePositions() {
        saveVodResumePositions(true);
    }

    private void saveVodResumePositions(boolean scheduleSync) {
        if (prefs == null || !ownsResumeProgressSession()) return;
        try {
            Map<String, Long> durations = new HashMap<>();
            for (String id : vodResumePositions.keySet()) {
                if (id != null && !id.trim().isEmpty()) durations.put(id, vodResumeDuration(id));
            }
            ResumeProgressStore.Snapshot snapshot = ResumeProgressStore.Snapshot.capture(false,
                    vodResumePositions, durations, vodResumeUpdatedAt, System.currentTimeMillis());
            resumeProgressStore.submit(resumeProgressSession, PREF_VOD_RESUME_POSITIONS, snapshot);
            if (scheduleSync) scheduleUserPreferencePush();
        } catch (Exception e) {
            Log.w(TAG, "failed to queue vod resume positions");
        }
    }

    private boolean ownsResumeProgressSession() {
        if (resumeProgressStore == null || !resumeProgressStore.current(resumeProgressSession)) return false;
        String scope = catalogSnapshotStore == null ? "" : catalogSnapshotStore.getUserScope();
        if (!java.util.Objects.equals(scope, resumeProgressSession.scope))
            resumeProgressSession = resumeProgressStore.openSession(scope);
        return true;
    }

    static boolean shouldPreserveLocalVodProgress(long localTime, long remoteTime, boolean remoteHasEntry, long durationMs) {
        // An absent entry cannot acknowledge a local bookmark we could not upload
        // because its duration was unknown. Explicit remote entries still win.
        return localTime > remoteTime || (!remoteHasEntry && durationMs <= 60_000L);
    }

    private long vodResumeDuration(String id) {
        ChannelItem item = findChannelItemById(id);
        if (item == null) item = vodResumeItems.get(id);
        return Math.max(vodResumeDurations.getOrDefault(id, 0L), item == null ? 0L : item.vodDurationSeconds * 1000L);
    }

    private void rememberVodResumeItem(ChannelItem item) {
        if (item == null || !item.isVod || item.id.isEmpty()) {
            return;
        }
        boolean alreadyCached = vodResumeItems.containsKey(item.id);
        vodResumeItems.put(item.id, item);
        if (!alreadyCached && catalogSnapshotStore != null) {
            catalogSnapshotStore.saveVodResumeItem(item);
        }
    }

    private void loadGlobalSearchRecents() {
        globalSearchRecents.clear();
        if (prefs == null) {
            return;
        }
        String raw = prefs.getString(PREF_GLOBAL_SEARCH_RECENTS, "");
        if (raw == null || raw.trim().isEmpty()) {
            return;
        }
        try {
            org.json.JSONArray array = new org.json.JSONArray(raw);
            for (int i = 0; i < array.length(); i++) {
                String value = cleanText(array.optString(i, ""));
                if (!value.isEmpty() && !globalSearchRecents.contains(value)) {
                    globalSearchRecents.add(value);
                }
                if (globalSearchRecents.size() >= 8) {
                    break;
                }
            }
        } catch (Exception e) {
            Log.w(TAG, "failed to load global search recents", e);
        }
    }

    private void rememberGlobalSearchQuery(String query) {
        String value = cleanText(query);
        if (value.length() < 2 || prefs == null) {
            return;
        }
        globalSearchRecents.remove(value);
        globalSearchRecents.add(0, value);
        while (globalSearchRecents.size() > 8) {
            globalSearchRecents.remove(globalSearchRecents.size() - 1);
        }
        saveGlobalSearchRecents();
    }

    private void saveGlobalSearchRecents() {
        if (prefs == null) {
            return;
        }
        try {
            org.json.JSONArray array = new org.json.JSONArray();
            for (String item : globalSearchRecents) {
                if (item != null && !item.trim().isEmpty()) {
                    array.put(item.trim());
                }
            }
            prefs.edit().putString(PREF_GLOBAL_SEARCH_RECENTS, array.toString()).apply();
        } catch (Exception e) {
            Log.w(TAG, "failed to save global search recents", e);
        }
    }

    private void loadLearnedPlaybackModes() {
        learnedPlaybackModesByChannelId.clear();
        learnedPlaybackModesUpdatedAt.clear();
        if (prefs == null) {
            return;
        }
        String raw = prefs.getString(PREF_PLAYBACK_LEARNED_MODES, "");
        if (raw == null || raw.trim().isEmpty()) {
            return;
        }
        try {
            JSONObject json = new JSONObject(raw);
            JSONObject timestamps;
            try {
                timestamps = new JSONObject(prefs.getString(PREF_PLAYBACK_LEARNED_AT, "{}"));
            } catch (Exception ignored) {
                timestamps = new JSONObject();
            }
            long now = System.currentTimeMillis();
            java.util.Iterator<String> keys = json.keys();
            while (keys.hasNext()) {
                String key = keys.next();
                long learnedAt = timestamps.optLong(key, now);
                if (PlaybackRouteLearningPolicy.isExpired(learnedAt, now)) {
                    continue;
                }
                String mode = sanitizePlaybackMode(json.optString(key, PlaybackModeStore.MODE_AUTO));
                if (!PlaybackModeStore.MODE_AUTO.equals(mode)) {
                    learnedPlaybackModesByChannelId.put(key, mode);
                    learnedPlaybackModesUpdatedAt.put(key, learnedAt);
                }
            }
        } catch (Exception e) {
            Log.w(TAG, "failed to load learned playback modes", e);
        }
        // Persist migration dates once so legacy entries also expire.
        saveLearnedPlaybackModes();
    }

    private void expireLearnedPlaybackModes() {
        long now = System.currentTimeMillis();
        boolean changed = false;
        java.util.Iterator<String> keys = learnedPlaybackModesByChannelId.keySet().iterator();
        while (keys.hasNext()) {
            String key = keys.next();
            Long learnedAt = learnedPlaybackModesUpdatedAt.get(key);
            if (learnedAt == null || PlaybackRouteLearningPolicy.isExpired(learnedAt, now)) {
                keys.remove();
                learnedPlaybackModesUpdatedAt.remove(key);
                changed = true;
            }
        }
        if (changed) {
            saveLearnedPlaybackModes();
        }
    }

    private void saveLearnedPlaybackModes() {
        if (prefs == null) {
            return;
        }
        try {
            JSONObject json = new JSONObject();
            JSONObject timestamps = new JSONObject();
            learnedPlaybackModesUpdatedAt.keySet().retainAll(learnedPlaybackModesByChannelId.keySet());
            for (Map.Entry<String, String> entry : learnedPlaybackModesByChannelId.entrySet()) {
                if (entry.getKey() == null || entry.getKey().trim().isEmpty()) {
                    continue;
                }
                String mode = sanitizePlaybackMode(entry.getValue());
                if (!PlaybackModeStore.MODE_AUTO.equals(mode)) {
                    json.put(entry.getKey(), mode);
                    Long learnedAt = learnedPlaybackModesUpdatedAt.get(entry.getKey());
                    timestamps.put(entry.getKey(), learnedAt == null ? System.currentTimeMillis() : learnedAt);
                }
            }
            prefs.edit().putString(PREF_PLAYBACK_LEARNED_MODES, json.toString())
                    .putString(PREF_PLAYBACK_LEARNED_AT, timestamps.toString()).apply();
        } catch (Exception e) {
            Log.w(TAG, "failed to save learned playback modes", e);
        }
    }

    private void loadRecordingResumePositions() {
        recordingResumePositions.clear();
        recordingResumeDurations.clear();
        recordingResumeUpdatedAt.clear();
        if (prefs == null) {
            return;
        }
        ResumeProgressStore.Snapshot latest = resumeProgressStore.latest(resumeProgressSession, PREF_RECORDING_RESUME_POSITIONS);
        if (latest != null) {
            latest.restore(recordingResumePositions, recordingResumeDurations, recordingResumeUpdatedAt);
            return;
        }
        String raw = prefs.getString(PREF_RECORDING_RESUME_POSITIONS, "");
        if (raw == null || raw.trim().isEmpty()) {
            return;
        }
        try {
            JSONObject json = new JSONObject(raw);
            java.util.Iterator<String> keys = json.keys();
            while (keys.hasNext()) {
                String key = keys.next();
                JSONObject row = json.optJSONObject(key);
                if (row == null) {
                    recordingResumePositions.put(key, Math.max(0L, json.optLong(key, 0L)));
                    continue;
                }
                recordingResumePositions.put(key, Math.max(0L, row.optLong("position_ms", 0L)));
                recordingResumeDurations.put(key, Math.max(0L, row.optLong("duration_ms", 0L)));
                recordingResumeUpdatedAt.put(key, Math.max(0L, row.optLong("updated_at", 0L)));
            }
        } catch (Exception e) {
            Log.w(TAG, "failed to load recording resume positions", e);
        }
    }

    private void saveRecordingResumePositions() {
        if (prefs == null || !ownsResumeProgressSession()) return;
        try {
            resumeProgressStore.submit(resumeProgressSession, PREF_RECORDING_RESUME_POSITIONS,
                    ResumeProgressStore.Snapshot.capture(true, recordingResumePositions,
                            recordingResumeDurations, recordingResumeUpdatedAt, System.currentTimeMillis()));
        } catch (Exception e) {
            Log.w(TAG, "failed to queue recording resume positions");
        }
    }

